# Ver228: DB保存時刻・画面表示時刻を日本時間へ統一。
_V228_JST = ZoneInfo("Asia/Tokyo")

def _v228_now_jst_iso() -> str:
    return datetime.now(_V228_JST).isoformat(timespec="seconds")

def _v228_format_saved_time(value) -> str:
    """新規のJST時刻と、旧版のUTC時刻を日本時間表示へそろえる。"""
    text = str(value or "").strip()
    if not text:
        return ""
    try:
        dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
        # 旧DBのタイムゾーンなし値は、従来の保存仕様に合わせてUTCとして扱う。
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(_V228_JST).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return text.replace("T", " ")[:19]


# Ver227: 発走前除外と発走後事故を分離。
# Ver225: 欠車・発走前除外は「事故」ではなく事前除外として扱う。
# 比較用の行は補うが、事故判定に使われる欄へ「欠車」等の語を残さない。


# Ver229: 壁で詰まる時間と前残りを、イベントシミュレーション後の着順分布へ再配分する。
# Ver230: 6周内蔵型ベータ。過去周回結果と直接対戦履歴を事前学習して各試行へ反映。
# engine.pyを差し替えずに使えるよう、三連単カウントを穏やかに補正し、他券種も整合再集計する。
def _v229_num(value, default=0.0) -> float:
    try:
        n = float(value)
        return n if pd.notna(n) else float(default)
    except Exception:
        return float(default)


def _v229_wall_profile(df: pd.DataFrame, entries: pd.DataFrame) -> dict[int, dict]:
    if not isinstance(df, pd.DataFrame) or df.empty:
        return {}
    work = df.copy()
    car_col = "車" if "車" in work.columns else ("車番" if "車番" in work.columns else None)
    if not car_col:
        return {}
    work["_car"] = pd.to_numeric(work[car_col], errors="coerce")
    work = work.dropna(subset=["_car"]).copy()
    work["_car"] = work["_car"].astype(int)

    entry_map = {}
    if isinstance(entries, pd.DataFrame) and not entries.empty:
        ec = "車番" if "車番" in entries.columns else ("車" if "車" in entries.columns else None)
        if ec:
            for _, r in entries.iterrows():
                try:
                    entry_map[int(r[ec])] = r
                except Exception:
                    pass

    handicaps = {}
    for _, r in work.iterrows():
        car = int(r["_car"])
        er = entry_map.get(car)
        h = None
        for source in (r, er):
            if source is None:
                continue
            for key in ("ハンデ", "H", "handicap"):
                if key in source.index:
                    m = re.search(r"-?\d+", str(source.get(key, "")))
                    if m:
                        h = int(m.group())
                        break
            if h is not None:
                break
        handicaps[car] = int(h or 0)

    cars = sorted(handicaps, key=lambda c: (handicaps[c], c))
    if not cars:
        return {}
    min_h, max_h = min(handicaps.values()), max(handicaps.values())
    spread = max(10.0, float(max_h - min_h))
    same_counts = {c: sum(1 for x in cars if handicaps[x] == handicaps[c]) for c in cars}

    raw_break = {}
    for _, r in work.iterrows():
        car = int(r["_car"])
        vals = []
        for key in ("混戦突破適性", "展開適性点", "実戦能力点", "スタート伸び指数"):
            if key in r.index:
                vals.append(_v229_num(r.get(key), 0.0))
        raw_break[car] = sum(vals) / len(vals) if vals else 0.0
    if raw_break:
        lo, hi = min(raw_break.values()), max(raw_break.values())
    else:
        lo = hi = 0.0

    profile = {}
    for pos, car in enumerate(cars):
        h = handicaps[car]
        same_ahead = sum(1 for x in cars[:pos] if handicaps[x] == h)
        lower_ahead = sum(1 for x in cars[:pos] if handicaps[x] < h)
        density = max(0, same_counts[car] - 1) / max(1, len(cars) - 1)
        # 同ハンデの外枠、前ハンデ車の多さを壁リスクへ。上限を抑え、極端な改変を避ける。
        wall_risk = min(1.0, 0.16 * same_ahead + 0.085 * lower_ahead + 0.34 * density)
        bnorm = 0.5 if hi <= lo else (raw_break.get(car, lo) - lo) / (hi - lo)
        breakthrough = min(1.0, max(0.0, 0.25 + 0.75 * bnorm))
        frontness = 1.0 - (h - min_h) / spread
        inner_same = 1.0 - same_ahead / max(1, same_counts[car] - 1) if same_counts[car] > 1 else 0.5
        escape = max(0.0, min(1.0, 0.62 * frontness + 0.38 * inner_same))
        effective_loss = wall_risk * (1.0 - 0.68 * breakthrough)
        profile[car] = {
            "handicap": h, "wall_risk": wall_risk, "breakthrough": breakthrough,
            "escape": escape, "effective_loss": effective_loss, "initial_pos": pos + 1,
        }
    return profile


def _v229_apply_wall_distribution(df: pd.DataFrame, bets: dict, entries: pd.DataFrame, trials: int):
    if not isinstance(bets, dict) or not isinstance(bets.get("三連単"), dict) or not bets.get("三連単"):
        return df, bets, {"enabled": False, "reason": "三連単分布なし"}
    profile = _v229_wall_profile(df, entries)
    if len(profile) < 3:
        return df, bets, {"enabled": False, "reason": "壁判定データ不足"}

    tri = bets["三連単"]
    weighted = {}
    for combo, count in tri.items():
        try:
            a, b, c = map(int, combo)
            pa, pb, pc = profile[a], profile[b], profile[c]
        except Exception:
            weighted[combo] = float(count)
            continue
        # 先頭候補は逃げやすさを加点。後方候補は壁ロスを減点。
        # ただし捌き力が高い選手は減点を大幅に緩和する。
        factor = 1.0
        factor *= 1.0 + 0.16 * pa["escape"] - 0.12 * pa["effective_loss"]
        factor *= 1.0 - 0.11 * pb["effective_loss"]
        factor *= 1.0 - 0.07 * pc["effective_loss"]
        # 前ハンデ車が上位に残る自然な展開を少し優遇。
        if pa["handicap"] < pb["handicap"]:
            factor *= 1.045
        if pb["handicap"] <= pc["handicap"]:
            factor *= 1.015
        factor = max(0.76, min(1.24, factor))
        weighted[(a, b, c)] = max(0.0, float(count) * factor)

    total_w = sum(weighted.values())
    if total_w <= 0:
        return df, bets, {"enabled": False, "reason": "再配分失敗"}
    target = max(1, int(trials))
    scaled = {k: v / total_w * target for k, v in weighted.items()}
    ints = {k: int(v) for k, v in scaled.items()}
    remain = target - sum(ints.values())
    if remain > 0:
        for k, _ in sorted(scaled.items(), key=lambda kv: kv[1] - int(kv[1]), reverse=True)[:remain]:
            ints[k] += 1

    new_bets = dict(bets)
    new_bets["三連単"] = ints
    trifuku, nitan, nifuku = {}, {}, {}
    for (a, b, c), cnt in ints.items():
        trifuku[tuple(sorted((a, b, c)))] = trifuku.get(tuple(sorted((a, b, c))), 0) + cnt
        nitan[(a, b)] = nitan.get((a, b), 0) + cnt
        nifuku[tuple(sorted((a, b)))] = nifuku.get(tuple(sorted((a, b))), 0) + cnt
    new_bets["三連複"] = trifuku
    new_bets["2連単"] = nitan
    new_bets["2連複"] = nifuku

    out_df = df.copy()
    car_col = "車" if "車" in out_df.columns else ("車番" if "車番" in out_df.columns else None)
    if car_col:
        out_df["壁リスク"] = out_df[car_col].map(lambda x: profile.get(int(x), {}).get("wall_risk", 0.0) * 100 if pd.notna(x) else 0.0)
        out_df["壁突破力"] = out_df[car_col].map(lambda x: profile.get(int(x), {}).get("breakthrough", 0.0) * 100 if pd.notna(x) else 0.0)
        out_df["前残り指数"] = out_df[car_col].map(lambda x: profile.get(int(x), {}).get("escape", 0.0) * 100 if pd.notna(x) else 0.0)
        out_df["壁ロス推定"] = out_df[car_col].map(lambda x: profile.get(int(x), {}).get("effective_loss", 0.0) * 100 if pd.notna(x) else 0.0)
    top_risk = sorted(profile.items(), key=lambda kv: kv[1]["effective_loss"], reverse=True)[:3]
    audit = {
        "enabled": True,
        "high_risk": [{"car": c, **v} for c, v in top_risk],
        "message": "同ハンデ密集・前車数・捌き力から、壁で失う時間と前残りを着順分布へ穏やかに反映",
    }
    return out_df, new_bets, audit



# Ver230 beta: 壁・飛び出し・追い抜きを6周イベント本体に組み込む。
# 既存の能力シミュレーションを土台として、過去周回結果と直接対戦履歴を事前学習に利用する。
def _v230_db_path() -> str:
    try:
        return str(engine.DB_PATH)
    except Exception:
        return "autorace_players.sqlite3"


def _v230_norm_name(value) -> str:
    return re.sub(r"[\s　]+", "", str(value or "")).strip()


def _v230_hist_profiles(venue: str, names: list[str]) -> dict[str, dict]:
    """過去結果から1周目飛び出し・前残り・追い上げ・抜き実績を縮小推定する。"""
    out = {n: {"starts": 0.0, "first_gain": 0.0, "hold": 0.5, "chase": 0.5, "overtake": 0.5, "sample": 0} for n in names}
    if not names:
        return out
    try:
        con = sqlite3.connect(_v230_db_path(), timeout=15)
        placeholders = ",".join("?" for _ in names)
        rows = con.execute(
            f"""
            SELECT p.player_name, lf.first_lap_pos, lf.final_pos, lf.net_gain,
                   lf.overtakes, lf.passed_by, lf.lead_laps, r.venue
            FROM lap_features lf
            JOIN race_entries re ON re.race_id=lf.race_id AND re.car_no=lf.car_no
            LEFT JOIN players p ON p.player_id=re.player_id
            JOIN races r ON r.race_id=lf.race_id
            WHERE p.player_name IN ({placeholders})
            """, names
        ).fetchall()
        stats = {n: [] for n in names}
        for name, first, final, gain, overtakes, passed_by, lead_laps, row_venue in rows:
            key = _v230_norm_name(name)
            if key not in stats:
                continue
            stats[key].append((first, final, gain, overtakes, passed_by, lead_laps, row_venue))
        for n, vals in stats.items():
            if not vals:
                continue
            # 開催場一致を1.35倍で重み付け。少数データは0.5へ縮小。
            wsum=0.0; first_gain=0.0; hold=0.0; chase=0.0; over=0.0
            for first, final, gain, ov, pb, lead, rv in vals:
                w=1.35 if venue and str(rv)==str(venue) else 1.0
                first=float(first or 0); final=float(final or first or 0); gain=float(gain or (first-final))
                ov=float(ov or 0); pb=float(pb or 0); lead=float(lead or 0)
                wsum += w
                first_gain += w * max(-4.0, min(4.0, gain))
                hold += w * (1.0 if first>0 and final<=first else 0.0)
                chase += w * (1.0 if first>0 and final<first else 0.0)
                over += w * ((ov+1.0)/(ov+pb+2.0))
            conf=min(1.0, wsum/18.0)
            out[n]={
                "starts": min(1.0, max(0.0, 0.5 + 0.08*(first_gain/max(wsum,1.0)))),
                "first_gain": first_gain/max(wsum,1.0),
                "hold": 0.5 + conf*((hold/max(wsum,1.0))-0.5),
                "chase": 0.5 + conf*((chase/max(wsum,1.0))-0.5),
                "overtake": 0.5 + conf*((over/max(wsum,1.0))-0.5),
                "sample": len(vals),
            }
        con.close()
    except Exception:
        pass
    return out




# Ver241: グランドノートから周回別の追い抜き・被追い抜き後失速を学習する。
def _v240_transition_profiles(venue: str, names: list[str]) -> dict[str, dict]:
    """player_lap_historyから周回別追抜傾向と、抜かれた直後の連鎖後退を縮小推定。"""
    base = {n: {
        "lap_attack": [0.0]*7, "lap_sample": [0]*7,
        "passed_slowdown": 0.18, "cascade_risk": 0.16,
        "pass_momentum": 0.14, "sample": 0,
    } for n in names}
    if not names:
        return base
    try:
        con = sqlite3.connect(_v230_db_path(), timeout=15)
        placeholders = ",".join("?" for _ in names)
        rows = con.execute(
            f"""
            SELECT plh.race_key, plh.player_name, plh.lap_no, plh.position,
                   COALESCE(r.venue, '')
            FROM player_lap_history plh
            LEFT JOIN races r ON r.race_key = plh.race_key
            WHERE REPLACE(REPLACE(plh.player_name,' ',''),'　','') IN ({placeholders})
              AND plh.lap_no IS NOT NULL
            ORDER BY plh.player_name, plh.race_key, plh.lap_no
            """, names
        ).fetchall()
        grouped = {}
        for race_key, name, lap_no, pos, row_venue in rows:
            key = _v230_norm_name(name)
            if key not in base:
                continue
            grouped.setdefault((key, race_key), []).append((int(lap_no or 0), int(pos or 0), str(row_venue or '')))
        accum = {n: {"w":0.0,"passed":0.0,"cascade":0.0,"momentum":0.0,"events":0.0,
                     "lap_gain":[0.0]*7,"lap_w":[0.0]*7} for n in names}
        for (name, _rk), vals in grouped.items():
            vals = sorted(vals)
            if len(vals) < 2:
                continue
            venue_w = 1.35 if venue and vals[0][2] == venue else 1.0
            for idx in range(1, len(vals)):
                lap, pos, _ = vals[idx]
                prev_pos = vals[idx-1][1]
                if prev_pos <= 0 or pos <= 0:
                    continue
                delta = prev_pos - pos  # +なら順位上昇
                li = max(1, min(6, lap))
                accum[name]["lap_gain"][li] += venue_w * max(-3, min(3, delta))
                accum[name]["lap_w"][li] += venue_w
                accum[name]["w"] += venue_w
                if delta > 0:
                    accum[name]["momentum"] += venue_w * min(2, delta)
                elif delta < 0:
                    accum[name]["passed"] += venue_w * min(2, -delta)
                    # 抜かれた次の周にも後退したら連鎖失速。
                    if idx + 1 < len(vals):
                        next_pos = vals[idx+1][1]
                        if next_pos > pos:
                            accum[name]["cascade"] += venue_w * min(2, next_pos-pos)
                accum[name]["events"] += venue_w
        for n, a in accum.items():
            ev = max(1.0, a["events"]); conf = min(1.0, ev/28.0)
            lap_attack=[0.0]*7; lap_sample=[0]*7
            for li in range(1,7):
                lw=a["lap_w"][li]
                lap_sample[li]=int(round(lw))
                if lw>0:
                    # 平均順位上昇を穏やかなlogit加点へ。
                    lap_attack[li]=max(-0.18,min(0.24,(a["lap_gain"][li]/lw)*0.075))*conf
            passed_rate=a["passed"]/ev
            cascade_rate=a["cascade"]/max(1.0,a["passed"])
            momentum_rate=a["momentum"]/ev
            base[n]={
                "lap_attack":lap_attack, "lap_sample":lap_sample,
                "passed_slowdown":0.12 + conf*max(0.0,min(0.22,passed_rate*0.10)),
                "cascade_risk":0.08 + conf*max(0.0,min(0.28,cascade_rate*0.16)),
                "pass_momentum":0.10 + conf*max(0.0,min(0.24,momentum_rate*0.10)),
                "sample":int(round(ev)),
            }
        con.close()
    except Exception:
        pass
    return base

def _v230_matchup_map(names: list[str]) -> dict[tuple[str,str], tuple[float,float]]:
    """直接対戦の追い抜き優位を返す。値は(優位度,信頼度)。"""
    result={}
    if not names:
        return result
    try:
        con=sqlite3.connect(_v230_db_path(), timeout=15)
        rows=con.execute(
            "SELECT player_a_name,player_b_name,shrunk_a_advantage,confidence FROM v152_player_overtake_matchups"
        ).fetchall()
        wanted=set(names)
        for a,b,adv,conf in rows:
            a=_v230_norm_name(a); b=_v230_norm_name(b)
            if a in wanted and b in wanted:
                result[(a,b)]=(float(adv or 0.0), float(conf or 0.0))
                result[(b,a)]=(-float(adv or 0.0), float(conf or 0.0))
        con.close()
    except Exception:
        pass
    return result


def _v230_num(value, default=0.0) -> float:
    """Ver230用の安全な数値変換。既存Ver229実装を再利用する。"""
    return _v229_num(value, default)


def _v230_col_num(row, keys, default=0.0):
    for k in keys:
        try:
            if k in row.index and pd.notna(row[k]):
                return float(row[k])
        except Exception:
            pass
    return float(default)




# Ver248: 実測の周回順位遷移から、開催場・周回別の追い抜き基準を時系列検証して校正する。
_V248_WALL_CALIBRATION_CACHE = {}

def _v248_logit(p: float) -> float:
    p = max(1e-5, min(1.0 - 1e-5, float(p)))
    return float(np.log(p / (1.0 - p)))

def _v248_wall_calibration(db_path: str | None = None) -> dict:
    path = str(db_path or _v230_db_path())
    try:
        stamp = (path, int(Path(path).stat().st_mtime_ns))
    except Exception:
        stamp = (path, 0)
    if stamp in _V248_WALL_CALIBRATION_CACHE:
        return dict(_V248_WALL_CALIBRATION_CACHE[stamp])
    result = {
        "enabled": False, "global_logit": 0.0, "venue_delta": {}, "lap_delta": {},
        "sample_transitions": 0, "validation_transitions": 0, "baseline_logloss": None,
        "calibrated_logloss": None, "reason": "周回履歴不足のため固定係数を使用",
    }
    try:
        with sqlite3.connect(path) as con:
            laps = pd.read_sql_query(
                "SELECT race_key,lap_no,position,car_no FROM result_laps", con
            )
            races = pd.read_sql_query(
                "SELECT race_key,race_date,venue,race_no FROM result_races "
                "WHERE COALESCE(learning_eligible,1)=1", con
            )
        if laps.empty or races.empty:
            _V248_WALL_CALIBRATION_CACHE.clear(); _V248_WALL_CALIBRATION_CACHE[stamp] = dict(result); return result
        for c in ("lap_no", "position", "car_no"):
            laps[c] = pd.to_numeric(laps[c], errors="coerce")
        laps = laps.dropna(subset=["lap_no", "position", "car_no"]).copy()
        laps[["lap_no", "position", "car_no"]] = laps[["lap_no", "position", "car_no"]].astype(int)
        rows = []
        for race_key, g in laps.groupby("race_key"):
            lap_values = sorted(g["lap_no"].unique())
            for lap in lap_values:
                cur = g[g["lap_no"] == lap].sort_values("position")
                nxt = g[g["lap_no"] == lap + 1].sort_values("position")
                if len(cur) < 3 or nxt.empty:
                    continue
                next_pos = dict(zip(nxt["car_no"].astype(int), nxt["position"].astype(int)))
                order = cur["car_no"].astype(int).tolist()
                for i in range(1, len(order)):
                    front, chaser = order[i - 1], order[i]
                    if front not in next_pos or chaser not in next_pos:
                        continue
                    rows.append({
                        "race_key": str(race_key), "lap": int(lap),
                        "passed": int(next_pos[chaser] < next_pos[front]),
                    })
        data = pd.DataFrame(rows)
        if data.empty:
            _V248_WALL_CALIBRATION_CACHE.clear(); _V248_WALL_CALIBRATION_CACHE[stamp] = dict(result); return result
        data = data.merge(races, on="race_key", how="inner")
        data["race_date"] = pd.to_datetime(data["race_date"], errors="coerce")
        data = data.sort_values(["race_date", "race_no", "race_key", "lap"])
        race_order = data[["race_key", "race_date", "race_no"]].drop_duplicates().sort_values(["race_date", "race_no", "race_key"])
        if len(race_order) < 40 or len(data) < 1200:
            result["sample_transitions"] = int(len(data))
            result["reason"] = "時系列検証に必要な周回履歴が不足"
            _V248_WALL_CALIBRATION_CACHE.clear(); _V248_WALL_CALIBRATION_CACHE[stamp] = dict(result); return result
        split = max(25, min(len(race_order) - 12, int(round(len(race_order) * 0.70))))
        train_keys = set(race_order.iloc[:split]["race_key"].astype(str))
        valid_keys = set(race_order.iloc[split:]["race_key"].astype(str))
        train = data[data["race_key"].astype(str).isin(train_keys)].copy()
        valid = data[data["race_key"].astype(str).isin(valid_keys)].copy()
        gp = float((train["passed"].sum() + 20.0) / (len(train) + 40.0))
        gl = _v248_logit(gp)
        def _group_delta(col: str, alpha: float) -> dict:
            agg = train.groupby(col)["passed"].agg(["sum", "count"])
            out = {}
            for key, row in agg.iterrows():
                p = float((row["sum"] + alpha * gp) / (row["count"] + alpha))
                out[key] = float(np.clip(_v248_logit(p) - gl, -0.45, 0.45))
            return out
        venue_delta = _group_delta("venue", 80.0)
        lap_delta = _group_delta("lap", 100.0)
        y = valid["passed"].to_numpy(dtype=float)
        base_p = np.full(len(valid), gp, dtype=float)
        z = np.asarray([gl + venue_delta.get(r["venue"], 0.0) + lap_delta.get(int(r["lap"]), 0.0) for _, r in valid.iterrows()], dtype=float)
        cal_p = 1.0 / (1.0 + np.exp(-z))
        def _ll(prob):
            prob = np.clip(prob, 1e-5, 1 - 1e-5)
            return float(-np.mean(y * np.log(prob) + (1 - y) * np.log(1 - prob)))
        base_ll, cal_ll = _ll(base_p), _ll(cal_p)
        enabled = bool(cal_ll + 0.001 < base_ll)
        result.update({
            "enabled": enabled, "global_logit": gl, "venue_delta": venue_delta if enabled else {},
            "lap_delta": lap_delta if enabled else {}, "sample_transitions": int(len(data)),
            "validation_transitions": int(len(valid)), "baseline_logloss": base_ll,
            "calibrated_logloss": cal_ll,
            "reason": (
                f"時系列検証でLogLossが{base_ll:.4f}→{cal_ll:.4f}へ改善したため反映"
                if enabled else f"時系列検証で改善幅不足（{base_ll:.4f}→{cal_ll:.4f}）のため停止"
            ),
        })
    except Exception as exc:
        result["reason"] = f"校正失敗: {exc}"
    _V248_WALL_CALIBRATION_CACHE.clear(); _V248_WALL_CALIBRATION_CACHE[stamp] = dict(result)
    return result




# Ver253: 実際のグランドノートを1周ごとに照合し、開催場・周回・ハンデ差別の
# 追い抜き発生率を時系列で学習する。予測対象日以降の結果は使わない。
_V251_LAP_ALIGNMENT_CACHE = {}

def _v251_logit(p: float) -> float:
    p = max(0.015, min(0.985, float(p)))
    return float(np.log(p / (1.0 - p)))

def _v251_gap_bucket(gap: int) -> str:
    g = max(0, int(gap or 0))
    if g <= 0: return "0m"
    if g <= 10: return "10m"
    if g <= 20: return "20m"
    return "30m+"

def _v251_lap_alignment_calibration(db_path: str | None, venue: str, cutoff_date: str) -> dict:
    """実測グランドノートの隣接入替を周回・ハンデ差別に縮小推定する。"""
    result = {
        "enabled": False, "sample_pairs": 0, "races": 0,
        "global_pass_rate": 0.0, "lap_bucket_delta": {},
        "lap_pass_rate": {}, "reason": "グランドノート履歴不足",
    }
    if not db_path or not Path(db_path).exists():
        return result
    try:
        stamp=(str(db_path), Path(db_path).stat().st_mtime_ns, str(venue), str(cutoff_date)[:10])
    except Exception:
        stamp=(str(db_path), str(venue), str(cutoff_date)[:10])
    if stamp in _V251_LAP_ALIGNMENT_CACHE:
        return dict(_V251_LAP_ALIGNMENT_CACHE[stamp])
    try:
        con=sqlite3.connect(str(db_path))
        q="""
        SELECT rl.race_key, rr.race_date, rr.venue, rl.lap_no, rl.lap_label,
               rl.position, rl.car_no,
               COALESCE(CAST(REPLACE(REPLACE(re.handicap,'m',''),'Ｍ','') AS INTEGER),0) AS handicap
        FROM result_laps rl
        JOIN result_races rr ON rr.race_key=rl.race_key
        LEFT JOIN races r ON r.race_key=rl.race_key
        LEFT JOIN race_entries re ON re.race_id=r.race_id AND re.car_no=rl.car_no
        WHERE COALESCE(rr.learning_eligible,1)=1
          AND (?='' OR rr.venue=?)
          AND (?='' OR substr(rr.race_date,1,10) < substr(?,1,10))
        ORDER BY rl.race_key, COALESCE(rl.lap_no,999), rl.position
        """
        rows=pd.read_sql_query(q, con, params=(venue,venue,cutoff_date,cutoff_date))
        con.close()
    except Exception as e:
        result["reason"]=f"周回履歴読込失敗: {e}"
        return result
    if rows.empty:
        return result
    events=[]
    race_count=0
    for race_key, grp in rows.groupby('race_key'):
        laps=[]
        for lap_key, lg in grp.groupby(['lap_no','lap_label'], dropna=False, sort=False):
            lg=lg.sort_values('position')
            order=[int(x) for x in lg['car_no'].tolist()]
            hmap={int(r.car_no): int(r.handicap or 0) for r in lg.itertuples()}
            lap_no=lap_key[0]
            try: lap_no=int(lap_no)
            except Exception: lap_no=len(laps)+1
            laps.append((lap_no, order, hmap))
        laps.sort(key=lambda x:x[0])
        if len(laps)<2: continue
        race_count += 1
        for idx in range(1,len(laps)):
            lap_no, cur, hmap=laps[idx]
            prev=laps[idx-1][1]
            cur_pos={c:i for i,c in enumerate(cur)}
            for j in range(1,len(prev)):
                front, chaser=prev[j-1],prev[j]
                if front not in cur_pos or chaser not in cur_pos: continue
                success=1 if cur_pos[chaser] < cur_pos[front] else 0
                gap=max(0, int(hmap.get(chaser,0))-int(hmap.get(front,0)))
                events.append((int(lap_no), _v251_gap_bucket(gap), success))
    if len(events)<120:
        result.update({"sample_pairs":len(events),"races":race_count})
        _V251_LAP_ALIGNMENT_CACHE[stamp]=dict(result)
        return result
    ev=pd.DataFrame(events,columns=['lap','bucket','success'])
    global_rate=float(ev.success.mean())
    deltas={}; lap_rates={}
    for lap, lg in ev.groupby('lap'):
        lap_rates[int(lap)]={"rate":float(lg.success.mean()),"n":int(len(lg))}
        for bucket,bg in lg.groupby('bucket'):
            n=len(bg); raw=float(bg.success.mean())
            # 少数データは全体へ戻す。n=35で半分程度の反映。
            w=n/(n+35.0)
            shrunk=global_rate + w*(raw-global_rate)
            delta=float(np.clip(_v251_logit(shrunk)-_v251_logit(global_rate),-0.42,0.42))
            deltas[f"{int(lap)}|{bucket}"]={"delta":delta,"rate":raw,"n":int(n),"shrunk_rate":shrunk}
    result={
        "enabled":True,"sample_pairs":int(len(ev)),"races":int(race_count),
        "global_pass_rate":global_rate,"lap_bucket_delta":deltas,
        "lap_pass_rate":lap_rates,"reason":"開催日前の実測グランドノートから周回別に学習",
    }
    _V251_LAP_ALIGNMENT_CACHE.clear(); _V251_LAP_ALIGNMENT_CACHE[stamp]=dict(result)
    return result

def _v251_actual_lap_orders(db_path: str | None, meta: dict) -> list[tuple[str, tuple[int,...]]]:
    """同一レースの実測グランドノートが登録済みなら周回順を返す。"""
    if not db_path or not Path(db_path).exists(): return []
    race_date=str((meta or {}).get('開催日') or (meta or {}).get('race_date') or '')[:10]
    venue=str((meta or {}).get('開催場') or (meta or {}).get('venue') or '')
    race_no=str((meta or {}).get('R') or (meta or {}).get('レース') or (meta or {}).get('race_no') or '').strip().replace('R','')
    try:
        con=sqlite3.connect(str(db_path))
        q="""
        SELECT rl.lap_label, rl.lap_no, rl.position, rl.car_no
        FROM result_laps rl JOIN result_races rr ON rr.race_key=rl.race_key
        WHERE substr(rr.race_date,1,10)=? AND rr.venue=?
          AND REPLACE(COALESCE(rr.race_no,''),'R','')=?
        ORDER BY COALESCE(rl.lap_no,999), rl.position
        """
        d=pd.read_sql_query(q,con,params=(race_date,venue,race_no)); con.close()
    except Exception:
        return []
    if d.empty:return []
    out=[]
    for (label,lap_no),g in d.groupby(['lap_label','lap_no'],dropna=False,sort=False):
        out.append((str(label),tuple(int(x) for x in g.sort_values('position').car_no.tolist())))
    return out

def _v251_pairwise_accuracy(pred: tuple[int,...], actual: tuple[int,...]) -> float:
    common=[c for c in actual if c in pred]
    if len(common)<2:return 0.0
    pp={c:i for i,c in enumerate(pred)}; ap={c:i for i,c in enumerate(actual)}
    ok=tot=0
    for i,a in enumerate(common):
        for b in common[i+1:]:
            tot+=1; ok += int((pp[a]<pp[b])==(ap[a]<ap[b]))
    return ok/tot if tot else 0.0



# Ver253: 予測時に代表隊列を保存し、後日登録された実測グランドノートとの差を
# 開催場・周回・ハンデ差別に学習する。結果登録済みレースの再計算はバックテスト扱いで学習除外。
# Ver262 bugfix: 一括補完から通常保存関数が直接呼ばれても NameError にならないよう初期化。
_V253_RECONSTRUCTION_MODE = False
_V252_LAP_RESIDUAL_CACHE = {}

def _v252_ensure_lap_tables(con: sqlite3.Connection) -> None:
    con.execute("""
    CREATE TABLE IF NOT EXISTS v252_lap_prediction_snapshots (
        snapshot_id INTEGER PRIMARY KEY AUTOINCREMENT,
        race_date TEXT NOT NULL,
        venue TEXT NOT NULL,
        race_no TEXT NOT NULL,
        lap_no INTEGER NOT NULL,
        predicted_order TEXT NOT NULL,
        support REAL,
        app_version TEXT NOT NULL,
        is_backtest INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )
    """)
    con.execute("""
    CREATE INDEX IF NOT EXISTS idx_v252_lap_pred_race
    ON v252_lap_prediction_snapshots(race_date, venue, race_no, lap_no, created_at)
    """)

# Ver253 uses the same snapshot schema introduced in Ver252.
# Keep a dedicated wrapper so Ver253 maintenance actions do not fail on a missing symbol.
def _v253_ensure_lap_tables(con: sqlite3.Connection) -> None:
    _v252_ensure_lap_tables(con)

def _v252_save_lap_prediction(db_path: str | None, meta: dict, modal_laps: list[dict], is_backtest: bool, app_version_override: str = '') -> dict:
    """Save one race's representative lap orders and verify that all laps were persisted.

    Ver260 storage fix: this used to fail silently, which made the precision screen show
    fewer races than were actually predicted.  Return a status object so the caller can
    surface failures instead of quietly losing the comparison snapshot.
    """
    status={"ok":False,"saved_laps":0,"expected_laps":len(modal_laps or []),"reason":""}
    if not db_path or not Path(db_path).exists():
        status["reason"]="DBファイルが見つかりません"; return status
    if not modal_laps:
        status["reason"]="代表周回隊列が0件です"; return status
    m=meta or {}
    race_date=str(m.get('開催日') or m.get('日付') or m.get('race_date') or m.get('date') or '')[:10]
    venue=str(m.get('開催場') or m.get('場') or m.get('venue') or m.get('track') or '').strip()
    race_no=str(m.get('R') or m.get('レース') or m.get('レース番号') or m.get('race_no') or m.get('race') or '').strip()
    race_no=re.sub(r'[^0-9]', '', race_no) or race_no.replace('R','').replace('r','').strip()
    status.update({"race_date":race_date,"venue":venue,"race_no":race_no})
    if not race_date or not venue or not race_no:
        status["reason"]=f"レースキー不足: date={race_date or '-'} venue={venue or '-'} R={race_no or '-'}"; return status
    # 再構成は従来どおりVer253の検証材料、通常予測は現在の実行版として保存する。
    app_version=(str(app_version_override or '').strip() or ('Ver253' if _V253_RECONSTRUCTION_MODE else str(globals().get('_V231_APP_VERSION') or 'Ver265')))
    bt=(2 if _V253_RECONSTRUCTION_MODE else (1 if is_backtest else 0))
    status.update({"app_version":app_version,"is_backtest":bt})
    try:
        with sqlite3.connect(str(db_path), timeout=30) as con:
            _v252_ensure_lap_tables(con)
            con.execute("""
                DELETE FROM v252_lap_prediction_snapshots
                WHERE race_date=? AND venue=? AND race_no=? AND app_version=?
            """, (race_date,venue,race_no,app_version))
            inserted=0
            for row in modal_laps:
                lap_no=int(row.get('lap',0) or 0)
                order=str(row.get('order','') or '').strip()
                if lap_no<=0 or not order:
                    continue
                con.execute("""
                    INSERT INTO v252_lap_prediction_snapshots
                    (race_date,venue,race_no,lap_no,predicted_order,support,app_version,is_backtest)
                    VALUES(?,?,?,?,?,?,?,?)
                """, (race_date,venue,race_no,lap_no,order,float(row.get('support',0.0) or 0.0),app_version,bt))
                inserted+=1
            con.commit()
            saved=int(con.execute("""
                SELECT COUNT(*) FROM v252_lap_prediction_snapshots
                WHERE race_date=? AND venue=? AND race_no=? AND app_version=?
            """,(race_date,venue,race_no,app_version)).fetchone()[0])
        status["saved_laps"]=saved
        status["ok"]=(saved==inserted and saved>0)
        status["reason"]=("保存・検証OK" if status["ok"] else f"保存件数不一致: insert={inserted}, db={saved}")
        _V252_LAP_RESIDUAL_CACHE.clear()
        return status
    except Exception as exc:
        status["reason"]=f"{type(exc).__name__}: {exc}"
        return status


def _v260_snapshot_from_saved_view(db_path: str, view: dict, source_app_version: str = '') -> dict:
    """Register lap snapshots from an already-saved prediction without rerunning it.

    Important: preserve the source prediction version. Restoring a Ver253 prediction must
    remain Ver253 and must not create a new Ver260 ROI/prediction record.
    """
    status={"ok":False,"saved_laps":0,"reason":"保存済み予測に周回隊列がありません"}
    if not isinstance(view,dict) or not view:
        status["reason"]="保存済み予測を読み込めません"; return status
    meta=dict(view.get("meta") or {})
    audit=meta.get("6周展開シミュレーション") or meta.get("壁補正監査") or {}
    laps=list(audit.get("predicted_lap_orders") or []) if isinstance(audit,dict) else []
    if not laps:
        return status
    ver=str(source_app_version or view.get("app_version") or "").strip() or str(globals().get('_V231_APP_VERSION') or 'Ver265')
    # This is a stored prediction generated at its original time, not a result-aware rerun.
    return _v252_save_lap_prediction(db_path,meta,laps,False,app_version_override=ver)


def _v260_repair_saved_snapshot_history(db_path: str, app_version: str = '', limit: int = 200) -> dict:
    """Backfill missing lap snapshots directly from saved prediction payloads."""
    out={"checked":0,"repaired_races":0,"repaired_laps":0,"already_ok":0,"no_laps":0,"errors":[],"labels":[]}
    histories=_v231_list_prediction_histories(db_path,max(1,int(limit)))
    target=str(app_version or '').strip()
    for h in histories:
        if target and str(h.get('app_version') or '') != target:
            continue
        out["checked"]+=1
        try:
            view,_,_,hm=_v231_load_prediction_history(db_path,int(h.get('history_id') or 0))
            if not view:
                out["errors"].append(f"履歴ID{h.get('history_id')}: 読込失敗"); continue
            meta=view.get('meta') or {}
            race_date=str(meta.get('開催日') or meta.get('日付') or meta.get('race_date') or meta.get('date') or '')[:10]
            venue=str(meta.get('開催場') or meta.get('場') or meta.get('venue') or meta.get('track') or '').strip()
            race_no=str(meta.get('R') or meta.get('レース') or meta.get('レース番号') or meta.get('race_no') or meta.get('race') or '').strip()
            race_no=re.sub(r'[^0-9]','',race_no) or race_no.replace('R','').replace('r','').strip()
            ver=str(hm.get('app_version') or h.get('app_version') or view.get('app_version') or target or _V231_APP_VERSION)
            if race_date and venue and race_no:
                with sqlite3.connect(str(db_path)) as con:
                    _v252_ensure_lap_tables(con)
                    n=int(con.execute("SELECT COUNT(*) FROM v252_lap_prediction_snapshots WHERE race_date=? AND venue=? AND race_no=? AND app_version=?",(race_date,venue,race_no,ver)).fetchone()[0] or 0)
                if n>=6:
                    out["already_ok"]+=1; continue
            audit=(meta.get('6周展開シミュレーション') or meta.get('壁補正監査') or {}) if isinstance(meta,dict) else {}
            laps=(audit.get('predicted_lap_orders') or []) if isinstance(audit,dict) else []
            if not laps:
                out["no_laps"]+=1; continue
            stt=_v260_snapshot_from_saved_view(db_path,view,ver)
            if stt.get('ok'):
                out["repaired_races"]+=1
                out["repaired_laps"]+=int(stt.get('saved_laps',0) or 0)
                out["labels"].append(str(h.get('race_label') or f"履歴ID{h.get('history_id')}"))
            else:
                out["errors"].append(f"{h.get('race_label')}: {stt.get('reason','保存失敗')}")
        except Exception as exc:
            out["errors"].append(f"{h.get('race_label') or h.get('history_id')}: {type(exc).__name__}: {exc}")
    out["message"]=(f"確認{out['checked']}件 / 修復{out['repaired_races']}レース・{out['repaired_laps']}周 / "
                    f"既登録{out['already_ok']}件 / 周回材料なし{out['no_laps']}件")
    return out


# Ver264 maintenance: 一括再シミュレーションを現行Ver264でも継承し、周回スナップショットまで原子的に保存する。
# Ver262: 保存済み予測を現在バージョンで一括再シミュレーションする。
# 同一レース・現行Verの履歴が既に存在する場合は重複作成せずスキップする。

# ---------------------------------------------------------------------------
# Ver272: 時系列再シミュレーション後の「仮想100円均等」回収率バックテスト
# 実購入処理ではなく、保存済み過去レースの評価専用。
# オッズは同一レースに保存されている最古スナップショットを全Ver共通で使う。
# ---------------------------------------------------------------------------


# ---------------------------------------------------------------------------
# Ver272評価機能: バージョン横並び・共通レース回収率比較
# 予測ロジックは変更しない。
# 全選択Verに保存予測がある共通race_keyだけを使い、
# 同一レースでは同一の最古オッズスナップショットで買い目を再生成して採点する。
# ---------------------------------------------------------------------------

def _v272_version_race_histories(db_path: str, versions: list[str]) -> dict:
    out = {str(v): {} for v in versions}
    if not versions:
        return out
    _v231_ensure_prediction_history_table(db_path)
    with sqlite3.connect(str(db_path)) as con:
        con.row_factory = sqlite3.Row
        qs = ",".join(["?"] * len(versions))
        rows = con.execute(f"""
            SELECT history_id, race_key, app_version, prediction_time
            FROM v231_prediction_history
            WHERE app_version IN ({qs})
            ORDER BY datetime(prediction_time) ASC, history_id ASC
        """, tuple(str(v) for v in versions)).fetchall()
    for r in rows:
        ver = str(r["app_version"] or "")
        rk = str(r["race_key"] or "")
        if ver in out and rk:
            out[ver][rk] = int(r["history_id"])
    return out


def _v280_saved_plan_exact_same_odds_score(
    db_path: str, race_key: str, version: str,
    shared_odds_maps: dict, shared_odds_run: dict,
) -> dict:
    """同レース・同Verに、共通最古オッズと完全一致する照合済みプランがあればそのまま採点値を返す。"""
    out = {}
    bet_key_map = {
        "三連単":"3tan", "三連複":"3fuku",
        "2連単":"2tansho", "2車単":"2tansho",
        "2連複":"2fuku", "2車複":"2fuku",
        "単勝":"tansho", "複勝":"fukusho", "ワイド":"wide",
    }
    try:
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.row_factory = sqlite3.Row
            plans = con.execute("""
                SELECT r.plan_hash,r.points,r.cost_yen,
                       f.hit,f.payout_yen,f.return_rate,
                       f.evaluated_at,r.created_at
                FROM v187_mixed_plan_runs r
                JOIN v187_mixed_plan_feedback f
                  ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                WHERE r.race_key=?
                  AND COALESCE(NULLIF(r.app_version,''),'Unknown')=?
                  AND f.return_rate IS NOT NULL
                ORDER BY datetime(f.evaluated_at) DESC,
                         datetime(r.created_at) DESC
            """, (str(race_key), str(version))).fetchall()

            for p in plans:
                tickets = con.execute("""
                    SELECT bet_type,combination,odds
                    FROM v187_mixed_plan_tickets
                    WHERE race_key=? AND plan_hash=?
                """, (str(race_key), str(p["plan_hash"]))).fetchall()
                if not tickets:
                    continue
                same = True
                for tk in tickets:
                    key = bet_key_map.get(str(tk["bet_type"] or ""))
                    if not key:
                        same = False
                        break
                    combo = str(tk["combination"] or "").strip()
                    saved = (shared_odds_maps.get(key,{}) or {}).get(combo)
                    try:
                        if saved is None or abs(float(saved)-float(tk["odds"] or 0)) > 1e-6:
                            same = False
                            break
                    except Exception:
                        same = False
                        break
                if same:
                    cost = int(p["cost_yen"] or int(p["points"] or 0)*100)
                    payout = int(p["payout_yen"] or 0)
                    return {
                        "version": str(version), "race_key": str(race_key),
                        "evaluated": True, "points": int(p["points"] or 0),
                        "cost_yen": cost, "payout_yen": payout,
                        "return_rate": float(p["return_rate"] or 0.0),
                        "hit": bool(int(p["hit"] or 0)),
                        "reason": "同一最古オッズの保存済み照合プラン",
                        "odds_created_at": str((shared_odds_run or {}).get("created_at") or ""),
                        "odds_snapshot_id": str((shared_odds_run or {}).get("snapshot_id") or ""),
                    }
    except Exception:
        pass
    return out


def _v272_score_saved_history_same_odds(
    db_path: str,
    history_id: int,
    race_key: str,
    version: str,
    shared_odds_maps: dict,
    shared_odds_run: dict,
) -> dict:
    out = {
        "version": str(version), "race_key": str(race_key), "history_id": int(history_id),
        "evaluated": False, "points": 0, "cost_yen": 0, "payout_yen": 0,
        "return_rate": None, "hit": False, "reason": "",
        "odds_created_at": str((shared_odds_run or {}).get("created_at") or ""),
        "odds_snapshot_id": str((shared_odds_run or {}).get("snapshot_id") or ""),
    }
    try:
        _saved_same280 = _v280_saved_plan_exact_same_odds_score(
            db_path, str(race_key), str(version), shared_odds_maps or {}, shared_odds_run or {}
        )
        if _saved_same280.get("evaluated"):
            _saved_same280["history_id"] = int(history_id)
            return _saved_same280

        view, raw_text, venue_override, hist_meta = _v231_load_prediction_history(db_path, int(history_id))
        if not isinstance(view, dict):
            out["reason"] = "保存予測を復元できません"
            return out

        bets = view.get("bets")
        meta = view.get("meta") or {}
        trials = int(view.get("trials") or 0)
        if not isinstance(bets, dict) or not bets:
            out["reason"] = "保存予測にbetsなし"
            return out
        if sum(len(v) for v in (shared_odds_maps or {}).values()) <= 0:
            out["reason"] = "共通オッズなし"
            return out

        result = v184_eight_car_mixed_plan(bets, trials, meta, shared_odds_maps)
        if not isinstance(result, dict) or not result.get("available"):
            out["reason"] = str((result or {}).get("reason") or "買い目再生成不可")
            return out

        plan_hash = _v187_save_mixed_plan(
            db_path, str(race_key), result, app_version=str(version)
        )
        if not plan_hash:
            out["reason"] = "プラン保存失敗"
            return out

        _v212_recalculate_plan_feedback(db_path, str(race_key), str(plan_hash))

        with sqlite3.connect(str(db_path)) as con:
            con.row_factory = sqlite3.Row
            row = con.execute("""
                SELECT r.points, r.cost_yen,
                       f.hit, f.payout_yen, f.return_rate
                FROM v187_mixed_plan_runs r
                LEFT JOIN v187_mixed_plan_feedback f
                  ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                WHERE r.race_key=? AND r.plan_hash=?
                LIMIT 1
            """, (str(race_key), str(plan_hash))).fetchone()

        if row is None:
            out["reason"] = "採点レコードなし"
            return out

        out["points"] = int(row["points"] or 0)
        out["cost_yen"] = int(row["cost_yen"] or out["points"] * 100)
        if row["return_rate"] is None:
            out["reason"] = "払戻未登録"
            return out

        out["evaluated"] = True
        out["hit"] = bool(int(row["hit"] or 0))
        out["payout_yen"] = int(row["payout_yen"] or 0)
        out["return_rate"] = float(row["return_rate"] or 0.0)
        out["reason"] = "採点済み"

        try:
            _extra276=_v276_virtual_extra_all_odds_score(
                db_path,str(race_key),bets,int(trials or 0),shared_odds_maps,result or {},
            )
            if _extra276.get("available"):
                out["virtual_extra_points"]=int(_extra276.get("points",0) or 0)
                out["virtual_extra_cost_yen"]=int(_extra276.get("cost_yen",0) or 0)
                out["virtual_extra_payout_yen"]=int(_extra276.get("payout_yen",0) or 0)
                out["virtual_extra_hits"]=int(_extra276.get("hits",0) or 0)
                out["virtual_extra_rows"]=list(_extra276.get("rows") or [])
                out["virtual_combined_model_return_rate"]=_extra276.get("combined_model_return_rate")
            out["virtual_combined_cost_yen"]=int(out["cost_yen"])+int(out["virtual_extra_cost_yen"])
            out["virtual_combined_payout_yen"]=int(out["payout_yen"])+int(out["virtual_extra_payout_yen"])
            out["virtual_combined_return_rate"]=(
                float(out["virtual_combined_payout_yen"])/float(out["virtual_combined_cost_yen"])*100.0
                if int(out["virtual_combined_cost_yen"])>0 else None
            )
        except Exception:
            out["virtual_combined_cost_yen"]=int(out["cost_yen"])
            out["virtual_combined_payout_yen"]=int(out["payout_yen"])
            out["virtual_combined_return_rate"]=out["return_rate"]
        return out
    except Exception as exc:
        out["reason"] = f"{type(exc).__name__}: {exc}"
        return out


def _v272_common_race_roi_compare(db_path: str, versions: list[str]) -> dict:
    versions = [str(v) for v in versions if str(v)]
    out = {
        "versions": versions, "common_races": [], "rows": [], "summary": [],
        "missing_odds": 0, "missing_payout": 0,
    }
    if len(versions) < 2:
        return out

    hist = _v272_version_race_histories(db_path, versions)
    sets = [set(hist[v].keys()) for v in versions]
    common = sorted(set.intersection(*sets)) if sets else []
    out["common_races"] = common

    for race_key in common:
        odds_maps, odds_run = _v273_load_earliest_saved_odds(db_path, race_key)
        if sum(len(v) for v in odds_maps.values()) <= 0:
            out["missing_odds"] += 1
            continue

        for ver in versions:
            hid = hist[ver].get(race_key)
            if not hid:
                continue
            row = _v272_score_saved_history_same_odds(
                db_path, hid, race_key, ver, odds_maps, odds_run
            )
            out["rows"].append(row)
            if (not row.get("evaluated")) and "払戻" in str(row.get("reason") or ""):
                out["missing_payout"] += 1

    for ver in versions:
        vr = [r for r in out["rows"] if r.get("version") == ver and r.get("evaluated")]
        cost = sum(int(r.get("cost_yen",0) or 0) for r in vr)
        payout = sum(int(r.get("payout_yen",0) or 0) for r in vr)
        hits = sum(int(bool(r.get("hit"))) for r in vr)
        rate = (payout / cost * 100.0) if cost > 0 else None
        out["summary"].append({
            "version": ver,
            "対象R": len(vr),
            "的中R": hits,
            "投資円": cost,
            "払戻円": payout,
            "回収率": rate,
        })
    return out


def _v273_load_earliest_saved_odds(db_path: str, race_key: str) -> tuple[dict, dict]:
    empty = {'3tan': {}, '3fuku': {}, '2tansho': {}, '2fuku': {}, 'tansho': {}, 'fukusho': {}, 'wide': {}}
    try:
        _v221_ensure_odds_tables(db_path)
        with sqlite3.connect(str(db_path)) as con:
            con.row_factory = sqlite3.Row
            run = con.execute("""
                SELECT * FROM v221_odds_runs
                WHERE race_key=?
                ORDER BY datetime(created_at) ASC, rowid ASC
                LIMIT 1
            """, (str(race_key or ''),)).fetchone()
            if not run:
                return empty, {}
            rows = con.execute("""
                SELECT bet_key, combination, odds
                FROM v221_odds_values
                WHERE race_key=? AND snapshot_id=?
            """, (str(race_key or ''), str(run["snapshot_id"]))).fetchall()
        out = {k: {} for k in empty}
        for r in rows:
            k = str(r["bet_key"] or "")
            if k in out:
                try:
                    odd = float(r["odds"])
                    if odd > 0:
                        out[k][str(r["combination"])] = odd
                except Exception:
                    pass
        return out, dict(run)
    except Exception:
        return empty, {}



def _v276_virtual_all_odds_candidates(
    bets: dict,
    trials: int,
    odds_maps: dict,
) -> list[dict]:
    """
    過去バックテスト専用。
    保存オッズにある全対応券種
    3連単 / 3連複 / 2連単 / 2連複 / 単勝 / ワイド
    を同じ基準でモデル確率・単体期待値へ変換する。
    """
    tri_counter=(bets or {}).get("三連単",{}) or {}
    if not tri_counter or int(trials or 0)<=0:
        return []

    outcomes=[]
    for combo,count in tri_counter.items():
        vals=tuple(int(v) for v in (tuple(combo) if isinstance(combo,(tuple,list)) else (combo,)))
        if len(vals)==3:
            outcomes.append((vals,float(count)/max(int(trials),1)*100.0))
    if not outcomes:
        return []

    probs={
        "三連単":{},
        "三連複":{},
        "2連単":{},
        "2連複":{},
        "単勝":{},
        "ワイド":{},
    }
    for (a,b,c),prob in outcomes:
        k3=f"{a}-{b}-{c}"
        probs["三連単"][k3]=probs["三連単"].get(k3,0.0)+prob

        k3f="-".join(map(str,sorted((a,b,c))))
        probs["三連複"][k3f]=probs["三連複"].get(k3f,0.0)+prob

        k2=f"{a}-{b}"
        probs["2連単"][k2]=probs["2連単"].get(k2,0.0)+prob

        k2f="-".join(map(str,sorted((a,b))))
        probs["2連複"][k2f]=probs["2連複"].get(k2f,0.0)+prob

        probs["単勝"][str(a)]=probs["単勝"].get(str(a),0.0)+prob

        for x,y in ((a,b),(a,c),(b,c)):
            kw="-".join(map(str,sorted((x,y))))
            probs["ワイド"][kw]=probs["ワイド"].get(kw,0.0)+prob

    key_map={
        "三連単":"3tan",
        "三連複":"3fuku",
        "2連単":"2tansho",
        "2連複":"2fuku",
        "単勝":"tansho",
        "ワイド":"wide",
    }

    rows=[]
    for typ,odd_key in key_map.items():
        for combo,odds in (odds_maps.get(odd_key,{}) or {}).items():
            try:
                odd=float(odds)
                combo_text=str(combo).strip()
                if typ in ("三連複","2連複","ワイド"):
                    nums=[int(x) for x in re.findall(r"\d+",combo_text)]
                    if nums:
                        combo_text="-".join(map(str,sorted(nums)))
                prob=float(probs[typ].get(combo_text,0.0))
            except Exception:
                continue
            if odd<=0 or prob<=0:
                continue
            ev=prob/100.0*odd*100.0
            rows.append({
                "type":typ,
                "combo":combo_text,
                "probability":prob,
                "odds":odd,
                "ev":ev,
            })

    rows.sort(
        key=lambda r:(float(r.get("ev",0)),float(r.get("probability",0))),
        reverse=True,
    )
    return rows


def _v276_virtual_extra_all_odds_score(
    db_path: str,
    race_key: str,
    bets: dict,
    trials: int,
    odds_maps: dict,
    base_result: dict,
) -> dict:
    """
    過去バックテスト専用。
    既存4券種合成プランを基準に、保存オッズに存在する全対応券種から、
    追加後の合成モデル期待回収率が上昇する候補だけを仮想追加する。
    現在レースの候補表示・実購入処理には使用しない。
    """
    out={
        "available":False,"points":0,"cost_yen":0,"payout_yen":0,"hits":0,
        "rows":[],"base_model_return_rate":None,"combined_model_return_rate":None,
        "reason":"",
    }

    try:
        base_n=int((base_result or {}).get("points",0) or 0)
        base_rate=float((base_result or {}).get("model_return_rate"))
    except Exception:
        base_n=0
        base_rate=None
    if base_n<=0 or base_rate is None or not np.isfinite(base_rate):
        out["reason"]="基準プランのモデル期待回収率なし"
        return out

    candidates=_v276_virtual_all_odds_candidates(bets,int(trials or 0),odds_maps or {})
    if not candidates:
        out["reason"]="保存オッズから仮想候補を作れませんでした"
        return out

    # 既存プランにすでに含まれる券は追加対象から除外。
    base_ids=set()
    for t in (base_result or {}).get("tickets",[]) or []:
        typ=str(t.get("type") or "")
        combo=str(t.get("combo") or "").strip()
        if typ in ("三連複","2連複","ワイド"):
            nums=[int(x) for x in re.findall(r"\d+",combo)]
            if nums:
                combo="-".join(map(str,sorted(nums)))
        base_ids.add((typ,combo))

    base_cost=float(base_n*100)
    expected_payout=base_cost*base_rate/100.0
    current_cost=base_cost
    current_rate=base_rate
    selected=[]

    for cand in candidates:
        ident=(str(cand.get("type") or ""),str(cand.get("combo") or ""))
        if ident in base_ids:
            continue
        try:
            ev=float(cand.get("ev",0) or 0)
        except Exception:
            continue
        if ev<=0:
            continue
        next_expected=expected_payout+ev
        next_cost=current_cost+100.0
        next_rate=next_expected/next_cost*100.0 if next_cost>0 else 0.0
        # 追加後の合成モデル期待回収率が上がるものだけ。
        if next_rate>current_rate+1e-9:
            selected.append(dict(cand))
            expected_payout=next_expected
            current_cost=next_cost
            current_rate=next_rate

    if not selected:
        out["reason"]="全券種を比較したが合成モデル期待回収率を上げる追加候補なし"
        return out

    # 候補選択後にだけ実払戻で採点する。
    try:
        with sqlite3.connect(str(db_path),timeout=30.0) as con:
            con.row_factory=sqlite3.Row
            payout_rows=con.execute("""
                SELECT bet_type, combination, payout_yen
                FROM result_payouts
                WHERE race_key=?
            """,(str(race_key or ""),)).fetchall()
        payout_map={}
        for r in payout_rows:
            typ=_v212_norm_bet_type(str(r["bet_type"] or ""))
            combo=_v187_norm_combo(str(r["bet_type"] or ""),str(r["combination"] or ""))
            payout_map[(typ,combo)]=int(r["payout_yen"] or 0)
    except Exception as exc:
        out["reason"]=f"払戻読込失敗: {type(exc).__name__}: {exc}"
        return out

    actual_payout=0
    hit_count=0
    detail=[]
    for cand in selected:
        typ=str(cand.get("type") or "")
        combo=str(cand.get("combo") or "").strip()
        norm_typ=_v212_norm_bet_type(typ)
        norm_combo=_v187_norm_combo(typ,combo)
        payout=int(payout_map.get((norm_typ,norm_combo),0) or 0)
        hit=bool(payout>0)
        actual_payout+=payout
        hit_count+=int(hit)
        detail.append({
            "type":typ,
            "combo":combo,
            "model_probability":float(cand.get("probability",0) or 0),
            "saved_odds":float(cand.get("odds",0) or 0),
            "model_ev":float(cand.get("ev",0) or 0),
            "hit":hit,
            "payout_yen":payout,
        })

    out.update({
        "available":True,
        "points":len(selected),
        "cost_yen":len(selected)*100,
        "payout_yen":int(actual_payout),
        "hits":int(hit_count),
        "rows":detail,
        "base_model_return_rate":float(base_rate),
        "combined_model_return_rate":float(current_rate),
        "reason":"全対応券種から合成モデル期待回収率が上がる候補だけ仮想追加",
    })
    return out



def _v273_virtual_roi_score(
    db_path: str,
    race_key: str,
    bets: dict,
    trials: int,
    meta: dict,
    app_version: str,
) -> dict:
    """
    保存済みの最古オッズ + 登録済み払戻で、再シミュレーション結果を仮想採点する。
    1点100円均等。オッズ未保存/払戻未登録なら対象外。
    """
    out = {
        "available": False, "evaluated": False, "race_key": str(race_key or ""),
        "cost_yen": 0, "payout_yen": 0, "return_rate": None,
        "points": 0, "hit": False, "odds_snapshot_id": "", "odds_created_at": "",
        "reason": "",
        "virtual_extra_points":0,
        "virtual_extra_cost_yen":0,
        "virtual_extra_payout_yen":0,
        "virtual_extra_hits":0,
        "virtual_extra_rows":[],
        "virtual_combined_cost_yen":0,
        "virtual_combined_payout_yen":0,
        "virtual_combined_return_rate":None,
        "virtual_combined_model_return_rate":None,
    }
    if not race_key:
        out["reason"] = "race_keyなし"
        return out

    odds_maps, odds_run = _v273_load_earliest_saved_odds(db_path, race_key)
    if sum(len(v) for v in odds_maps.values()) <= 0:
        out["reason"] = "保存オッズなし"
        return out

    try:
        result = v184_eight_car_mixed_plan(bets, int(trials or 0), meta or {}, odds_maps)
    except Exception as exc:
        out["reason"] = f"プラン生成失敗: {type(exc).__name__}: {exc}"
        return out

    if not isinstance(result, dict) or not result.get("available"):
        out["reason"] = str((result or {}).get("reason") or "回収率プラン生成不可")
        return out

    out["available"] = True
    out["odds_snapshot_id"] = str(odds_run.get("snapshot_id") or "")
    out["odds_created_at"] = str(odds_run.get("created_at") or "")
    try:
        plan_hash = _v187_save_mixed_plan(
            db_path, str(race_key), result, app_version=str(app_version or APP_VERSION)
        )
        if not plan_hash:
            out["reason"] = "プラン保存失敗"
            return out
        _v212_recalculate_plan_feedback(db_path, str(race_key), str(plan_hash))

        with sqlite3.connect(str(db_path)) as con:
            con.row_factory = sqlite3.Row
            row = con.execute("""
                SELECT r.points, r.cost_yen,
                       f.hit, f.payout_yen, f.return_rate
                FROM v187_mixed_plan_runs r
                LEFT JOIN v187_mixed_plan_feedback f
                  ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                WHERE r.race_key=? AND r.plan_hash=?
                LIMIT 1
            """, (str(race_key), str(plan_hash))).fetchone()

        if row is None:
            out["reason"] = "採点レコードなし"
            return out

        out["points"] = int(row["points"] or 0)
        out["cost_yen"] = int(row["cost_yen"] or out["points"] * 100)
        if row["return_rate"] is None:
            out["reason"] = "払戻未登録"
            return out

        out["evaluated"] = True
        out["hit"] = bool(int(row["hit"] or 0))
        out["payout_yen"] = int(row["payout_yen"] or 0)
        out["return_rate"] = float(row["return_rate"] or 0.0)
        out["reason"] = "採点済み"
        return out
    except Exception as exc:
        out["reason"] = f"採点失敗: {type(exc).__name__}: {exc}"
        return out



# Ver278: Streamlit画面を占有しない再シミュレーション用バックグラウンドジョブ。
# 状態はst.session_stateではなくSQLiteへ保存するため、画面移動・再描画後も確認できる。
_V278_BG_THREADS = globals().get("_V278_BG_THREADS", {})
_V278_BG_LOCK = globals().get("_V278_BG_LOCK", threading.Lock())

def _v278_bg_ensure_table(db_path: str) -> None:
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        try:
            con.execute("PRAGMA journal_mode=WAL")
        except Exception:
            pass
        con.execute("""
            CREATE TABLE IF NOT EXISTS v278_background_jobs(
                job_id INTEGER PRIMARY KEY AUTOINCREMENT,
                job_type TEXT NOT NULL,
                app_version TEXT NOT NULL,
                status TEXT NOT NULL,
                created_at TEXT NOT NULL,
                started_at TEXT,
                updated_at TEXT,
                finished_at TEXT,
                limit_count INTEGER NOT NULL DEFAULT 0,
                force_current INTEGER NOT NULL DEFAULT 0,
                done_count INTEGER NOT NULL DEFAULT 0,
                total_count INTEGER NOT NULL DEFAULT 0,
                current_label TEXT DEFAULT '',
                message TEXT DEFAULT '',
                result_blob BLOB,
                cancel_requested INTEGER NOT NULL DEFAULT 0,
                pause_requested INTEGER NOT NULL DEFAULT 0,
                error_text TEXT DEFAULT ''
            )
        """)
        try:
            cols={str(r[1]) for r in con.execute("PRAGMA table_info(v278_background_jobs)").fetchall()}
            if "pause_requested" not in cols:
                con.execute("ALTER TABLE v278_background_jobs ADD COLUMN pause_requested INTEGER NOT NULL DEFAULT 0")
        except Exception:
            pass
        con.commit()

def _v278_bg_update(db_path: str, job_id: int, **fields) -> None:
    if not fields:
        return
    _v278_bg_ensure_table(db_path)
    allowed={
        "status","started_at","updated_at","finished_at","done_count","total_count",
        "current_label","message","result_blob","cancel_requested","pause_requested","error_text"
    }
    fields={k:v for k,v in fields.items() if k in allowed}
    if not fields:
        return
    fields["updated_at"]=_v228_now_jst_iso()
    keys=list(fields.keys())
    sql="UPDATE v278_background_jobs SET "+",".join(f"{k}=?" for k in keys)+" WHERE job_id=?"
    vals=[fields[k] for k in keys]+[int(job_id)]
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        con.execute(sql, vals)
        con.commit()

def _v278_bg_get_job(db_path: str, job_id: int | None = None) -> dict:
    try:
        _v278_bg_ensure_table(db_path)
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.row_factory=sqlite3.Row
            con.execute("PRAGMA busy_timeout=30000")
            if job_id:
                row=con.execute(
                    "SELECT * FROM v278_background_jobs WHERE job_id=?",
                    (int(job_id),)
                ).fetchone()
            else:
                row=con.execute("""
                    SELECT * FROM v278_background_jobs
                    WHERE job_type='batch_rerun'
                    ORDER BY job_id DESC LIMIT 1
                """).fetchone()
        if not row:
            return {}
        d=dict(row)
        blob=d.get("result_blob")
        if blob:
            try:
                d["result"]=pickle.loads(zlib.decompress(bytes(blob)))
            except Exception:
                d["result"]={}
        else:
            d["result"]={}
        return d
    except Exception:
        return {}

def _v278_bg_has_running_job(db_path: str) -> bool:
    try:
        _v278_bg_ensure_table(db_path)
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.execute("PRAGMA busy_timeout=30000")
            row=con.execute("""
                SELECT COUNT(*) FROM v278_background_jobs
                WHERE job_type='batch_rerun' AND status IN ('queued','running','pause_requested','paused','cancel_requested')
            """).fetchone()
        return bool(int(row[0] or 0))
    except Exception:
        return False

def _v278_bg_cancel_requested(db_path: str, job_id: int) -> bool:
    try:
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.execute("PRAGMA busy_timeout=30000")
            row=con.execute(
                "SELECT cancel_requested FROM v278_background_jobs WHERE job_id=?",
                (int(job_id),)
            ).fetchone()
        return bool(row and int(row[0] or 0))
    except Exception:
        return False

def _v278_bg_request_cancel(db_path: str, job_id: int) -> None:
    _v278_bg_update(
        db_path, job_id,
        status="cancel_requested",
        cancel_requested=1,
        message="現在のレース処理が終わり次第停止します。"
    )

def _v278_bg_pause_requested(db_path: str, job_id: int) -> bool:
    try:
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.execute("PRAGMA busy_timeout=30000")
            row=con.execute(
                "SELECT pause_requested FROM v278_background_jobs WHERE job_id=?",
                (int(job_id),)
            ).fetchone()
        return bool(row and int(row[0] or 0))
    except Exception:
        return False

def _v278_bg_set_pause(db_path: str, job_id: int, paused: bool, message: str = "") -> None:
    _v278_bg_update(
        db_path, job_id,
        pause_requested=1 if paused else 0,
        status="pause_requested" if paused else "running",
        message=message or ("他のDB登録を待っています。" if paused else "再シミュレーションを再開しました。"),
    )

def _v278_bg_pause_loop(db_path: str, job_id: int) -> None:
    if not _v278_bg_pause_requested(db_path, job_id):
        return
    _v278_bg_update(
        db_path, job_id,
        status="paused",
        message="選手履歴・結果などのDB登録を優先するため一時停止中です。"
    )
    while _v278_bg_pause_requested(db_path, job_id):
        if _v278_bg_cancel_requested(db_path, job_id):
            return
        time_module.sleep(0.25)
    _v278_bg_update(db_path, job_id, status="running", message="バックグラウンド再シミュレーションを再開しました。")

def _v278_pause_background_for_foreground(db_path: str, timeout_sec: float = 90.0) -> dict:
    """DB登録前にバックグラウンド処理をレース境界で止める。"""
    job=_v278_bg_get_job(db_path)
    if not job or str(job.get("status") or "") not in ("queued","running","pause_requested","paused"):
        return {"paused":False,"job_id":0,"reason":"no_running_job"}
    job_id=int(job.get("job_id") or 0)
    _v278_bg_set_pause(db_path,job_id,True,"DB登録を優先するため、現在レース終了後に一時停止します。")
    deadline=time_module.time()+float(timeout_sec)
    while time_module.time()<deadline:
        cur=_v278_bg_get_job(db_path,job_id)
        status=str(cur.get("status") or "")
        if status=="paused":
            return {"paused":True,"job_id":job_id}
        if status in ("completed","cancelled","failed"):
            return {"paused":False,"job_id":job_id,"reason":status}
        time_module.sleep(0.25)
    # タイムアウト時は無理に同時書込せず、登録側に明示する
    return {"paused":False,"job_id":job_id,"reason":"timeout"}

def _v278_resume_background_after_foreground(db_path: str, pause_info: dict) -> None:
    try:
        if pause_info and pause_info.get("job_id"):
            _v278_bg_set_pause(db_path,int(pause_info["job_id"]),False,"DB登録完了。再シミュレーションを再開します。")
    except Exception:
        pass


class _V276ForegroundPredictionPriority:
    """通常予測中はバックグラウンド再シミュレーションへ一時停止要求を出す。

    停止完了を待たないため通常予測の開始は遅らせない。バックグラウンド側は
    現在レース終了後の境界で停止し、通常予測終了後に自動再開する。
    """
    def __init__(self, db_path):
        self.db_path = str(db_path)
        self.job_id = 0

    def __enter__(self):
        try:
            job = _v278_bg_get_job(self.db_path)
            if job and str(job.get("status") or "") in ("queued", "running", "pause_requested", "paused"):
                self.job_id = int(job.get("job_id") or 0)
                if self.job_id:
                    _v278_bg_set_pause(
                        self.db_path, self.job_id, True,
                        "通常予測を優先するため、現在レース終了後に一時停止します。"
                    )
        except Exception:
            self.job_id = 0
        return self

    def __exit__(self, exc_type, exc, tb):
        try:
            if self.job_id:
                _v278_bg_set_pause(
                    self.db_path, self.job_id, False,
                    "通常予測完了。バックグラウンド再シミュレーションを再開します。"
                )
        except Exception:
            pass
        return False

def _v276_send_rerun_complete_notification(result: dict) -> None:
    """バックグラウンド再シミュレーション正常完了時だけntfyへ即時通知する。

    通知失敗は再シミュレーション結果へ影響させない。
    通知先は既存の一般予定通知と同じ既定トピック notify を使用し、
    Streamlit Cloud等では AUTORACE_NTFY_TOPIC 環境変数で上書きできる。
    """
    try:
        topic = str(os.environ.get("AUTORACE_NTFY_TOPIC", "notify") or "notify").strip()
        if not topic or any(ch in topic for ch in "/?# "):
            return
        rerun = int((result or {}).get("rerun") or 0)
        checked = int((result or {}).get("checked") or 0)
        message = f"再シミュレーションが完了しました。再計算 {rerun}R / 確認 {checked}R"
        payload = {
            "topic": topic,
            "title": "AutoRaceAI 再シミュレーション完了",
            "message": message,
            "priority": 4,
            "tags": ["bell"],
        }
        request = urllib.request.Request(
            "https://ntfy.sh",
            data=json.dumps(payload, ensure_ascii=False).encode("utf-8", errors="strict"),
            method="POST",
            headers={"Content-Type": "application/json; charset=utf-8"},
        )
        with urllib.request.urlopen(request, timeout=8) as response:
            response.read()
    except Exception:
        # 通知経路の一時障害で、完了済みジョブをfailed扱いにしない。
        pass



def _v284_backfill_transition_audit_from_latest_histories(db_path: str, app_version: str = "") -> dict:
    """最新予測payloadに既に入っているVer284展開監査をDB監査3表へ復元する。
    再シミュレーションは行わない。batch保存経路の保険として完了時に必ず実行する。
    """
    result={"ok":False,"checked":0,"saved_races":0,"errors":[]}
    ver=str(app_version or globals().get("_V231_APP_VERSION") or "Ver284")
    try:
        _v284_ensure_transition_audit_tables(db_path)
        with sqlite3.connect(str(db_path),timeout=60.0) as con:
            con.execute("PRAGMA busy_timeout=60000")
            rows=con.execute("""
                SELECT h.race_key,h.prediction_time,h.trials,h.payload
                FROM v231_prediction_history h
                JOIN (
                    SELECT race_key,MAX(history_id) AS mid
                    FROM v231_prediction_history
                    WHERE app_version=?
                    GROUP BY race_key
                ) x ON h.history_id=x.mid
                ORDER BY h.race_key
            """,(ver,)).fetchall()
        for race_key,prediction_time,trials,payload in rows:
            result["checked"]+=1
            try:
                obj=pickle.loads(zlib.decompress(payload))
                meta=(obj or {}).get("meta") or {}
                wall=meta.get("6周展開シミュレーション") or meta.get("壁補正監査") or {}
                detail=wall.get("v284_transition_audit") or {}
                if not detail:
                    continue
                # 既にこのrace_keyの最新監査が6周あるなら重複保存しない。
                with sqlite3.connect(str(db_path),timeout=30.0) as con:
                    n=int(con.execute(
                        "SELECT COUNT(DISTINCT lap_no) FROM v284_transition_audit WHERE race_key=? AND app_version=?",
                        (str(race_key),ver)
                    ).fetchone()[0] or 0)
                if n>=6:
                    result["saved_races"]+=1
                    continue
                save=_v284_save_transition_audit(db_path,str(race_key),wall)
                if save.get("ok"):
                    result["saved_races"]+=1
                elif len(result["errors"])<8:
                    result["errors"].append(f"{race_key}: {save.get('reason','保存失敗')}")
            except Exception as exc:
                if len(result["errors"])<8:
                    result["errors"].append(f"{race_key}: {type(exc).__name__}: {exc}")
        result["ok"]=(len(result["errors"])==0)
        return result
    except Exception as exc:
        result["errors"].append(f"{type(exc).__name__}: {exc}")
        return result


def _v278_bg_worker(db_path: str, job_id: int, limit_count: int, force_current: bool, resume_done_offset: int = 0, resume_total_target: int = 0, diagnostic_auto: bool = False) -> None:
    try:
        _v278_bg_update(
            db_path, job_id,
            status="running",
            started_at=_v228_now_jst_iso(),
            message="対象レースを整理しています。"
        )
        def _progress(done,total,label):
            _done_raw=int(done or 0)
            _total_raw=int(total or 0)
            _done_show=int(resume_done_offset or 0)+_done_raw
            _total_show=int(resume_total_target or 0)
            if _total_show <= 0:
                _total_show=int(resume_done_offset or 0)+_total_raw
            _total_show=max(_total_show,_done_show)
            _v278_bg_update(
                db_path, job_id,
                done_count=_done_show,
                total_count=_total_show,
                current_label=str(label or ""),
                message=f"{_done_show}/{_total_show}｜{str(label or '')}"
            )

        result=_v262_batch_rerun_saved_histories(
            db_path,
            int(limit_count),
            _progress,
            force_current=bool(force_current),
            diagnostic_auto=bool(diagnostic_auto),
            cancel_cb=lambda: _v278_bg_cancel_requested(db_path,job_id),
            pause_cb=lambda: _v278_bg_pause_loop(db_path,job_id),
        )
        # Ver284 hotfix: 各レースの最新payloadには監査集計が保存されているため、
        # batch終了時（停止時を含む）に必ず監査3表へ同期する。
        _audit_backfill284=_v284_backfill_transition_audit_from_latest_histories(
            db_path,str(globals().get("_V231_APP_VERSION") or "Ver284")
        )
        result["v284_audit_backfill"]=_audit_backfill284
        result["v284_transition_audit_saved_races"]=int(_audit_backfill284.get("saved_races") or 0)
        cancelled=bool(result.get("cancelled")) or _v278_bg_cancel_requested(db_path,job_id)
        blob=zlib.compress(pickle.dumps(result,protocol=pickle.HIGHEST_PROTOCOL),level=6)
        _final_done278=int(resume_done_offset or 0)+int(result.get("checked",0) or 0)
        _final_total278=int(resume_done_offset or 0)+int(result.get("candidate_total",result.get("checked",0)) or 0)
        _v278_bg_update(
            db_path, job_id,
            status="cancelled" if cancelled else "completed",
            finished_at=_v228_now_jst_iso(),
            done_count=_final_done278,
            total_count=_final_total278,
            current_label="",
            message=(
                "停止しました。処理済みレースは保存されています。"
                if cancelled else (
                    str(result.get("message") or "完了しました。")
                    + f" / Ver284展開監査DB保存{int(result.get('v284_transition_audit_saved_races') or 0)}R"
                )
            ),
            result_blob=sqlite3.Binary(blob),
        )
        # Ver309: 再シミュレーション中に保留したGitHub保存を、完了後に1回だけ実行。
        # ここではバックグラウンドjobをcompleted/cancelledへ更新済みなので、
        # push_db_to_github()の通常の再シミュレーション中ガードには掛からない。
        try:
            _gh309_ok, _gh309_msg = push_db_to_github(
                "AutoRaceAI: 再シミュレーション完了後のDB一括保存"
            )
            result["github_deferred_save_ok"] = bool(_gh309_ok)
            result["github_deferred_save_message"] = str(_gh309_msg or "")
            if not _gh309_ok:
                # GitHub保存失敗で再シミュレーション自体をfailed扱いにはしない。
                _v278_bg_update(
                    db_path, job_id,
                    message=(
                        "再シミュレーションは完了しました。GitHub一括保存は未完了です。 "
                        + str(_gh309_msg or "")
                    ),
                )
        except Exception as _gh309_exc:
            result["github_deferred_save_ok"] = False
            result["github_deferred_save_message"] = (
                f"{type(_gh309_exc).__name__}: {_gh309_exc}"
            )
            _v278_bg_update(
                db_path, job_id,
                message=(
                    "再シミュレーションは完了しました。GitHub一括保存でエラーが発生しました。 "
                    + result["github_deferred_save_message"]
                ),
            )
        if not cancelled:
            _v276_send_rerun_complete_notification(result)
    except Exception as exc:
        _v278_bg_update(
            db_path, job_id,
            status="failed",
            finished_at=_v228_now_jst_iso(),
            current_label="",
            message="バックグラウンド再シミュレーションでエラーが発生しました。",
            error_text=f"{type(exc).__name__}: {exc}",
        )
    finally:
        try:
            with _V278_BG_LOCK:
                _V278_BG_THREADS.pop(int(job_id),None)
        except Exception:
            pass

def _v278_bg_start(db_path: str, limit_count: int, force_current: bool, diagnostic_auto: bool = False) -> dict:
    _v278_bg_ensure_table(db_path)
    if _v278_bg_has_running_job(db_path):
        return {"ok":False,"reason":"すでにバックグラウンド再シミュレーションが動いています。"}
    now=_v228_now_jst_iso()
    try:
        _v231_ensure_prediction_history_table(db_path)
        with sqlite3.connect(str(db_path),timeout=30.0) as _con278:
            if bool(force_current):
                _approx_total278=int(_con278.execute("""
                    SELECT COUNT(*) FROM (
                        SELECT race_key FROM v231_prediction_history
                        WHERE race_key IS NOT NULL AND TRIM(race_key)<>''
                        GROUP BY race_key
                        ORDER BY MAX(history_id) DESC LIMIT ?
                    )
                """,(max(1,int(limit_count)),)).fetchone()[0] or 0)
            else:
                _approx_total278=int(_con278.execute("""
                    SELECT COUNT(*) FROM (
                        SELECT h.race_key
                        FROM v231_prediction_history h
                        WHERE h.race_key IS NOT NULL AND TRIM(h.race_key)<>''
                          AND NOT EXISTS (
                              SELECT 1 FROM v231_prediction_history c
                              WHERE c.race_key=h.race_key AND c.app_version=?
                          )
                        GROUP BY h.race_key
                        ORDER BY MAX(h.history_id) DESC LIMIT ?
                    )
                """,(str(_V231_APP_VERSION),max(1,int(limit_count)))).fetchone()[0] or 0)
    except Exception:
        _approx_total278=0
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        cur=con.execute("""
            INSERT INTO v278_background_jobs(
                job_type,app_version,status,created_at,updated_at,limit_count,force_current,message
            ) VALUES ('batch_rerun',?,?,?,?,?,?,?)
        """,(
            str(_V231_APP_VERSION),"queued",now,now,
            int(limit_count),1 if force_current else 0,
            "準備中"
        ))
        try:
            con.execute(
                "UPDATE v278_background_jobs SET total_count=?, message=? WHERE job_id=?",
                (int(_approx_total278), "対象レースを確認中" if _approx_total278<=0 else f"対象 約{int(_approx_total278)}R を確認", int(cur.lastrowid or 0))
            )
        except Exception:
            pass
        con.commit()
        job_id=int(cur.lastrowid or 0)
    th=threading.Thread(
        target=_v278_bg_worker,
        args=(str(db_path),job_id,int(limit_count),bool(force_current),0,0,bool(diagnostic_auto)),
        daemon=True,
        name=f"autorace-bg-rerun-{job_id}",
    )
    with _V278_BG_LOCK:
        _V278_BG_THREADS[job_id]=th
    th.start()
    return {"ok":True,"job_id":job_id}





# Ver290 hotfix4: 途中jobを捨てて「最初から」やり直すための安全な再スタート。
# 既にVer290で正常保存済みのレースは再計算しないので、結果の重複は作らない。
def _v290_restart_batch_clean(db_path: str, limit_count: int = 80) -> dict:
    try:
        _v278_bg_ensure_table(db_path)
        now=_v228_now_jst_iso()

        # 既存のbatch jobをすべて停止扱いへ。
        with sqlite3.connect(str(db_path),timeout=1.0) as con:
            con.execute("PRAGMA busy_timeout=1000")
            con.execute("""
                UPDATE v278_background_jobs
                   SET status='cancelled',
                       cancel_requested=1,
                       pause_requested=0,
                       finished_at=?,
                       message='Ver290クリーン再スタートのため旧jobを終了',
                       updated_at=?
                 WHERE job_type='batch_rerun'
                   AND status IN ('queued','running','pause_requested','paused','cancel_requested')
            """,(now,now))
            con.commit()

        # 同一プロセス内に残るthread参照も破棄。
        try:
            with _V278_BG_LOCK:
                _V278_BG_THREADS.clear()
        except Exception:
            pass

        # 新jobを「force_current=False」で開始。
        # これによりVer290で6周+監査まで保存済みのレースは自動スキップし、
        # 未完了レースだけを最初から順にやり直す。
        result=_v278_bg_start(str(db_path),int(limit_count),False)
        if result.get("ok"):
            return {
                "ok":True,
                "job_id":int(result.get("job_id") or 0),
                "message":"旧jobを破棄し、Ver290保存済みを除外して最初から再シミュレーションを開始しました。"
            }
        return {"ok":False,"reason":str(result.get("reason") or "開始失敗")}
    except Exception as exc:
        return {"ok":False,"reason":f"{type(exc).__name__}: {exc}"}

# Ver290 hotfix3: BG heartbeat / stale recovery.
def _v290_parse_job_time(value) -> float:
    try:
        s=str(value or "").strip()
        if not s:
            return 0.0
        dt=datetime.fromisoformat(s.replace("Z","+00:00"))
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=_V228_JST)
        return dt.timestamp()
    except Exception:
        return 0.0

def _v290_spawn_recovery_worker(db_path: str, old_job: dict, reason: str) -> dict:
    """Old jobを打切り、新jobで保存済みVer290を除いた残りだけ再開する。"""
    try:
        jid_old=int(old_job.get("job_id") or 0)
        done0=int(old_job.get("done_count") or 0)
        total0=int(old_job.get("total_count") or 0)
        limit0=max(1,int(old_job.get("limit_count") or total0 or 80))

        # 古いjobは以後UIの「実行中」判定から外す。万一旧threadが戻ってもcancel_requestedを見て終了する。
        with sqlite3.connect(str(db_path),timeout=1.0) as con:
            con.execute("PRAGMA busy_timeout=1000")
            con.execute("""
                UPDATE v278_background_jobs
                   SET status='cancelled',
                       cancel_requested=1,
                       pause_requested=0,
                       finished_at=?,
                       message=?,
                       updated_at=?
                 WHERE job_id=?
            """,(
                _v228_now_jst_iso(),
                "停止状態を検知したため新しいjobへ引継ぎ: "+str(reason),
                _v228_now_jst_iso(),
                jid_old
            ))
            con.commit()

        now=_v228_now_jst_iso()
        with sqlite3.connect(str(db_path),timeout=1.0) as con:
            con.execute("PRAGMA busy_timeout=1000")
            cur=con.execute("""
                INSERT INTO v278_background_jobs(
                    job_type,app_version,status,created_at,updated_at,started_at,
                    limit_count,force_current,done_count,total_count,current_label,message
                ) VALUES ('batch_rerun',?,'running',?,?,?,?,0,?,?,?,?)
            """,(
                str(_V231_APP_VERSION),now,now,now,limit0,
                done0,total0,str(old_job.get("current_label") or ""),
                f"{done0}/{total0}から残りを自動再開しました。"
            ))
            con.commit()
            jid_new=int(cur.lastrowid or 0)

        th=threading.Thread(
            target=_v278_bg_worker,
            args=(str(db_path),jid_new,limit0,False,done0,total0),
            daemon=True,
            name=f"autorace-bg-rerun-recover-{jid_new}",
        )
        with _V278_BG_LOCK:
            _V278_BG_THREADS[jid_new]=th
        th.start()
        return {"ok":True,"action":"restarted","old_job_id":jid_old,"job_id":jid_new,"done":done0,"total":total0,"reason":reason}
    except Exception as exc:
        return {"ok":False,"action":"error","reason":f"{type(exc).__name__}: {exc}"}

def _v290_recover_orphaned_batch_job(db_path: str, stale_seconds: float = 90.0) -> dict:
    try:
        _v278_bg_ensure_table(db_path)
        with sqlite3.connect(str(db_path),timeout=0.8) as con:
            con.row_factory=sqlite3.Row
            con.execute("PRAGMA busy_timeout=800")
            row=con.execute("""
                SELECT *
                  FROM v278_background_jobs
                 WHERE job_type='batch_rerun'
                   AND status IN ('queued','running','pause_requested','paused','cancel_requested')
                 ORDER BY job_id DESC
                 LIMIT 1
            """).fetchone()
        if not row:
            return {"ok":True,"action":"none"}

        job=dict(row)
        jid=int(job.get("job_id") or 0)
        if not jid:
            return {"ok":True,"action":"none"}

        th=None
        try:
            with _V278_BG_LOCK:
                th=_V278_BG_THREADS.get(jid)
        except Exception:
            th=None
        alive=bool(th is not None and getattr(th,"is_alive",lambda:False)())

        updated_ts=_v290_parse_job_time(job.get("updated_at"))
        age=max(0.0,time_module.time()-updated_ts) if updated_ts else 999999.0

        # threadが無いなら即復旧。threadがあっても進捗DB更新が150秒以上無ければstale扱い。
        if not alive:
            return _v290_spawn_recovery_worker(db_path,job,"実行threadが存在しません")
        if age >= float(stale_seconds):
            return _v290_spawn_recovery_worker(db_path,job,f"進捗更新が{int(age)}秒ありません")

        return {"ok":True,"action":"alive","job_id":jid,"age_seconds":round(age,1)}
    except Exception as exc:
        return {"ok":False,"action":"error","reason":f"{type(exc).__name__}: {exc}"}

# Ver290 hotfix5: 自動復旧・自動再開は行わない。停止後の再開はユーザー操作に限定。
_v290_orphan_recovery={"ok":True,"action":"manual_control"}


def _v290_manual_resume_batch(db_path: str, job: dict) -> dict:
    """停止済み/停止要求済みjobを、ユーザー操作時だけ残りから再開する。"""
    try:
        if not isinstance(job,dict) or not job:
            return {"ok":False,"reason":"再開対象jobがありません。"}
        old_jid=int(job.get("job_id") or 0)
        done0=int(job.get("done_count") or 0)
        total0=int(job.get("total_count") or 0)
        limit0=max(1,int(job.get("limit_count") or total0 or 80))
        now=_v228_now_jst_iso()

        with sqlite3.connect(str(db_path),timeout=1.0) as con:
            con.execute("PRAGMA busy_timeout=1000")
            con.execute("""
                UPDATE v278_background_jobs
                   SET status='cancelled',
                       cancel_requested=1,
                       pause_requested=0,
                       finished_at=COALESCE(finished_at,?),
                       message='手動再開のため新しいjobへ引継ぎ',
                       updated_at=?
                 WHERE job_id=?
            """,(now,now,old_jid))
            con.commit()

        with sqlite3.connect(str(db_path),timeout=1.0) as con:
            con.execute("PRAGMA busy_timeout=1000")
            cur=con.execute("""
                INSERT INTO v278_background_jobs(
                    job_type,app_version,status,created_at,updated_at,started_at,
                    limit_count,force_current,done_count,total_count,current_label,message
                ) VALUES ('batch_rerun',?,'running',?,?,?,?,0,?,?,?,?)
            """,(
                str(_V231_APP_VERSION),now,now,now,limit0,
                done0,total0,str(job.get("current_label") or ""),
                f"{done0}/{total0}から手動再開しました。"
            ))
            con.commit()
            new_jid=int(cur.lastrowid or 0)

        th=threading.Thread(
            target=_v278_bg_worker,
            args=(str(db_path),new_jid,limit0,False,done0,total0),
            daemon=True,
            name=f"autorace-bg-rerun-manual-resume-{new_jid}",
        )
        with _V278_BG_LOCK:
            _V278_BG_THREADS[new_jid]=th
        th.start()
        return {"ok":True,"job_id":new_jid,"done":done0,"total":total0}
    except Exception as exc:
        return {"ok":False,"reason":f"{type(exc).__name__}: {exc}"}


# Ver279: 通常1R予測をStreamlit描画スレッドから分離してバックグラウンド実行する。
# 計算式・seed・試行回数・6周展開は通常予測と同一。画面操作だけを解放する。
_V279_BG_PRED_THREADS = globals().get("_V279_BG_PRED_THREADS", {})
_V279_BG_PRED_LOCK = globals().get("_V279_BG_PRED_LOCK", threading.Lock())


def _v279_bg_prediction_get_latest(db_path: str) -> dict:
    try:
        _v278_bg_ensure_table(db_path)
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.row_factory=sqlite3.Row
            con.execute("PRAGMA busy_timeout=30000")
            row=con.execute("""
                SELECT * FROM v278_background_jobs
                WHERE job_type='normal_prediction'
                ORDER BY job_id DESC LIMIT 1
            """).fetchone()
        if not row:
            return {}
        d=dict(row)
        blob=d.get("result_blob")
        if blob:
            try:
                d["result"]=pickle.loads(zlib.decompress(bytes(blob)))
            except Exception:
                d["result"]={}
        else:
            d["result"]={}
        return d
    except Exception:
        return {}


def _v301_bg_input_fingerprint(raw_text: str, venue_override: str, excluded: list[int] | None = None) -> str:
    """BG予測開始時の入力を固定するための軽量指紋。表示制御専用。"""
    try:
        src=(str(venue_override or "").strip()+"\n"+str(raw_text or "").strip()+"\n"+
             ",".join(str(int(x)) for x in sorted(excluded or [])))
        return hashlib.sha256(src.encode("utf-8",errors="replace")).hexdigest()[:24]
    except Exception:
        return ""


def _v301_bg_completed_view_matches(job: dict, view: dict, raw_text: str, venue_override: str) -> tuple[bool,str]:
    """完了ジョブと読み込んだ履歴が同一レース・同一ジョブ由来かを検証する。"""
    try:
        result=(job or {}).get("result") or {}
        expected_job=int((job or {}).get("job_id") or 0)
        expected_race=str(result.get("race_key") or "").strip()
        expected_fp=str(result.get("input_fingerprint") or "").strip()
        actual_race=str((view or {}).get("race_key") or "").strip()
        actual_job=int((view or {}).get("_v301_bg_job_id") or 0)
        actual_fp=str((view or {}).get("_v301_bg_input_fingerprint") or "").strip()
        if expected_job and actual_job and expected_job!=actual_job:
            return False,f"job_id不一致 expected={expected_job} actual={actual_job}"
        if expected_race and actual_race and expected_race!=actual_race:
            return False,f"race_key不一致 expected={expected_race} actual={actual_race}"
        if expected_fp and actual_fp and expected_fp!=actual_fp:
            return False,"入力指紋不一致"
        # 新修正版で保存されたジョブは3項目を必須にする。
        if expected_fp and (not actual_job or not actual_fp or not actual_race):
            return False,"BG結果の識別情報が不足"
        return True,""
    except Exception as exc:
        return False,f"照合エラー: {type(exc).__name__}: {exc}"


def _v279_bg_prediction_any_active(db_path: str) -> bool:
    try:
        _v278_bg_ensure_table(db_path)
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.execute("PRAGMA busy_timeout=30000")
            row=con.execute("""
                SELECT COUNT(*) FROM v278_background_jobs
                WHERE job_type IN ('normal_prediction','batch_rerun')
                  AND status IN ('queued','running','pause_requested','paused','cancel_requested')
            """).fetchone()
        return bool(int(row[0] or 0))
    except Exception:
        return False




def _v284_apply_simulation_joint_ranks(df: pd.DataFrame, audit: dict) -> pd.DataFrame:
    """6周展開シミュレーションの共同分布を最終順位として採用する。"""
    try:
        if not isinstance(df,pd.DataFrame) or df.empty or not isinstance(audit,dict):
            return df
        car_col="車" if "車" in df.columns else ("車番" if "車番" in df.columns else None)
        if car_col is None:
            return df
        expected=audit.get("finish_expected_rank") or {}
        tops=audit.get("top_scenarios") or []
        joint=[]
        if tops:
            joint=[int(x) for x in str(tops[0].get("combo") or "").split("-") if str(x).strip().isdigit()]
        cars=[int(x) for x in pd.to_numeric(df[car_col],errors="coerce").dropna().astype(int).tolist()]
        if len(joint)<3:
            joint=sorted(cars,key=lambda c:(float(expected.get(str(c),99.0)),c))[:3]
        rest=sorted([c for c in cars if c not in joint],
                    key=lambda c:(float(expected.get(str(c),99.0)),c))
        order=joint[:3]+rest
        rank_map={c:i+1 for i,c in enumerate(order)}
        out=df.copy()
        out["Ver284_展開最終順位"]=pd.to_numeric(out[car_col],errors="coerce").map(
            lambda x: rank_map.get(int(x),99) if pd.notna(x) else 99
        )
        out["Ver284_展開平均着順"]=pd.to_numeric(out[car_col],errors="coerce").map(
            lambda x: round(float(expected.get(str(int(x)),99.0)),3) if pd.notna(x) else 99.0
        )
        out["改善後順位"]=out["Ver284_展開最終順位"].astype(int)
        out["順位整合メモ"]="Ver284:6周展開共同分布を最終結果として採用"
        return out
    except Exception:
        return df


def _v283_apply_top3_priority_ranks(df: pd.DataFrame) -> pd.DataFrame:
    """1～3着を目的にしたVer283最終順位整合。

    - 1位はVer196の本番1着率1位を固定（勝者予測を壊さない）
    - 2・3位候補は本番3着内率の上位から選ぶ
    - 2位/3位の順序は推定2着率（本番連対率-本番1着率）を優先
    - 4位以下は従来の改善後順位の相対順を維持
    """
    try:
        if not isinstance(df, pd.DataFrame) or df.empty:
            return df
        required = {"車", "改善後順位", "本番1着率", "本番3着内率"}
        if not required.issubset(set(df.columns)):
            return df

        out = df.copy()
        _cars = pd.to_numeric(out["車"], errors="coerce")
        _rank = pd.to_numeric(out["改善後順位"], errors="coerce")
        _win = pd.to_numeric(out["本番1着率"], errors="coerce").fillna(-1.0)
        _top3 = pd.to_numeric(out["本番3着内率"], errors="coerce").fillna(-1.0)
        if "本番連対率" in out.columns:
            _place2 = (
                pd.to_numeric(out["本番連対率"], errors="coerce").fillna(0.0)
                - pd.to_numeric(out["本番1着率"], errors="coerce").fillna(0.0)
            ).clip(lower=0.0)
        else:
            _place2 = _top3.clip(lower=0.0) - _win.clip(lower=0.0)

        valid_idx = [
            i for i in out.index
            if pd.notna(_cars.loc[i]) and pd.notna(_rank.loc[i])
        ]
        if len(valid_idx) < 3:
            return out

        # Ver196の1位を維持。万一rank=1が無ければ本番1着率最大。
        rank1 = [i for i in valid_idx if int(_rank.loc[i]) == 1]
        if rank1:
            winner_idx = rank1[0]
        else:
            winner_idx = max(valid_idx, key=lambda i: (float(_win.loc[i]), float(_top3.loc[i]), -int(_cars.loc[i])))

        # 2・3着候補は3着内率を主軸に2台だけ選ぶ。
        remaining = [i for i in valid_idx if i != winner_idx]
        top3_candidates = sorted(
            remaining,
            key=lambda i: (
                -float(_top3.loc[i]),
                -float(_place2.loc[i]),
                -float(_win.loc[i]),
                int(_cars.loc[i]),
            )
        )[:2]

        # 2着率を優先して2位/3位を並べる。
        top3_candidates = sorted(
            top3_candidates,
            key=lambda i: (
                -float(_place2.loc[i]),
                -float(_win.loc[i]),
                -float(_top3.loc[i]),
                int(_cars.loc[i]),
            )
        )

        first3 = [winner_idx] + top3_candidates

        # 4着以下はVer196の既存順位をそのまま相対維持。
        rest = sorted(
            [i for i in valid_idx if i not in set(first3)],
            key=lambda i: (float(_rank.loc[i]), int(_cars.loc[i]))
        )
        ordered = first3 + rest

        new_rank = {idx: pos + 1 for pos, idx in enumerate(ordered)}
        out["Ver283_TOP3優先前順位"] = _rank
        out["Ver283_推定2着率"] = _place2.round(3)
        out["Ver283_TOP3候補"] = False
        for idx in first3:
            out.loc[idx, "Ver283_TOP3候補"] = True
        for idx, rank_no in new_rank.items():
            out.loc[idx, "改善後順位"] = int(rank_no)

        if "順位整合メモ" in out.columns:
            old_note = out["順位整合メモ"].fillna("").astype(str)
            out["順位整合メモ"] = old_note.apply(
                lambda x: (x + " / " if x else "") + "Ver283:1着固定＋TOP3優先"
            )
        else:
            out["順位整合メモ"] = "Ver283:1着固定＋TOP3優先"

        return out
    except Exception:
        # 安全側: 何かあればVer196順位をそのまま使う。
        return df


def _v279_send_bg_prediction_complete_notification(result: dict) -> None:
    try:
        topic=str(os.environ.get("AUTORACE_NTFY_TOPIC", "notify") or "notify").strip()
        if not topic or any(ch in topic for ch in "/?# "):
            return
        label=str((result or {}).get("race_label") or (result or {}).get("race_key") or "1R予測")
        payload={
            "topic":topic,
            "title":"AutoRaceAI 予測完了",
            "message":f"{label} のバックグラウンド予測が完了しました。",
            "priority":4,
            "tags":["checkered_flag"],
        }
        request=urllib.request.Request(
            "https://ntfy.sh",
            data=json.dumps(payload,ensure_ascii=False).encode("utf-8",errors="strict"),
            method="POST",
            headers={"Content-Type":"application/json; charset=utf-8"},
        )
        with urllib.request.urlopen(request,timeout=8) as response:
            response.read()
    except Exception:
        pass


def _v279_bg_prediction_worker(db_path: str, job_id: int, request_data: dict) -> None:
    try:
        _v278_bg_update(
            db_path,job_id,status="running",started_at=_v228_now_jst_iso(),
            done_count=0,total_count=4,current_label="基礎予測",message="基礎予測を実行しています。"
        )
        raw_text=str(request_data.get("raw_text") or "")
        venue_override=str(request_data.get("venue_override") or "")
        trials=int(request_data.get("trials") or 20000)
        seed=int(request_data.get("seed") or 42)
        excluded=[int(x) for x in (request_data.get("excluded") or [])]
        prediction_text=raw_text
        if venue_override:
            prediction_text=f"開催場: {venue_override}\n"+raw_text

        timing={}
        _v276_foreground_prediction_event.set()
        with _V276ForegroundPredictionPriority(db_path):
            _t0=time_module.perf_counter()
            df,bets,output,entries,meta=engine.ver16_run_prediction(
                prediction_text,trials,seed,manual_excluded=excluded
            )
            entries=_v276_mark_retrial_from_prediction_text(entries,prediction_text)
            df=_v276_copy_retrial_to_prediction_df(df,entries)
            _t_base=time_module.perf_counter()
            _v278_bg_update(db_path,job_id,done_count=1,current_label="6周展開",message="6周展開を計算しています。")

            meta=dict(meta or {})
            df,bets,wall_audit=_v230_six_lap_simulation(df,bets,entries,meta,trials,seed)
            # 単発バックグラウンド予測の進捗はv278_background_jobsへ直接更新する。
            meta["壁補正監査"]=wall_audit
            meta["6周展開シミュレーション"]=wall_audit
            _t1=time_module.perf_counter()
            _v278_bg_update(db_path,job_id,done_count=2,current_label="確率集計",message="着順・券種別確率を集計しています。")

            finish_prob=engine.v30_finish_probabilities(df,bets,trials)
            _v273_audit_keep={c:df[c].copy() for c in df.columns if str(c).startswith("Ver273_")}
            df = _v284_apply_simulation_joint_ranks(df, wall_audit)
            for _c273,_s273 in _v273_audit_keep.items():
                try:
                    if len(_s273)==len(df):
                        df[_c273]=list(_s273)
                except Exception:
                    pass
            _t2=time_module.perf_counter()

        _v276_foreground_prediction_event.clear()
        _v278_bg_update(db_path,job_id,done_count=3,current_label="保存",message="予測履歴を保存しています。")
        _t_save0=time_module.perf_counter()
        race_key=engine.v34_save_prediction_snapshot(meta,df,finish_prob,engine.DB_PATH)
        _t_save1=time_module.perf_counter()
        _v217_deferred_prediction_db_save(meta,bets,trials,df)
        timing={
            "base_prediction":_t_base-_t0,
            "six_lap":_t1-_t_base,
            "six_lap_prepare":float((wall_audit or {}).get("prepare_seconds",0.0) or 0.0),
            "six_lap_simulation":float((wall_audit or {}).get("simulation_seconds",0.0) or 0.0),
            "simulation":_t1-_t0,
            "aggregation":_t2-_t1,
            "db_save":_t_save1-_t_save0,
            "deferred_db_save":True,
            "total":_t_save1-_t0,
        }
        prediction_view={
            "df":df,"bets":bets,"output":output,"entries":entries,"meta":meta,
            "finish_prob":finish_prob,"race_key":race_key,"trials":trials,"excluded":excluded,
            "learning_boundary":{},"future_audit":{},"day_trend":{},"prediction_timing":timing,
            "app_version":_V231_APP_VERSION,"simulation_mode":_V231_SIMULATION_MODE,
            "settings_hash":_v231_settings_hash(trials,seed,excluded),
            "prediction_time":_v228_now_jst_iso(),"seed":seed,
            "rerun_from_restored":bool(request_data.get("rerun_from_restored", False)),
            "rerun_source_version":str(request_data.get("rerun_source_version") or ""),
            "rerun_source_history_id":int(request_data.get("rerun_source_history_id") or 0),
            "background_prediction":True,
            "_v301_bg_job_id":int(job_id),
            "_v301_bg_input_fingerprint":str(request_data.get("_v301_bg_input_fingerprint") or ""),
        }
        history_id=_v231_save_prediction_history(
            db_path,race_key,raw_text,venue_override,prediction_view,trials,seed
        )
        _v222_save_prediction_restore(db_path,race_key,raw_text,venue_override,prediction_view)
        try:
            meta0=prediction_view.get("meta") or {}
            label=_v222_race_label(meta0,race_key)
        except Exception:
            label=str(race_key)
        result={
            "history_id":int(history_id or 0),"race_key":str(race_key),"race_label":str(label),
            "app_version":str(_V231_APP_VERSION),"timing":timing,
            "rerun_from_restored":bool(request_data.get("rerun_from_restored", False)),
            "rerun_source_version":str(request_data.get("rerun_source_version") or ""),
            "rerun_source_history_id":int(request_data.get("rerun_source_history_id") or 0),
            "job_id":int(job_id),
            "input_fingerprint":str(request_data.get("_v301_bg_input_fingerprint") or ""),
        }
        blob=zlib.compress(pickle.dumps(result,protocol=pickle.HIGHEST_PROTOCOL),level=6)
        _v278_bg_update(
            db_path,job_id,status="completed",finished_at=_v228_now_jst_iso(),done_count=4,total_count=4,
            current_label="",
            message=(
                f"復元内容の再シミュレーション完了：{label}"
                if bool(request_data.get("rerun_from_restored", False))
                else f"予測完了：{label}"
            ),
            result_blob=sqlite3.Binary(blob)
        )
        _v279_send_bg_prediction_complete_notification(result)
    except Exception as exc:
        _v276_foreground_prediction_event.clear()
        _v278_bg_update(
            db_path,job_id,status="failed",finished_at=_v228_now_jst_iso(),current_label="",
            message="バックグラウンド予測でエラーが発生しました。",
            error_text=f"{type(exc).__name__}: {exc}",
        )
    finally:
        _v276_foreground_prediction_event.clear()
        try:
            with _V279_BG_PRED_LOCK:
                _V279_BG_PRED_THREADS.pop(int(job_id),None)
        except Exception:
            pass


def _v279_bg_prediction_start(
    db_path: str, raw_text: str, venue_override: str, trials: int, seed: int, excluded: list[int],
    rerun_from_restored: bool = False, rerun_source_version: str = "", rerun_source_history_id: int = 0,
) -> dict:
    _v278_bg_ensure_table(db_path)
    if _v279_bg_prediction_any_active(db_path):
        return {"ok":False,"reason":"別の予測または再シミュレーションが動いています。完了後に開始してください。"}
    if not str(raw_text or "").strip():
        return {"ok":False,"reason":"出走表が空です。"}
    now=_v228_now_jst_iso()
    job_type = "restored_rerun_prediction" if bool(rerun_from_restored) else "normal_prediction"
    start_message = (
        "復元内容のバックグラウンド再シミュレーションを開始します。"
        if bool(rerun_from_restored) else "バックグラウンド予測を開始します。"
    )
    with sqlite3.connect(str(db_path),timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        cur=con.execute("""
            INSERT INTO v278_background_jobs(
                job_type,app_version,status,created_at,updated_at,limit_count,force_current,
                done_count,total_count,current_label,message
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?)
        """,(
            job_type,str(_V231_APP_VERSION),"queued",now,now,1,0,0,4,"準備中",start_message
        ))
        con.commit(); job_id=int(cur.lastrowid or 0)
    _excluded301=[int(x) for x in (excluded or [])]
    _input_fp301=_v301_bg_input_fingerprint(str(raw_text),str(venue_override or ""),_excluded301)
    request_data={
        "raw_text":str(raw_text),"venue_override":str(venue_override or ""),"trials":int(trials),
        "seed":int(seed),"excluded":_excluded301,
        "_v301_bg_job_id":int(job_id),"_v301_bg_input_fingerprint":_input_fp301,
        "rerun_from_restored":bool(rerun_from_restored),
        "rerun_source_version":str(rerun_source_version or ""),
        "rerun_source_history_id":int(rerun_source_history_id or 0),
    }
    th=threading.Thread(
        target=_v279_bg_prediction_worker,args=(str(db_path),job_id,request_data),daemon=True,
        name=f"autorace-bg-prediction-{job_id}",
    )
    with _V279_BG_PRED_LOCK:
        _V279_BG_PRED_THREADS[job_id]=th
    th.start()
    return {"ok":True,"job_id":job_id}


def _v279_bg_prediction_load_completed(db_path: str, job: dict) -> tuple[dict,str,str]:
    try:
        result=(job or {}).get("result") or {}
        hid=int(result.get("history_id") or 0)
        if not hid:
            return {},"",""
        view,raw_text,venue_override,_meta=_v231_load_prediction_history(db_path,hid)
        view=(view if isinstance(view,dict) else {})
        _ok301,_why301=_v301_bg_completed_view_matches(job,view,str(raw_text or ""),str(venue_override or ""))
        if not _ok301:
            return {},"",""
        return view,str(raw_text or ""),str(venue_override or "")
    except Exception:
        return {},"",""


def _v310_auto_diagnostic_race_keys(db_path: str, current_ver: str, limit: int) -> list[str]:
    """直前2版で買い目差分が大きいレースを自動選定する。"""
    m=re.match(r'^Ver(\d+)$',str(current_ver or ''))
    if not m: return []
    n=int(m.group(1)); newer=f'Ver{n-1}'; older=f'Ver{n-2}'
    try:
        with sqlite3.connect(str(db_path)) as con:
            keys=[r[0] for r in con.execute('SELECT DISTINCT race_key FROM v187_mixed_plan_runs WHERE app_version=?',(newer,))]
            scored=[]
            for rk in keys:
                rows={v:con.execute('SELECT plan_hash FROM v187_mixed_plan_runs WHERE race_key=? AND app_version=? ORDER BY created_at DESC LIMIT 1',(rk,v)).fetchone() for v in (older,newer)}
                if not all(rows.values()): continue
                def sig(v):
                    return [(r[0],r[1],round(float(r[2] or 0),5)) for r in con.execute('SELECT bet_type,combination,probability FROM v187_mixed_plan_tickets WHERE race_key=? AND plan_hash=?',(rk,rows[v][0]))]
                a,b=sig(older),sig(newer); diff=len(set(a)^set(b))+abs(len(a)-len(b))*2
                if diff: scored.append((diff,str(rk)))
            return [rk for _d,rk in sorted(scored,reverse=True)[:max(1,int(limit))]]
    except Exception:
        return []


def _v262_batch_rerun_saved_histories(db_path: str, limit: int = 120, progress_cb=None, force_current: bool = False, cancel_cb=None, pause_cb=None, diagnostic_auto: bool = False) -> dict:
    out={
        "checked":0,"rerun":0,"skipped_current":0,"no_text":0,"errors":[],"labels":[],
        "roi_evaluated":0,"roi_no_odds":0,"roi_no_payout":0,
        "roi_cost_yen":0,"roi_payout_yen":0,"roi_hits":0,"roi_rows":[],
        "roi_plus_cost_yen":0,"roi_plus_payout_yen":0,"roi_plus_extra_points":0,
    }
    current_ver=str(globals().get('_V231_APP_VERSION') or 'Ver304')
    # Ver289 hotfix:
    # limitは「履歴行数」ではなく「重複を除いたレース数」として扱う。
    # 旧実装は最新limit件の履歴行だけ取得してからrace_key重複除去していたため、
    # Ver284/285/286/287/288など同一レースの複数版が増えるほど
    # 80指定でも30R程度まで候補が縮むことがあった。
    try:
        _v231_ensure_prediction_history_table(db_path)
        with sqlite3.connect(str(db_path),timeout=30.0) as _con289:
            _con289.row_factory=sqlite3.Row
            # 現行版を明示的に優先する。同一レースの別版を「最新履歴」という
            # 理由だけで拾うと、Ver309の再実行がVer308/307の学習状態・設定を
            # 入力にしてしまい、版間比較の入力が混ざる。
            _rows289=_con289.execute("""
                WITH ranked AS (
                    SELECT h.history_id,h.race_key,h.race_label,h.app_version,h.simulation_mode,
                           h.settings_hash,h.prediction_time,h.trials,h.seed,
                           ROW_NUMBER() OVER (
                               PARTITION BY h.race_key
                               ORDER BY CASE WHEN h.app_version=? THEN 0 ELSE 1 END,
                                        h.history_id DESC
                           ) AS rn
                    FROM v231_prediction_history h
                    WHERE h.race_key IS NOT NULL AND TRIM(h.race_key)<>''
                )
                SELECT history_id,race_key,race_label,app_version,simulation_mode,
                       settings_hash,prediction_time,trials,seed
                FROM ranked
                WHERE rn=1
                ORDER BY prediction_time DESC,history_id DESC
            """, (current_ver,)).fetchall()
        histories=[dict(r) for r in _rows289]
    except Exception:
        histories=_v231_list_prediction_histories(db_path,max(1,int(limit)))

    # Ver304 hotfix2:
    # v231履歴が無い過去レースも、v222保存入力または
    # 結果DBの「事前判明項目だけ」から安全に再構成して候補へ追加する。
    try:
        histories.extend(_v304_missing_full_replay_records(db_path,current_ver))
    except Exception:
        pass

    # 既にSQL側でrace_keyごと最新1件だが、旧DB/フォールバック時の安全用に重複除去。
    unique=[]; seen=set()
    for h in histories:
        rk=str(h.get('race_key') or '').strip()
        if not rk or rk in seen:
            continue
        seen.add(rk); unique.append(h)
    if diagnostic_auto:
        _diag_keys310=set(_v310_auto_diagnostic_race_keys(db_path,current_ver,max(1,int(limit))))
        unique=[h for h in unique if str(h.get('race_key') or '').strip() in _diag_keys310]
        if not unique:
            out['message']='自動診断対象の版間買い目差分が見つかりません。'
            out['candidate_total']=0
            return out
    # Ver276 speed: race_key から日付・場・Rを直接読める通常ケースでは、
    # 並び替えのためだけに圧縮payloadを展開しない。旧形式だけ従来処理へフォールバックする。
    _prep_t0_v276=time_module.perf_counter()
    chronological=[]
    for h in unique:
        _hid=int(h.get('history_id') or 0)
        _rk=str(h.get('race_key') or '').strip()
        _m276=re.match(r'^(\d{8})_(.+?)_(\d+)R$',_rk)
        if _m276:
            _d8,_venue,_rno_s=_m276.groups()
            _date=f"{_d8[:4]}-{_d8[4:6]}-{_d8[6:8]}"
            chronological.append((_date,_venue,int(_rno_s),_hid,h))
            continue
        try:
            _v, _raw, _vo, _hm = _v231_load_prediction_history(db_path, _hid)
            _mm = (_v or {}).get('meta') or {}
            _date = str(_mm.get('開催日') or _mm.get('日付') or _mm.get('race_date') or _mm.get('date') or '')[:10]
            _venue = str(_mm.get('開催場') or _mm.get('場') or _mm.get('venue') or _mm.get('track') or '')
            _rraw = str(_mm.get('R') or _mm.get('レース') or _mm.get('レース番号') or _mm.get('race_no') or _mm.get('race') or '')
            _rm = re.search(r'\d+', _rraw)
            _rno = int(_rm.group()) if _rm else 999
            chronological.append((_date, _venue, _rno, _hid, h))
        except Exception:
            chronological.append(('9999-99-99','',999,_hid,h))
    chronological.sort(key=lambda x:(x[0],x[1],x[2],x[3]))
    unique=[x[4] for x in chronological]

    total=len(unique)
    # Ver276 speed: 現行Ver済み判定を N件のpayload展開 + N回COUNT から、
    # まとめSQL + 対象レースの最新payloadだけの確認へ変更。予測値・スキップ条件は変更しない。
    current_keys=set()
    current_complete_keys=set()
    current_audit_complete_keys=set()
    try:
        _v231_ensure_prediction_history_table(db_path)
        _target_keys276={str(x.get('race_key') or '').strip() for x in unique if str(x.get('race_key') or '').strip()}
        _latest_current276={}
        with sqlite3.connect(str(db_path)) as con:
            _v252_ensure_lap_tables(con)
            rows=con.execute(
                "SELECT race_key, MAX(history_id) FROM v231_prediction_history WHERE app_version=? GROUP BY race_key",
                (current_ver,)
            ).fetchall()
            current_keys={str(r[0]) for r in rows if r and r[0]}
            _latest_current276={str(r[0]):int(r[1]) for r in rows if r and r[0] and r[1]}

            # 6周保存済み判定も1レースずつCOUNTせず一括取得。
            lap_rows=con.execute(
                """SELECT race_date,venue,race_no,COUNT(DISTINCT lap_no)
                   FROM v252_lap_prediction_snapshots
                   WHERE app_version=?
                   GROUP BY race_date,venue,race_no
                   HAVING COUNT(DISTINCT lap_no)>=6""",
                (current_ver,)
            ).fetchall()
            _lap_complete276=set()
            for _d,_v,_r,_n in lap_rows:
                _d8=re.sub(r'[^0-9]','',str(_d or ''))[:8]
                _rn=re.sub(r'[^0-9]','',str(_r or ''))
                if _d8 and str(_v or '').strip() and _rn:
                    _lap_complete276.add(f"{_d8}_{str(_v).strip()}_{_rn}R")
            current_complete_keys=(_target_keys276 & current_keys & _lap_complete276)

        _audit_required273=[
            "Ver273_5周目ループ到達",
            "Ver273_5周目関数呼出",
            "Ver273_5周目再加速発動数",
            "Ver273_6周目ループ到達",
            "Ver273_6周目関数呼出",
            "Ver273_6周目再加速発動数",
        ]
        # 実際に今回スキップ候補になったレースだけpayloadを確認する。
        for _rk273 in current_complete_keys:
            _hid273=_latest_current276.get(_rk273)
            if not _hid273:
                continue
            try:
                cv,_,_,_cm=_v231_load_prediction_history(db_path,_hid273)
                _df273=(cv or {}).get('df')
                if (
                    _df273 is not None
                    and hasattr(_df273,'columns')
                    and all(c in _df273.columns for c in _audit_required273)
                ):
                    current_audit_complete_keys.add(_rk273)
            except Exception:
                pass
    except Exception:
        current_keys=set(); current_complete_keys=set(); current_audit_complete_keys=set()
    # Ver305 recommendation-only: 旧『再計算Ver305』は完了扱いにしない。
    # Ver304土台固定のoverlayプランまで作成済みのレースだけを完了扱いにする。
    if current_ver == 'Ver305':
        try:
            with sqlite3.connect(str(db_path)) as _c305done:
                _overlay305={str(r[0]) for r in _c305done.execute(
                    "SELECT DISTINCT race_key FROM v187_mixed_plan_runs WHERE app_version='Ver305' AND plan_origin=? AND COALESCE(include_in_live_stats,1)=1",
                    (_V305_REC_ONLY_ORIGIN,)
                ).fetchall() if r and r[0]}
            current_complete_keys=set(current_complete_keys) & _overlay305
            current_audit_complete_keys=set(current_audit_complete_keys) & _overlay305
        except Exception:
            current_complete_keys=set()
            current_audit_complete_keys=set()

    # Ver290 hotfix3:
    # 現行Verで6周+監査まで完全保存済みのレースは、ループ前に候補から除外する。
    # 再起動復旧時に「11/57から再開」したのに先頭11Rをもう一度数える問題を防ぐ。
    if not force_current:
        _already_complete290=set(current_complete_keys) & set(current_audit_complete_keys)
        if _already_complete290:
            _before290=len(unique)
            unique=[h for h in unique if str(h.get('race_key') or '').strip() not in _already_complete290]
            out['skipped_current'] += int(_before290-len(unique))

    # Ver304 hotfix:
    # 「保存履歴の最新limit件」を先に切るのではなく、現行Ver完了済みを除いた後でlimitを適用。
    # これで古い未処理レースが候補外へ押し出されるのを防ぐ。
    unique = unique[:max(1, int(limit))]
    total=len(unique)
    out['candidate_total']=int(total)
    out['prepare_seconds_v276']=round(time_module.perf_counter()-_prep_t0_v276,3)
    _run_t0_v276=time_module.perf_counter()
    for idx,h in enumerate(unique,1):
        if callable(cancel_cb):
            try:
                if bool(cancel_cb()):
                    out["cancelled"]=True
                    break
            except Exception:
                pass
        if callable(pause_cb):
            try:
                pause_cb()
            except Exception:
                pass
        if callable(cancel_cb):
            try:
                if bool(cancel_cb()):
                    out["cancelled"]=True
                    break
            except Exception:
                pass
        out['checked']+=1
        label=str(h.get('race_label') or h.get('race_key') or f'履歴{idx}')
        if h.get('_v304_input_source')=='result_prerace_safe_rebuild':
            label += "｜事前情報再構成"
        try:
            if callable(progress_cb):
                progress_cb(idx-1,total,label)
            race_key0=str(h.get('race_key') or '').strip()
            if (not force_current) and race_key0 in current_complete_keys and race_key0 in current_audit_complete_keys:
                out['skipped_current']+=1
                continue

            # Ver305は『Ver304の予測・6周・買い目固定 + 推奨だけ変更』として比較する。
            # Ver304保存済みならモデルを再計算せず、その保存値をそのまま複製する。
            if current_ver == 'Ver305' and _v305_latest_ver304_plan(db_path,race_key0):
                if callable(progress_cb):
                    progress_cb(idx-1,total,label+'｜Ver304土台を固定コピー中')
                _h305=_v305_clone_ver304_history(db_path,race_key0)
                _l305=_v305_clone_ver304_laps(db_path,race_key0)
                _p305=_v305_clone_ver304_plan_as_rec_only(db_path,race_key0)
                if not _p305.get('ok'):
                    raise RuntimeError('Ver304買い目固定コピー失敗: '+str(_p305.get('reason') or '不明'))
                # 実績はVer304買い目と完全同一。
                try:
                    with sqlite3.connect(str(db_path)) as _c305:
                        _fb305=_c305.execute(
                            'SELECT hit,cost_yen,payout_yen,return_rate FROM v187_mixed_plan_feedback WHERE race_key=? AND plan_hash=?',
                            (race_key0,str(_p305.get('plan_hash') or ''))
                        ).fetchone()
                    if _fb305:
                        out['roi_evaluated']+=1
                        out['roi_hits']+=int(bool(_fb305[0]))
                        out['roi_cost_yen']+=int(_fb305[1] or 0)
                        out['roi_payout_yen']+=int(_fb305[2] or 0)
                except Exception:
                    pass
                out['rerun']+=1
                out['labels'].append(
                    f"{label} → Ver305（Ver304予測・6周・買い目固定 / 推奨のみ再判定）"
                )
                current_keys.add(race_key0)
                current_complete_keys.add(race_key0)
                current_audit_complete_keys.add(race_key0)
                continue
            if str(h.get('_v304_raw_text') or '').strip():
                view=h.get('_v304_view') if isinstance(h.get('_v304_view'),dict) else {}
                raw_text=str(h.get('_v304_raw_text') or '')
                venue_override=str(h.get('_v304_venue_override') or '')
                hm={'app_version':str(h.get('app_version') or 'Unknown')}
            else:
                view, raw_text, venue_override, hm=_v231_load_prediction_history(db_path,int(h.get('history_id') or 0))
            if not str(raw_text or '').strip():
                out['no_text']+=1
                continue
            src_ver=str((hm or {}).get('app_version') or h.get('app_version') or (view or {}).get('app_version') or 'Unknown')
            trials=int(h.get('trials') or (view or {}).get('trials') or 20000)
            seed=int(h.get('seed') or (view or {}).get('seed') or 20260719)
            excluded=[int(x) for x in ((view or {}).get('excluded') or [])]

            # Ver305 reproducibility guard:
            # 保存時の学習状態があるレースは、その状態を復元してから再計算する。
            _state305=(view or {}).get("model_state_snapshot_v305")
            _state_restored305=False
            _state_source_hash305=""
            _state_current_hash305=""
            try:
                _state_current_hash305=engine.v305_model_state_fingerprint(db_path)
                if isinstance(_state305,dict) and _state305.get("state_hash"):
                    _state_source_hash305=str(_state305.get("state_hash") or "")
                    _state_restored305=bool(engine.v305_set_model_state_override(_state305))
            except Exception:
                _state_restored305=False

            prediction_text=str(raw_text)
            if str(venue_override or '').strip():
                prediction_text=f"開催場: {str(venue_override).strip()}\n"+prediction_text
            if callable(progress_cb):
                progress_cb(idx-1,total,label+"｜①基礎予測中")
            df,bets,output,entries,meta=engine.ver16_run_prediction(prediction_text,trials,seed,manual_excluded=excluded)
            _bets_before_lap310 = dict(bets or {})
            if callable(progress_cb):
                progress_cb(idx-1,total,label+"｜②6周展開中")
            entries=_v276_mark_retrial_from_prediction_text(entries,prediction_text)
            df=_v276_copy_retrial_to_prediction_df(df,entries)
            meta=dict(meta or {})
            df,bets,wall_audit=_v230_six_lap_simulation(df,bets,entries,meta,trials,seed)
            meta['壁補正監査']=wall_audit
            meta['6周展開シミュレーション']=wall_audit
            try:
                _v310_save_diagnostic(
                    db_path, str(race_key0),
                    {'meta':meta}, src_ver, _state_restored305,
                    _state_source_hash305, _state_current_hash305,
                    _bets_before_lap310, dict(bets or {}), wall_audit, trials, seed,
                )
            except Exception:
                pass
            finish_prob=engine.v30_finish_probabilities(df,bets,trials)
            try:
                engine.v305_clear_model_state_override()
            except Exception:
                pass
            _v273_audit_keep={
                c:df[c].copy() for c in df.columns if str(c).startswith("Ver273_")
            }
            df = _v284_apply_simulation_joint_ranks(df, wall_audit)
            for _c273,_s273 in _v273_audit_keep.items():
                try:
                    if len(_s273)==len(df):
                        df[_c273]=list(_s273)
                except Exception:
                    pass
            race_key=engine.v34_save_prediction_snapshot(meta,df,finish_prob,engine.DB_PATH)
            prediction_view={
                'df':df,'bets':bets,'output':output,'entries':entries,'meta':meta,
                'finish_prob':finish_prob,'race_key':race_key,'trials':trials,'excluded':excluded,
                'learning_boundary':{},'future_audit':{},'day_trend':{},'prediction_timing':{},
                'app_version':current_ver,'simulation_mode':_V231_SIMULATION_MODE,
                'settings_hash':_v231_settings_hash(trials,seed,excluded),
                'prediction_time':_v228_now_jst_iso(),'seed':seed,
                'rerun_from_restored':True,'rerun_source_version':src_ver,
                'rerun_source_history_id':int(h.get('history_id') or 0),
                'batch_rerun':True,'walk_forward_v269':True,
                'input_source_v304':str(h.get('_v304_input_source') or 'v231_prediction_history'),
                'input_reconstructed_v304':bool(h.get('_v304_input_source')=='result_prerace_safe_rebuild'),
                'input_rebuild_audit_v304':h.get('_v304_rebuild_audit') if isinstance(h.get('_v304_rebuild_audit'),dict) else {},
                'model_state_restored_v305':bool(_state_restored305),
                'source_model_state_hash_v305':str(_state_source_hash305 or ''),
                'current_model_state_hash_before_rerun_v305':str(_state_current_hash305 or ''),
                'v310_diagnostic':{
                    'source_prediction_version':str(src_ver or ''),
                    'model_state_restored':bool(_state_restored305),
                    'source_model_state_hash':str(_state_source_hash305 or ''),
                    'current_model_state_hash':str(_state_current_hash305 or ''),
                    'trials':int(trials or 0),'seed':int(seed or 0),
                    'bets_before_lap_hash':_v310_fingerprint(_bets_before_lap310) if '_v310_fingerprint' in globals() else '',
                    'bets_after_lap_hash':_v310_fingerprint(bets) if '_v310_fingerprint' in globals() else '',
                },
                'legacy_model_state_missing_v305':not bool(
                    isinstance(_state305,dict) and _state305.get("state_hash")
                ),
            }
            hid=_v231_save_prediction_history(db_path,race_key,raw_text,venue_override,prediction_view,trials,seed)
            if callable(progress_cb):
                progress_cb(idx-1,total,label+"｜④周回保存中")
            _v222_save_prediction_restore(db_path,race_key,raw_text,venue_override,prediction_view)
            # 一括再シミュレーションした予測は、同じ現行Verで1〜6周の代表隊列も必ず保存する。
            snap=_v260_snapshot_from_saved_view(db_path,prediction_view,current_ver)
            if not snap.get('ok'):
                raise RuntimeError(f"周回スナップショット保存失敗: {snap.get('reason','不明')}")

            # Ver272: 過去レースの仮想100円均等・回収率採点。
            # 保存済み最古オッズを全バージョン共通で使い、結果/払戻は採点にだけ使用する。
            if callable(progress_cb):
                progress_cb(idx-1,total,label+"｜⑤回収率採点中")
            _roi273=_v273_virtual_roi_score(
                db_path, race_key, bets, trials, meta, current_ver
            )
            if _roi273.get("evaluated"):
                out["roi_evaluated"]+=1
                out["roi_cost_yen"]+=int(_roi273.get("cost_yen",0) or 0)
                out["roi_payout_yen"]+=int(_roi273.get("payout_yen",0) or 0)
                out["roi_hits"]+=int(bool(_roi273.get("hit")))
                out["roi_plus_cost_yen"]+=int(
                    _roi273.get("virtual_combined_cost_yen",_roi273.get("cost_yen",0)) or 0
                )
                out["roi_plus_payout_yen"]+=int(
                    _roi273.get("virtual_combined_payout_yen",_roi273.get("payout_yen",0)) or 0
                )
                out["roi_plus_extra_points"]+=int(_roi273.get("virtual_extra_points",0) or 0)
            else:
                _reason273=str(_roi273.get("reason") or "")
                if "オッズ" in _reason273:
                    out["roi_no_odds"]+=1
                elif "払戻" in _reason273:
                    out["roi_no_payout"]+=1
            out["roi_rows"].append({
                "race": label,
                "race_key": race_key,
                "evaluated": bool(_roi273.get("evaluated")),
                "points": int(_roi273.get("points",0) or 0),
                "cost_yen": int(_roi273.get("cost_yen",0) or 0),
                "payout_yen": int(_roi273.get("payout_yen",0) or 0),
                "return_rate": _roi273.get("return_rate"),
                "hit": bool(_roi273.get("hit")),
                "virtual_extra_points":int(_roi273.get("virtual_extra_points",0) or 0),
                "virtual_extra_cost_yen":int(_roi273.get("virtual_extra_cost_yen",0) or 0),
                "virtual_extra_payout_yen":int(_roi273.get("virtual_extra_payout_yen",0) or 0),
                "virtual_combined_return_rate":_roi273.get("virtual_combined_return_rate"),
                "reason": str(_roi273.get("reason") or ""),
                "odds_created_at": str(_roi273.get("odds_created_at") or ""),
            })

            out['rerun']+=1
            out['labels'].append(f"{label} → {current_ver} (ID:{hid}, {int(snap.get('saved_laps',0) or 0)}周)")
            current_keys.add(str(race_key0 or race_key))
            current_complete_keys.add(str(race_key0 or race_key))
        except Exception as exc:
            out['errors'].append(f"{label}: {type(exc).__name__}: {exc}")
        finally:
            try:
                engine.v305_clear_model_state_override()
            except Exception:
                pass
            if callable(progress_cb):
                progress_cb(idx,total,label)
    out['race_processing_seconds_v276']=round(time_module.perf_counter()-_run_t0_v276,3)
    if int(out.get("roi_cost_yen",0) or 0) > 0:
        out["roi_return_rate"]=float(out["roi_payout_yen"])/float(out["roi_cost_yen"])*100.0
    else:
        out["roi_return_rate"]=None
    _force_note = " / 強制再計算ON" if force_current else ""
    out['message']=(f"確認{out['checked']}レース / {current_ver}再シミュレーション{out['rerun']} / "
                    f"監査列まで保存済み{out['skipped_current']} / 入力材料なし{out['no_text']} / エラー{len(out['errors'])}"
                    f"{_force_note} / 準備{float(out.get('prepare_seconds_v276',0) or 0):.2f}秒")
    return out

def _v252_lap_residual_calibration(db_path: str | None, venue: str, cutoff_date: str) -> dict:
    """予測代表隊列と後日判明した実測隊列の追越し差を時系列で縮小学習する。"""
    result={"enabled":False,"samples":0,"races":0,"delta":{},"reason":"予測・実測の周回ペア不足"}
    if not db_path or not Path(db_path).exists():
        return result
    try:
        stamp=(str(db_path),Path(db_path).stat().st_mtime_ns,str(venue),str(cutoff_date)[:10])
    except Exception:
        stamp=(str(db_path),str(venue),str(cutoff_date)[:10])
    if stamp in _V252_LAP_RESIDUAL_CACHE:
        return dict(_V252_LAP_RESIDUAL_CACHE[stamp])
    try:
        with sqlite3.connect(str(db_path)) as con:
            _v252_ensure_lap_tables(con)
            pred=pd.read_sql_query("""
                SELECT p.race_date,p.venue,p.race_no,p.lap_no,p.predicted_order,p.support,p.is_backtest,p.created_at
                FROM v252_lap_prediction_snapshots p
                WHERE p.is_backtest IN (0,2) AND p.app_version IN ('Ver253','Ver254','Ver256','Ver257','Ver259','Ver260')
                  AND (?='' OR p.venue=?)
                  AND (?='' OR substr(p.race_date,1,10)<substr(?,1,10))
                ORDER BY p.created_at
            """,con,params=(venue,venue,cutoff_date,cutoff_date))
            actual=pd.read_sql_query("""
                SELECT rr.race_date,rr.venue,REPLACE(COALESCE(rr.race_no,''),'R','') AS race_no,
                       rl.lap_no,rl.position,rl.car_no,
                       COALESCE(CAST(REPLACE(REPLACE(re.handicap,'m',''),'Ｍ','') AS INTEGER),0) AS handicap
                FROM result_laps rl
                JOIN result_races rr ON rr.race_key=rl.race_key
                LEFT JOIN races r ON r.race_key=rr.race_key
                LEFT JOIN race_entries re ON re.race_id=r.race_id AND re.car_no=rl.car_no
                WHERE COALESCE(rr.learning_eligible,1)=1
                  AND (?='' OR rr.venue=?)
                  AND (?='' OR substr(rr.race_date,1,10)<substr(?,1,10))
                ORDER BY rr.race_date,rr.venue,rr.race_no,rl.lap_no,rl.position
            """,con,params=(venue,venue,cutoff_date,cutoff_date))
    except Exception as exc:
        result['reason']=f'周回差分読込失敗: {exc}'
        return result
    if pred.empty or actual.empty:
        return result
    # 同一レース・周回は最新の予測だけ採用。
    pred=pred.sort_values('created_at').drop_duplicates(['race_date','venue','race_no','lap_no'],keep='last')
    amap={}
    hmaps={}
    for key,g in actual.groupby(['race_date','venue','race_no','lap_no'],dropna=False):
        gg=g.sort_values('position')
        amap[(str(key[0])[:10],str(key[1]),str(key[2]),int(key[3]))]=tuple(int(x) for x in gg.car_no.tolist())
        hmaps[(str(key[0])[:10],str(key[1]),str(key[2]),int(key[3]))]={int(r.car_no):int(r.handicap or 0) for r in gg.itertuples()}
    events=[]; race_keys=set()
    for row in pred.itertuples():
        key=(str(row.race_date)[:10],str(row.venue),str(row.race_no),int(row.lap_no))
        actual_order=amap.get(key)
        try: pred_order=tuple(int(x) for x in str(row.predicted_order).split('-') if str(x).strip())
        except Exception: continue
        if not actual_order or len(pred_order)<3: continue
        race_keys.add(key[:3]); hp=hmaps.get(key,{})
        # 各隣接ペアで「予測は抜く/実際は抜く」を比較する。
        # 前周の実測隊列を基準にするため、lap1は初期車列（ハンデ・車番順）を近似。
        prev_key=(key[0],key[1],key[2],key[3]-1)
        prev=amap.get(prev_key)
        if not prev:
            prev=tuple(sorted(actual_order,key=lambda c:(hp.get(c,0),c)))
        pp={c:i for i,c in enumerate(pred_order)}; ap={c:i for i,c in enumerate(actual_order)}
        for j in range(1,len(prev)):
            front,chaser=prev[j-1],prev[j]
            if front not in pp or chaser not in pp or front not in ap or chaser not in ap: continue
            pred_pass=int(pp[chaser]<pp[front]); actual_pass=int(ap[chaser]<ap[front])
            gap=max(0,hp.get(chaser,0)-hp.get(front,0))
            events.append((key[3],_v251_gap_bucket(gap),actual_pass-pred_pass,0.35 if int(getattr(row,'is_backtest',0) or 0)==2 else 1.0))
    if len(events)<60:
        result.update({'samples':len(events),'races':len(race_keys)})
        _V252_LAP_RESIDUAL_CACHE[stamp]=dict(result)
        return result
    ev=pd.DataFrame(events,columns=['lap','bucket','residual','weight'])
    deltas={}
    for (lap,bucket),g in ev.groupby(['lap','bucket']):
        n=len(g); effective_n=float(g['weight'].sum()); raw=float(np.average(g['residual'],weights=g['weight']))
        # 再構成データは0.35重み。正なら予測より実際の追越しが多い。
        shrunk=(effective_n/(effective_n+45.0))*raw
        deltas[f'{int(lap)}|{bucket}']={
            'delta':float(np.clip(shrunk*0.70,-0.24,0.24)),
            'raw_residual':raw,'n':int(n),'effective_n':round(effective_n,2)
        }
    result={'enabled':True,'samples':int(len(ev)),'races':int(len(race_keys)),
            'delta':deltas,'reason':'予測代表隊列と後日実測グランドノートの周回差を縮小学習'}
    _V252_LAP_RESIDUAL_CACHE.clear(); _V252_LAP_RESIDUAL_CACHE[stamp]=dict(result)
    return result


# Backward-compatible name used by the Ver253/Ver254 status panel.
# The implementation was renamed to *_calibration, but some UI code still called *_learning.
def _v252_lap_residual_learning(db_path: str | None, venue: str = "", cutoff_date: str = "") -> dict:
    return _v252_lap_residual_calibration(db_path, venue, cutoff_date)



# Ver257: Ver256の全実測周回学習に加え、race_entries→playersの選手名JOINを修正。
# 開催場×周回の実際の順位入替率を時系列で学習する。
# 少数開催場は全場平均へ縮小し、予測対象日以降の結果は混ぜない。
_V256_ACTUAL_LAP_CACHE = {}
_V256_SETTINGS_SYNC_CACHE = set()

def _v256_logit(p: float) -> float:
    p=max(0.02,min(0.98,float(p)))
    return float(np.log(p/(1.0-p)))

def _v256_actual_lap_calibration(db_path: str | None, venue: str = "", cutoff_date: str = "") -> dict:
    result={"enabled":False,"races":0,"pairs":0,"lap_delta":{},"rates":{},
            "reason":"実測グランドノート不足"}
    if not db_path or not Path(db_path).exists():
        return result
    try:
        stamp=(str(db_path),Path(db_path).stat().st_mtime_ns,str(venue),str(cutoff_date)[:10])
    except Exception:
        stamp=(str(db_path),str(venue),str(cutoff_date)[:10])
    if stamp in _V256_ACTUAL_LAP_CACHE:
        return dict(_V256_ACTUAL_LAP_CACHE[stamp])
    try:
        with sqlite3.connect(str(db_path)) as con:
            d=pd.read_sql_query("""
                SELECT substr(rr.race_date,1,10) AS race_date, rr.venue,
                       REPLACE(COALESCE(rr.race_no,''),'R','') AS race_no,
                       rl.lap_no, rl.position, rl.car_no
                FROM result_laps rl
                JOIN result_races rr ON rr.race_key=rl.race_key
                WHERE COALESCE(rr.learning_eligible,1)=1
                  AND rl.lap_no BETWEEN 1 AND 6
                  AND (?='' OR substr(rr.race_date,1,10)<substr(?,1,10))
                ORDER BY rr.race_date,rr.venue,rr.race_no,rl.lap_no,rl.position
            """,con,params=(cutoff_date,cutoff_date))
    except Exception as exc:
        result['reason']=f'全実測周回読込失敗: {exc}'
        return result
    if d.empty:
        return result
    events=[]; race_keys=set()
    for (race_date,v,race_no),g in d.groupby(['race_date','venue','race_no'],dropna=False):
        orders={int(l):tuple(int(x) for x in xg.sort_values('position').car_no.tolist())
                for l,xg in g.groupby('lap_no')}
        prev=None
        for lap in range(1,7):
            try:
                if int(lap) in (5,6):
                    late_release_audit_v273[int(lap)]["lap_seen"]+=1
            except Exception:
                pass
            cur=orders.get(lap)
            if not cur: continue
            if prev and len(prev)>=3 and len(cur)>=3:
                pos={c:i for i,c in enumerate(cur)}
                inv=pairs=0
                for i in range(len(prev)-1):
                    front,chaser=prev[i],prev[i+1]
                    if front in pos and chaser in pos:
                        pairs+=1; inv += int(pos[chaser] < pos[front])
                if pairs:
                    events.append((str(v),int(lap),int(inv),int(pairs)))
                    race_keys.add((str(race_date),str(v),str(race_no)))
            prev=cur
    if not events:
        return result
    ev=pd.DataFrame(events,columns=['venue','lap','passes','pairs'])
    global_stats=ev.groupby('lap',as_index=False)[['passes','pairs']].sum()
    global_rate={int(r.lap):(float(r.passes)+3.0)/(float(r.pairs)+12.0) for r in global_stats.itertuples()}
    use=ev[ev['venue'].astype(str)==str(venue)] if venue else ev
    local_stats=use.groupby('lap',as_index=False)[['passes','pairs']].sum()
    local_map={int(r.lap):(float(r.passes),float(r.pairs)) for r in local_stats.itertuples()}
    deltas={}; rates={}
    for lap in range(2,7):
        gp=float(global_rate.get(lap,0.22))
        passes,pairs=local_map.get(lap,(0.0,0.0))
        raw=(passes+3.0)/(pairs+12.0)
        shrink=pairs/(pairs+180.0)
        blended=shrink*raw+(1.0-shrink)*gp
        # ロジット差の35%だけ使い、1要素で展開を支配しない。
        delta=float(np.clip((_v256_logit(blended)-_v256_logit(gp))*0.35,-0.16,0.16))
        deltas[int(lap)]=delta
        rates[int(lap)]={'local_rate':round(raw,5),'blended_rate':round(blended,5),
                         'global_rate':round(gp,5),'pairs':int(pairs),'delta':round(delta,5)}
    result={'enabled':int(ev['pairs'].sum())>=300,'races':len(race_keys),
            'pairs':int(use['pairs'].sum()),'lap_delta':deltas,'rates':rates,
            'reason':'実測グランドノート全体の開催場×周回入替率を全場平均へ縮小学習'}
    _V256_ACTUAL_LAP_CACHE[stamp]=dict(result)
    return result

def _v256_refresh_learning_settings(db_path: str | None) -> dict:
    """周回実測で直接測れる設定だけを更新。未検証項目を推測で動かさない。"""
    out={'updated':0,'races':0,'pairs':0}
    if not db_path or not Path(db_path).exists(): return out
    try:
        sig=(str(db_path),Path(db_path).stat().st_mtime_ns)
    except Exception:
        sig=(str(db_path),)
    if sig in _V256_SETTINGS_SYNC_CACHE: return out
    cal=_v256_actual_lap_calibration(db_path,"","")
    if not cal.get('enabled'): return out
    rates=cal.get('rates') or {}
    early=np.mean([float((rates.get(l) or {}).get('blended_rate',0.22)) for l in (2,3)])
    late=np.mean([float((rates.get(l) or {}).get('blended_rate',0.18)) for l in (5,6)])
    vals={
        '前団維持': float(np.clip(0.68*(1.0+(0.24-early)*0.45),0.52,0.82)),
        '追い上げ': float(np.clip(0.62*(1.0+(early-0.24)*0.55),0.48,0.78)),
        '終盤': float(np.clip(0.58*(1.0+(late-0.18)*0.65),0.44,0.74)),
        '安定性': float(np.clip(0.55*(1.0-(np.std([float((rates.get(l) or {}).get('blended_rate',0.2)) for l in range(2,7)]))*0.8),0.45,0.66)),
    }
    try:
        with sqlite3.connect(str(db_path)) as con:
            race_count=con.execute("SELECT COUNT(*) FROM result_races WHERE COALESCE(learning_eligible,1)=1").fetchone()[0]
            for name,value in vals.items():
                cur=con.execute("SELECT initial_value FROM learning_settings WHERE setting_name=?",(name,)).fetchone()
                if not cur: continue
                con.execute("""UPDATE learning_settings
                               SET current_value=?,updated_at=CURRENT_TIMESTAMP,sample_races=?,reason=?
                               WHERE setting_name=?""",
                            (round(value,6),int(race_count),'Ver260: 全実測グランドノートの周回入替率＋選手別実測追抜学習を利用',name))
                out['updated']+=1
            con.commit()
        out.update({'races':int(race_count),'pairs':int(cal.get('pairs',0))})
        _V256_SETTINGS_SYNC_CACHE.add(sig)
    except Exception as exc:
        out['error']=str(exc)
    return out

# Ver254: 予測と実測の周回差を、選手別・周回別にも縮小学習する。
# 少数データは開催場全体へ強く縮小し、過学習と補正暴走を防ぐ。
_V254_PLAYER_LAP_CACHE = {}

def _v254_player_lap_calibration(db_path: str | None, venue: str, cutoff_date: str) -> dict:
    result={"enabled":False,"samples":0,"races":0,"player_delta":{},"reason":"選手別の予測・実測周回ペア不足"}
    if not db_path or not Path(db_path).exists():
        return result
    try:
        stamp=(str(db_path),Path(db_path).stat().st_mtime_ns,str(venue),str(cutoff_date)[:10])
    except Exception:
        stamp=(str(db_path),str(venue),str(cutoff_date)[:10])
    if stamp in _V254_PLAYER_LAP_CACHE:
        return dict(_V254_PLAYER_LAP_CACHE[stamp])
    try:
        with sqlite3.connect(str(db_path)) as con:
            _v252_ensure_lap_tables(con)
            pred=pd.read_sql_query("""
                SELECT p.race_date,p.venue,p.race_no,p.lap_no,p.predicted_order,
                       p.is_backtest,p.created_at
                FROM v252_lap_prediction_snapshots p
                WHERE p.is_backtest IN (0,2)
                  AND p.app_version IN ('Ver253','Ver254','Ver256','Ver257','Ver259','Ver260')
                  AND (?='' OR p.venue=?)
                  AND (?='' OR substr(p.race_date,1,10)<substr(?,1,10))
                ORDER BY p.created_at
            """,con,params=(venue,venue,cutoff_date,cutoff_date))
            actual=pd.read_sql_query("""
                SELECT rr.race_date,rr.venue,REPLACE(COALESCE(rr.race_no,''),'R','') AS race_no,
                       rl.lap_no,rl.position,rl.car_no,
                       COALESCE(re.player_name,'') AS player_name,
                       COALESCE(CAST(REPLACE(REPLACE(re.handicap,'m',''),'Ｍ','') AS INTEGER),0) AS handicap
                FROM result_laps rl
                JOIN result_races rr ON rr.race_key=rl.race_key
                LEFT JOIN result_entries re ON re.race_key=rr.race_key AND re.car_no=rl.car_no
                WHERE COALESCE(rr.learning_eligible,1)=1
                  AND (?='' OR rr.venue=?)
                  AND (?='' OR substr(rr.race_date,1,10)<substr(?,1,10))
                ORDER BY rr.race_date,rr.venue,rr.race_no,rl.lap_no,rl.position
            """,con,params=(venue,venue,cutoff_date,cutoff_date))
    except Exception as exc:
        result['reason']=f'選手別周回差分読込失敗: {exc}'
        return result
    if pred.empty or actual.empty:
        return result
    pred=pred.sort_values('created_at').drop_duplicates(['race_date','venue','race_no','lap_no'],keep='last')
    amap={}; nmap={}; hmap={}
    for key,g in actual.groupby(['race_date','venue','race_no','lap_no'],dropna=False):
        gg=g.sort_values('position')
        k=(str(key[0])[:10],str(key[1]),str(key[2]),int(key[3]))
        amap[k]=tuple(int(x) for x in gg.car_no.tolist())
        nmap[k]={int(r.car_no):str(r.player_name or '').strip() for r in gg.itertuples()}
        hmap[k]={int(r.car_no):int(r.handicap or 0) for r in gg.itertuples()}
    events=[]; race_keys=set()
    for row in pred.itertuples():
        key=(str(row.race_date)[:10],str(row.venue),str(row.race_no),int(row.lap_no))
        actual_order=amap.get(key)
        try: pred_order=tuple(int(x) for x in str(row.predicted_order).split('-') if str(x).strip())
        except Exception: continue
        if not actual_order or len(pred_order)<3: continue
        prev=amap.get((key[0],key[1],key[2],key[3]-1))
        hp=hmap.get(key,{})
        if not prev:
            prev=tuple(sorted(actual_order,key=lambda c:(hp.get(c,0),c)))
        pp={c:i for i,c in enumerate(pred_order)}; ap={c:i for i,c in enumerate(actual_order)}
        names=nmap.get(key,{})
        for j in range(1,len(prev)):
            front,chaser=prev[j-1],prev[j]
            name=str(names.get(chaser,'')).strip()
            if not name or front not in pp or chaser not in pp or front not in ap or chaser not in ap:
                continue
            pred_pass=int(pp[chaser]<pp[front]); actual_pass=int(ap[chaser]<ap[front])
            weight=0.35 if int(getattr(row,'is_backtest',0) or 0)==2 else 1.0
            events.append((name,key[3],actual_pass-pred_pass,weight))
            race_keys.add(key[:3])
    if len(events)<40:
        result.update({'samples':len(events),'races':len(race_keys)})
        _V254_PLAYER_LAP_CACHE[stamp]=dict(result)
        return result
    ev=pd.DataFrame(events,columns=['player','lap','residual','weight'])
    deltas={}
    for (player,lap),g in ev.groupby(['player','lap']):
        effective_n=float(g['weight'].sum())
        if effective_n < 1.0:
            continue
        raw=float(np.average(g['residual'],weights=g['weight']))
        # 選手別はデータが薄いため、場・周回補正よりさらに強く縮小。
        shrunk=(effective_n/(effective_n+18.0))*raw
        deltas[f'{player}|{int(lap)}']={
            'delta':float(np.clip(shrunk*0.42,-0.10,0.10)),
            'raw_residual':raw,
            'n':int(len(g)),
            'effective_n':round(effective_n,2),
        }
    result={
        'enabled':bool(deltas),'samples':int(len(ev)),'races':int(len(race_keys)),
        'player_delta':deltas,
        'reason':'予測と実測の周回差を選手別・周回別に強く縮小学習'
    }
    _V254_PLAYER_LAP_CACHE.clear(); _V254_PLAYER_LAP_CACHE[stamp]=dict(result)
    return result



# Ver260: 保存予測がある7レースだけに依存せず、実測グランドノート全体から
# 選手×周回の「前車を実際に入れ替えた率」を学習する。
# 開催場データが薄い場合は全場の選手傾向へ縮小し、さらに周回全体平均との差だけを小さく反映する。
_V258_PLAYER_ACTUAL_CACHE = {}

def _v258_player_actual_lap_calibration(db_path: str | None, venue: str = "", cutoff_date: str = "") -> dict:
    result={"enabled":False,"races":0,"pairs":0,"players":0,"linked_laps":0,"total_laps":0,
            "player_delta":{},"reason":"実測グランドノートの選手別周回データ不足"}
    if not db_path or not Path(db_path).exists():
        return result
    try:
        stamp=(str(db_path),Path(db_path).stat().st_mtime_ns,str(venue),str(cutoff_date)[:10])
    except Exception:
        stamp=(str(db_path),str(venue),str(cutoff_date)[:10])
    if stamp in _V258_PLAYER_ACTUAL_CACHE:
        return dict(_V258_PLAYER_ACTUAL_CACHE[stamp])
    try:
        with sqlite3.connect(str(db_path)) as con:
            total_laps=int(con.execute("""
                SELECT COUNT(*) FROM result_laps rl
                JOIN result_races rr ON rr.race_key=rl.race_key
                WHERE COALESCE(rr.learning_eligible,1)=1
                  AND (?='' OR substr(rr.race_date,1,10)<substr(?,1,10))
            """,(cutoff_date,cutoff_date)).fetchone()[0] or 0)
            linked_laps=int(con.execute("""
                SELECT COUNT(*) FROM result_laps rl
                JOIN result_races rr ON rr.race_key=rl.race_key
                JOIN result_entries re ON re.race_key=rr.race_key AND re.car_no=rl.car_no
                WHERE COALESCE(rr.learning_eligible,1)=1
                  AND COALESCE(TRIM(re.player_name),'')<>''
                  AND (?='' OR substr(rr.race_date,1,10)<substr(?,1,10))
            """,(cutoff_date,cutoff_date)).fetchone()[0] or 0)
            d=pd.read_sql_query("""
                SELECT substr(rr.race_date,1,10) AS race_date,rr.venue,
                       REPLACE(COALESCE(rr.race_no,''),'R','') AS race_no,
                       rl.lap_no,rl.position,rl.car_no,COALESCE(re.player_name,'') AS player_name
                FROM result_laps rl
                JOIN result_races rr ON rr.race_key=rl.race_key
                LEFT JOIN result_entries re ON re.race_key=rr.race_key AND re.car_no=rl.car_no
                WHERE COALESCE(rr.learning_eligible,1)=1
                  AND rl.lap_no BETWEEN 1 AND 6
                  AND (?='' OR substr(rr.race_date,1,10)<substr(?,1,10))
                ORDER BY rr.race_date,rr.venue,rr.race_no,rl.lap_no,rl.position
            """,con,params=(cutoff_date,cutoff_date))
    except Exception as exc:
        result['reason']=f'Ver260選手別実測周回読込失敗: {exc}'
        return result
    result['total_laps']=total_laps; result['linked_laps']=linked_laps
    if d.empty:
        return result
    events=[]; race_keys=set()
    for (race_date,v,race_no),g in d.groupby(['race_date','venue','race_no'],dropna=False):
        orders={int(l):tuple(int(x) for x in xg.sort_values('position').car_no.tolist()) for l,xg in g.groupby('lap_no')}
        names={int(r.car_no):str(r.player_name or '').strip() for r in g.itertuples() if str(r.player_name or '').strip()}
        prev=orders.get(1)
        for lap in range(2,7):
            cur=orders.get(lap)
            if not prev or not cur:
                prev=cur or prev; continue
            pos={c:i for i,c in enumerate(cur)}
            for i in range(1,len(prev)):
                front,chaser=prev[i-1],prev[i]
                name=names.get(chaser,'')
                if not name or front not in pos or chaser not in pos:
                    continue
                passed=int(pos[chaser] < pos[front])
                events.append((str(v),name,int(lap),passed))
                race_keys.add((str(race_date),str(v),str(race_no)))
            prev=cur
    if len(events)<100:
        result.update({'pairs':len(events),'races':len(race_keys)})
        _V258_PLAYER_ACTUAL_CACHE[stamp]=dict(result)
        return result
    ev=pd.DataFrame(events,columns=['venue','player','lap','passed'])
    # 全場の周回基準率。選手補正はこの基準との差だけを使う。
    lap_base={int(l):(float(g['passed'].sum())+4.0)/(len(g)+16.0) for l,g in ev.groupby('lap')}
    global_pg={(str(p),int(l)):(int(len(g)),float(g['passed'].sum())) for (p,l),g in ev.groupby(['player','lap'])}
    local=ev[ev['venue'].astype(str)==str(venue)] if venue else ev
    local_pg={(str(p),int(l)):(int(len(g)),float(g['passed'].sum())) for (p,l),g in local.groupby(['player','lap'])}
    deltas={}; used_players=set(); used_pairs=0
    for key,(gn,gpass) in global_pg.items():
        player,lap=key
        ln,lpass=local_pg.get(key,(0,0.0))
        # 全場の選手率はBeta平滑化、開催場固有は全場選手率へ縮小。
        gp=(gpass+2.0)/(gn+8.0)
        if venue:
            lp=(lpass+2.0)/(ln+8.0)
            local_conf=ln/(ln+18.0)
            player_rate=local_conf*lp+(1.0-local_conf)*gp
            n_for_conf=ln + 0.35*gn
        else:
            player_rate=gp; n_for_conf=gn
        base=float(lap_base.get(lap,0.20))
        confidence=float(n_for_conf/(n_for_conf+35.0))
        if n_for_conf < 2.0:
            continue
        # データが増えるほど0.08→0.24程度へ緩やかに強める。最大±0.14logitに制限。
        gain=0.08+0.16*confidence
        delta=float(np.clip((_v256_logit(player_rate)-_v256_logit(base))*gain,-0.14,0.14))
        if abs(delta)<0.004:
            continue
        deltas[f'{player}|{lap}']={
            'delta':delta,'rate':round(player_rate,5),'base_rate':round(base,5),
            'global_n':int(gn),'venue_n':int(ln),'confidence':round(confidence,4)
        }
        used_players.add(player); used_pairs += int(ln if venue else gn)
    result.update({
        'enabled':bool(deltas),'races':len(race_keys),'pairs':int(len(local)),
        'players':len(used_players),'player_delta':deltas,
        'reason':'Ver260: 全実測グランドノートから選手×周回の追抜率を学習し、開催場・全場へ階層縮小'
    })
    _V258_PLAYER_ACTUAL_CACHE.clear(); _V258_PLAYER_ACTUAL_CACHE[stamp]=dict(result)
    return result

# Ver253: 保存済み予測履歴の出走表を使い、各レースを現在の6周モデルで再構成する。
# 実結果は順位生成に使わず、生成後の周回残差学習だけに低い重みで利用する。
def _v253_backfill_saved_lap_predictions(db_path: str, limit: int = 80) -> dict:
    global _V253_RECONSTRUCTION_MODE
    result={"processed":0,"saved":0,"skipped":0,"already_done":0,"missing_meta":0,"errors":[],"saved_races":[],"message":""}
    if not db_path or not Path(db_path).exists():
        result["message"]="DBが見つかりません。"; return result
    try:
        with sqlite3.connect(str(db_path)) as con:
            _v253_ensure_lap_tables(con)
            rows=con.execute("""
                SELECT history_id,race_key,race_label,prediction_time,trials,seed,raw_text,venue_override
                FROM v231_prediction_history
                WHERE COALESCE(raw_text,'')<>''
                ORDER BY prediction_time ASC, history_id ASC
                LIMIT ?
            """,(max(1,int(limit)),)).fetchall()
            existing=set((str(a),str(b),str(c)) for a,b,c in con.execute("""
                SELECT race_date,venue,race_no FROM v252_lap_prediction_snapshots
                WHERE app_version IN ('Ver253','Ver254','Ver256','Ver257','Ver259','Ver260') AND is_backtest=2 GROUP BY race_date,venue,race_no
            """).fetchall())
        for row in rows:
            result["processed"]+=1
            hid,race_key,label,pred_time,trials,seed,raw_text,venue_override=row
            try:
                prediction_text=str(raw_text or '')
                if str(venue_override or '').strip():
                    prediction_text=f"開催場: {str(venue_override).strip()}\n"+prediction_text
                # パーサーと基礎予測は保存当時の入力だけから再実行。
                df,bets,output,entries,meta=engine.ver16_run_prediction(
                    prediction_text,max(1000,min(int(trials or 2000),4000)),int(seed or 42),manual_excluded=[]
                )
                entries=_v276_mark_retrial_from_prediction_text(entries,prediction_text)
                df=_v276_copy_retrial_to_prediction_df(df,entries)
                meta=dict(meta or {})
                race_date=str(meta.get('開催日') or meta.get('race_date') or '')[:10]
                venue=str(meta.get('開催場') or meta.get('venue') or '').strip()
                race_no=str(meta.get('R') or meta.get('レース') or meta.get('race_no') or '').strip().replace('R','')
                if not race_date or not venue or not race_no:
                    result["missing_meta"]+=1
                    result["skipped"]+=1
                    continue
                if (race_date,venue,race_no) in existing:
                    result["already_done"]+=1
                    result["skipped"]+=1
                    continue
                _V253_RECONSTRUCTION_MODE=True
                try:
                    _v230_six_lap_simulation(df,bets,entries,meta,max(1000,min(int(trials or 2000),4000)),int(seed or 42))
                finally:
                    _V253_RECONSTRUCTION_MODE=False
                existing.add((race_date,venue,race_no)); result["saved"]+=1
                result["saved_races"].append(f"{race_date} {venue}{race_no}R")
            except Exception as exc:
                _V253_RECONSTRUCTION_MODE=False
                if len(result["errors"])<8: result["errors"].append(f"履歴{hid}: {type(exc).__name__}: {exc}")
        _V252_LAP_RESIDUAL_CACHE.clear()
        result["message"]=(
            f"確認 {result['processed']}件｜新規再構成 {result['saved']}レース｜"
            f"再構成済み {result['already_done']}件｜材料不足 {result['missing_meta']}件｜"
            f"処理エラー {len(result['errors'])}件"
        )
    except Exception as exc:
        result["message"]=f"再構成失敗: {type(exc).__name__}: {exc}"
    return result


def _v253_reconstruction_status(db_path: str) -> dict:
    """Ver253の再構成保存状況と、実測グランドノートとの照合精度を返す。"""
    out={"races":0,"lap_rows":0,"paired_laps":0,"position_match":None,
         "pair_match":None,"position_mae":None,"by_lap":[],"race_labels":[],
         "learning_enabled":False,"learning_samples":0,"learning_races":0,"reason":""}
    if not db_path or not Path(db_path).exists():
        out["reason"]="DBが見つかりません。"; return out
    try:
        with sqlite3.connect(str(db_path)) as con:
            _v253_ensure_lap_tables(con)
            pred=pd.read_sql_query("""
                SELECT race_date,venue,race_no,lap_no,predicted_order,support,created_at
                FROM v252_lap_prediction_snapshots
                WHERE app_version IN ('Ver253','Ver254','Ver256','Ver257','Ver259','Ver260') AND is_backtest=2
                ORDER BY race_date,venue,CAST(race_no AS INTEGER),lap_no,created_at
            """,con)
            actual=pd.read_sql_query("""
                SELECT substr(rr.race_date,1,10) AS race_date,rr.venue,
                       CAST(rr.race_no AS TEXT) AS race_no,rl.lap_no,rl.position,rl.car_no
                FROM result_laps rl JOIN result_races rr ON rr.race_key=rl.race_key
                WHERE COALESCE(rr.learning_eligible,1)=1
                ORDER BY rr.race_date,rr.venue,CAST(rr.race_no AS INTEGER),rl.lap_no,rl.position
            """,con)
        if pred.empty:
            out["reason"]="再構成データはまだありません。"; return out
        pred=pred.sort_values('created_at').drop_duplicates(
            ['race_date','venue','race_no','lap_no'],keep='last')
        race_groups=pred[['race_date','venue','race_no']].drop_duplicates()
        out['races']=int(len(race_groups)); out['lap_rows']=int(len(pred))
        out['race_labels']=[f"{r.race_date} {r.venue}{r.race_no}R" for r in race_groups.itertuples()]
        amap={}
        for key,g in actual.groupby(['race_date','venue','race_no','lap_no'],dropna=False):
            amap[(str(key[0])[:10],str(key[1]),str(key[2]),int(key[3]))]=tuple(
                int(x) for x in g.sort_values('position').car_no.tolist())
        metrics=[]
        for row in pred.itertuples():
            key=(str(row.race_date)[:10],str(row.venue),str(row.race_no),int(row.lap_no))
            act=amap.get(key)
            try: prd=tuple(int(x) for x in str(row.predicted_order).split('-') if str(x).strip())
            except Exception: continue
            common=sorted(set(act or ()) & set(prd))
            if not act or len(common)<3: continue
            ap={c:i for i,c in enumerate(act)}; pp={c:i for i,c in enumerate(prd)}
            pos_match=sum(1 for i,c in enumerate(act) if i<len(prd) and prd[i]==c)/max(len(act),len(prd))
            pair_total=pair_ok=0
            for i in range(len(common)):
                for j in range(i+1,len(common)):
                    a,b=common[i],common[j]; pair_total+=1
                    pair_ok += int((ap[a]<ap[b])==(pp[a]<pp[b]))
            mae=float(np.mean([abs(ap[c]-pp[c]) for c in common]))
            metrics.append({'lap':int(row.lap_no),'position_match':pos_match,
                            'pair_match':pair_ok/pair_total if pair_total else 0.0,
                            'position_mae':mae})
        if metrics:
            md=pd.DataFrame(metrics); out['paired_laps']=int(len(md))
            out['position_match']=float(md.position_match.mean())
            out['pair_match']=float(md.pair_match.mean())
            out['position_mae']=float(md.position_mae.mean())
            for lap,g in md.groupby('lap'):
                out['by_lap'].append({'lap':int(lap),'paired':int(len(g)),
                    'position_match':float(g.position_match.mean()),
                    'pair_match':float(g.pair_match.mean()),
                    'position_mae':float(g.position_mae.mean())})
        learning=_v252_lap_residual_learning(str(db_path))
        out['learning_enabled']=bool(learning.get('enabled'))
        out['learning_samples']=int(learning.get('samples',0) or 0)
        out['learning_races']=int(learning.get('races',0) or 0)
        out['reason']=str(learning.get('reason',''))
    except Exception as exc:
        out['reason']=f"状況確認失敗: {type(exc).__name__}: {exc}"
    return out



def _v272_common_race_precision_compare(db_path: str, versions: list[str]) -> tuple[pd.DataFrame, list[tuple]]:
    """
    選択した全Verに周回スナップショットがある共通レースだけで精度比較する。
    総合3指標に加え、1～6周目の平均順位誤差も横並びにする。
    """
    cols = [
        "バージョン","共通R","照合周回","位置一致率","前後関係一致率","平均順位誤差",
        "1着的中率","TOP3一致","三連複一致率","三連単一致率","実TOP3予測順位誤差","TOP3重視スコア",
        "1周目誤差","2周目誤差","3周目誤差","4周目誤差","5周目誤差","6周目誤差",
    ]
    versions = [str(v) for v in versions if str(v)]
    if not db_path or not Path(db_path).exists() or len(versions) < 2:
        return pd.DataFrame(columns=cols), []

    try:
        with sqlite3.connect(str(db_path)) as con:
            _v252_ensure_lap_tables(con)
            qs = ",".join(["?"] * len(versions))
            pred = pd.read_sql_query(f"""
                SELECT race_date,venue,race_no,lap_no,predicted_order,app_version,created_at
                FROM v252_lap_prediction_snapshots
                WHERE app_version IN ({qs})
                ORDER BY created_at
            """, con, params=tuple(versions))
            actual = pd.read_sql_query("""
                SELECT substr(rr.race_date,1,10) AS race_date,rr.venue,
                       REPLACE(CAST(COALESCE(rr.race_no,'') AS TEXT),'R','') AS race_no,
                       rl.lap_no,rl.position,rl.car_no
                FROM result_laps rl
                JOIN result_races rr ON rr.race_key=rl.race_key
                WHERE COALESCE(rr.learning_eligible,1)=1
                ORDER BY rr.race_date,rr.venue,rr.race_no,rl.lap_no,rl.position
            """, con)
            finish = pd.read_sql_query("""
                SELECT substr(rr.race_date,1,10) AS race_date,rr.venue,
                       REPLACE(CAST(COALESCE(rr.race_no,'') AS TEXT),'R','') AS race_no,
                       re.car_no,re.finish
                FROM result_entries re
                JOIN result_races rr ON rr.race_key=re.race_key
                WHERE COALESCE(rr.learning_eligible,1)=1
                  AND re.finish IS NOT NULL
                  AND CAST(re.finish AS INTEGER) BETWEEN 1 AND 8
                ORDER BY rr.race_date,rr.venue,rr.race_no,CAST(re.finish AS INTEGER)
            """, con)
    except Exception:
        return pd.DataFrame(columns=cols), []

    if pred.empty or actual.empty:
        return pd.DataFrame(columns=cols), []

    pred["race_date"] = pred["race_date"].astype(str).str[:10]
    pred["race_no"] = pred["race_no"].astype(str).str.replace("R","",regex=False)
    pred = pred.sort_values("created_at").drop_duplicates(
        ["app_version","race_date","venue","race_no","lap_no"], keep="last"
    )

    # All selected versions must have at least one saved lap for the race.
    race_sets = []
    for ver in versions:
        gv = pred[pred["app_version"].astype(str) == ver]
        race_sets.append(set(
            (str(r.race_date)[:10], str(r.venue), str(r.race_no))
            for r in gv.itertuples()
        ))
    common_races = sorted(set.intersection(*race_sets)) if race_sets else []
    if not common_races:
        return pd.DataFrame(columns=cols), []

    common_set = set(common_races)
    pred = pred[pred.apply(
        lambda r: (str(r["race_date"])[:10], str(r["venue"]), str(r["race_no"])) in common_set,
        axis=1
    )]

    amap = {}
    for key,g in actual.groupby(["race_date","venue","race_no","lap_no"], dropna=False):
        amap[(str(key[0])[:10],str(key[1]),str(key[2]),int(key[3]))] = tuple(
            int(x) for x in g.sort_values("position").car_no.tolist()
        )

    finish_map = {}
    if not finish.empty:
        for key,g in finish.groupby(["race_date","venue","race_no"], dropna=False):
            _fg=g.copy()
            _fg["finish_num"]=pd.to_numeric(_fg["finish"],errors="coerce")
            _fg=_fg.dropna(subset=["finish_num"]).sort_values(["finish_num","car_no"])
            finish_map[(str(key[0])[:10],str(key[1]),str(key[2]))]=tuple(
                int(x) for x in _fg.car_no.tolist()
            )

    rows = []
    for ver in versions:
        gv = pred[pred["app_version"].astype(str) == ver]
        metrics = []
        lap_mae = {i: [] for i in range(1,7)}
        used_races = set()
        final_pred_by_race = {}
        for row in gv.itertuples():
            key = (str(row.race_date)[:10], str(row.venue), str(row.race_no), int(row.lap_no))
            act = amap.get(key)
            try:
                prd = tuple(int(x) for x in str(row.predicted_order).split("-") if str(x).strip())
            except Exception:
                continue
            common = sorted(set(act or ()) & set(prd))
            if not act or len(common) < 3:
                continue
            ap = {c:i for i,c in enumerate(act)}
            pp = {c:i for i,c in enumerate(prd)}
            pos_match = sum(
                1 for i,c in enumerate(act) if i < len(prd) and prd[i] == c
            ) / max(len(act),len(prd))
            pair_total = pair_ok = 0
            for i in range(len(common)):
                for j in range(i+1,len(common)):
                    a,b = common[i],common[j]
                    pair_total += 1
                    pair_ok += int((ap[a] < ap[b]) == (pp[a] < pp[b]))
            mae = float(np.mean([abs(ap[c]-pp[c]) for c in common]))
            metrics.append((pos_match, pair_ok/pair_total if pair_total else 0.0, mae))
            if 1 <= int(row.lap_no) <= 6:
                lap_mae[int(row.lap_no)].append(mae)
            used_races.add(key[:3])
            _rk=key[:3]
            _prev=final_pred_by_race.get(_rk)
            if _prev is None or int(row.lap_no) >= int(_prev[0]):
                final_pred_by_race[_rk]=(int(row.lap_no),prd)

        # Ver282表示追加: 目的を1～3着へ寄せた評価。予測ロジックには使わない。
        top3_eval=[]
        for _rk,(_lap,_prd) in final_pred_by_race.items():
            _act_finish=finish_map.get(_rk)
            if not _act_finish or len(_act_finish)<3 or len(_prd)<3:
                continue
            _actual3=tuple(_act_finish[:3])
            _pred3=tuple(_prd[:3])
            _pp={c:i+1 for i,c in enumerate(_prd)}
            _top3_n=len(set(_actual3)&set(_pred3))
            _win_hit=int(_pred3[0]==_actual3[0])
            _trio_hit=int(set(_pred3)==set(_actual3))
            _trifecta_hit=int(_pred3==_actual3)
            _actual_top3_rank_err=float(np.mean([
                abs((i+1)-int(_pp.get(c,len(_prd)+1))) for i,c in enumerate(_actual3)
            ]))
            # 1着35% + TOP3捕捉35% + 三連複15% + 三連単15%
            _score=(
                35.0*_win_hit +
                35.0*(_top3_n/3.0) +
                15.0*_trio_hit +
                15.0*_trifecta_hit
            )
            top3_eval.append((_win_hit,_top3_n,_trio_hit,_trifecta_hit,_actual_top3_rank_err,_score))

        if metrics:
            arr = np.asarray(metrics, dtype=float)
            rec = {
                "バージョン": ver,
                "共通R": len(used_races),
                "照合周回": len(metrics),
                "位置一致率": round(float(arr[:,0].mean())*100,1),
                "前後関係一致率": round(float(arr[:,1].mean())*100,1),
                "平均順位誤差": round(float(arr[:,2].mean()),2),
            }
            if top3_eval:
                _ta=np.asarray(top3_eval,dtype=float)
                rec.update({
                    "1着的中率":round(float(_ta[:,0].mean())*100,1),
                    "TOP3一致":round(float(_ta[:,1].mean()),2),
                    "三連複一致率":round(float(_ta[:,2].mean())*100,1),
                    "三連単一致率":round(float(_ta[:,3].mean())*100,1),
                    "実TOP3予測順位誤差":round(float(_ta[:,4].mean()),2),
                    "TOP3重視スコア":round(float(_ta[:,5].mean()),1),
                })
            else:
                rec.update({
                    "1着的中率":None,"TOP3一致":None,"三連複一致率":None,
                    "三連単一致率":None,"実TOP3予測順位誤差":None,"TOP3重視スコア":None,
                })
            for lap in range(1,7):
                rec[f"{lap}周目誤差"] = (
                    round(float(np.mean(lap_mae[lap])),2) if lap_mae[lap] else None
                )
            rows.append(rec)

    return pd.DataFrame(rows, columns=cols), common_races


def _v254_saved_version_lap_comparison(db_path: str) -> pd.DataFrame:
    """Compare saved lap snapshots by app_version against actual grand-note laps.

    This is a stored-data comparison only. It does not pretend to rerun historical
    engines that are no longer present in the current source tree.
    """
    columns=['バージョン','対象レース','照合周回','位置一致率','前後関係一致率','平均順位誤差']
    if not db_path or not Path(db_path).exists():
        return pd.DataFrame(columns=columns)
    try:
        with sqlite3.connect(str(db_path)) as con:
            _v252_ensure_lap_tables(con)
            pred=pd.read_sql_query("""
                SELECT race_date,venue,race_no,lap_no,predicted_order,app_version,created_at
                FROM v252_lap_prediction_snapshots
                ORDER BY created_at
            """,con)
            actual=pd.read_sql_query("""
                SELECT substr(rr.race_date,1,10) AS race_date,rr.venue,
                       REPLACE(CAST(COALESCE(rr.race_no,'') AS TEXT),'R','') AS race_no,
                       rl.lap_no,rl.position,rl.car_no
                FROM result_laps rl
                JOIN result_races rr ON rr.race_key=rl.race_key
                WHERE COALESCE(rr.learning_eligible,1)=1
                ORDER BY rr.race_date,rr.venue,rr.race_no,rl.lap_no,rl.position
            """,con)
    except Exception:
        return pd.DataFrame(columns=columns)
    if pred.empty or actual.empty:
        return pd.DataFrame(columns=columns)
    pred['race_date']=pred['race_date'].astype(str).str[:10]
    pred['race_no']=pred['race_no'].astype(str).str.replace('R','',regex=False)
    pred=pred.sort_values('created_at').drop_duplicates(
        ['app_version','race_date','venue','race_no','lap_no'],keep='last')
    amap={}
    for key,g in actual.groupby(['race_date','venue','race_no','lap_no'],dropna=False):
        amap[(str(key[0])[:10],str(key[1]),str(key[2]),int(key[3]))]=tuple(
            int(x) for x in g.sort_values('position').car_no.tolist())
    rows=[]
    for version,gver in pred.groupby('app_version',dropna=False):
        metrics=[]; races=set()
        for row in gver.itertuples():
            key=(str(row.race_date)[:10],str(row.venue),str(row.race_no),int(row.lap_no))
            act=amap.get(key)
            try:
                prd=tuple(int(x) for x in str(row.predicted_order).split('-') if str(x).strip())
            except Exception:
                continue
            common=sorted(set(act or ()) & set(prd))
            if not act or len(common)<3:
                continue
            ap={c:i for i,c in enumerate(act)}; pp={c:i for i,c in enumerate(prd)}
            pos_match=sum(1 for i,c in enumerate(act) if i<len(prd) and prd[i]==c)/max(len(act),len(prd))
            pair_total=pair_ok=0
            for i in range(len(common)):
                for j in range(i+1,len(common)):
                    a,b=common[i],common[j]; pair_total+=1
                    pair_ok += int((ap[a]<ap[b])==(pp[a]<pp[b]))
            mae=float(np.mean([abs(ap[c]-pp[c]) for c in common]))
            metrics.append((pos_match,pair_ok/pair_total if pair_total else 0.0,mae))
            races.add(key[:3])
        if metrics:
            arr=np.asarray(metrics,dtype=float)
            rows.append({
                'バージョン':str(version),'対象レース':len(races),'照合周回':len(metrics),
                '位置一致率':round(float(arr[:,0].mean())*100,1),
                '前後関係一致率':round(float(arr[:,1].mean())*100,1),
                '平均順位誤差':round(float(arr[:,2].mean()),2),
            })
    return pd.DataFrame(rows,columns=columns).sort_values(
        ['前後関係一致率','位置一致率','平均順位誤差'],ascending=[False,False,True],ignore_index=True)


def _v260_snapshot_storage_status(db_path: str, app_version: str = "") -> dict:
    """Show prediction-history count separately from lap-snapshot count."""
    out={"history_races":0,"snapshot_races":0,"snapshot_laps":0,"waiting_or_missing":0,"reason":""}
    if not db_path or not Path(db_path).exists():
        out["reason"]="DBなし"; return out
    ver=str(app_version or globals().get('_V231_APP_VERSION') or '').strip()
    try:
        with sqlite3.connect(str(db_path)) as con:
            _v252_ensure_lap_tables(con)
            try:
                row=con.execute("SELECT COUNT(DISTINCT race_key) FROM v231_prediction_history WHERE app_version=?",(ver,)).fetchone()
                out["history_races"]=int(row[0] or 0)
            except Exception:
                out["history_races"]=0
            row=con.execute("""
                SELECT COUNT(DISTINCT race_date||'|'||venue||'|'||race_no), COUNT(*)
                FROM v252_lap_prediction_snapshots WHERE app_version=?
            """,(ver,)).fetchone()
            out["snapshot_races"]=int(row[0] or 0); out["snapshot_laps"]=int(row[1] or 0)
        out["waiting_or_missing"]=max(0,out["history_races"]-out["snapshot_races"])
        out["reason"]="OK"
    except Exception as exc:
        out["reason"]=f"{type(exc).__name__}: {exc}"
    return out


# Ver255: 保存済みバージョンを同一の実測グランドノートで比較し、
# データ量と改善幅を加味して「採用候補 / 保留」を自動判定する。
def _v255_backtest_center(db_path: str) -> dict:
    out={
        'comparison':pd.DataFrame(), 'best_version':'', 'decision':'比較データ不足',
        'decision_reason':'比較可能な保存済み周回予測がありません。',
        'learning':{}, 'player_learning':{}, 'report_id':None,
    }
    cmp_df=_v254_saved_version_lap_comparison(db_path)
    out['comparison']=cmp_df
    try:
        out['learning']=_v252_lap_residual_learning(db_path)
    except Exception as exc:
        out['learning']={'enabled':False,'reason':f'{type(exc).__name__}: {exc}'}
    try:
        out['player_learning']=_v254_player_lap_calibration(db_path,'','')
    except Exception as exc:
        out['player_learning']={'enabled':False,'reason':f'{type(exc).__name__}: {exc}'}
    if cmp_df.empty:
        return out
    scored=cmp_df.copy()
    mae_score=(100.0-(scored['平均順位誤差'].astype(float)*22.0)).clip(lower=0,upper=100)
    scored['総合スコア']=(
        scored['前後関係一致率'].astype(float)*0.45+
        scored['位置一致率'].astype(float)*0.35+
        mae_score*0.20
    ).round(1)
    scored=scored.sort_values(
        ['総合スコア','対象レース','照合周回'],ascending=[False,False,False],ignore_index=True)
    out['comparison']=scored
    best=scored.iloc[0]
    out['best_version']=str(best['バージョン'])
    enough=bool(int(best['対象レース'])>=3 and int(best['照合周回'])>=12)
    if len(scored)==1:
        out['decision']='保留'
        out['decision_reason']='比較できるバージョンが1種類だけです。別バージョンの未来予測を保存してから比較してください。'
    else:
        second=scored.iloc[1]
        margin=float(best['総合スコア'])-float(second['総合スコア'])
        if enough and margin>=1.0:
            out['decision']='採用候補'
            out['decision_reason']=(
                f"{best['バージョン']}が次点より総合スコアで{margin:.1f}点上回りました。"
                '保存済みデータ内の比較なので、未来レースでの確認後に正式採用してください。'
            )
        elif not enough:
            out['decision']='保留'
            out['decision_reason']='対象レースまたは照合周回が少ないため、補正は自動採用しません。'
        else:
            out['decision']='保留'
            out['decision_reason']=f'上位2版の差が{margin:.1f}点で小さいため、追加データを待ちます。'
    return out


def _v255_save_backtest_report(db_path: str, result: dict) -> int | None:
    """Store only the evaluation summary. Prediction weights are never rewritten here."""
    if not db_path or not Path(db_path).exists():
        return None
    cmp_df=result.get('comparison')
    payload=[] if not isinstance(cmp_df,pd.DataFrame) else cmp_df.to_dict(orient='records')
    try:
        import json as _json
        with sqlite3.connect(str(db_path)) as con:
            con.execute("""
                CREATE TABLE IF NOT EXISTS v255_backtest_reports(
                    report_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    app_version TEXT NOT NULL,
                    best_version TEXT,
                    decision TEXT,
                    decision_reason TEXT,
                    comparison_json TEXT
                )
            """)
            cur=con.execute("""
                INSERT INTO v255_backtest_reports(
                    app_version,best_version,decision,decision_reason,comparison_json
                ) VALUES(?,?,?,?,?)
            """,(
                _V231_APP_VERSION,str(result.get('best_version') or ''),
                str(result.get('decision') or ''),str(result.get('decision_reason') or ''),
                _json.dumps(payload,ensure_ascii=False)
            ))
            con.commit()
            return int(cur.lastrowid)
    except Exception:
        return None



# Ver292: ハンデ跨ぎの「小さい試走優位」を全登録結果から自動較正する。
# 同ハンデ（横並び）はこのゲートの対象外。
_V292_TRIAL_GAP_GATE_CACHE = {}

def _v292_trial_gap_gate_calibration(
    db_path: str | None = None,
    cutoff_date: str = "",
    cutoff_race_no: int = 0,
) -> dict:
    """結果登録済みの全開催場データから、小試走差ゲート強度を自動更新する。

    - 対象: 後方ハンデ車の試走が前方車より速いが、その差が0.01秒未満のペア
    - 同ハンデは対象外
    - backtest時は対象レース以前だけを使用し、未来結果の混入を防ぐ
    - Beta(20,20)事前分布で全体へ縮小し、少数サンプルで極端にならない
    - posterior P(後方車先着率 > 50%) を [0.25,1.00] の補正倍率へ変換
    """
    path=str(db_path or _v230_db_path())
    cutoff=str(cutoff_date or "").strip()[:10]
    race_no=int(cutoff_race_no or 0)
    try:
        stamp=(path,int(Path(path).stat().st_mtime_ns),cutoff,race_no)
    except Exception:
        stamp=(path,0,cutoff,race_no)
    if stamp in _V292_TRIAL_GAP_GATE_CACHE:
        return dict(_V292_TRIAL_GAP_GATE_CACHE[stamp])

    out={
        "enabled":False,
        "threshold":0.010,
        "small_gap_scale":0.35,
        "samples":0,
        "wins":0,
        "raw_rate":None,
        "posterior_mean":0.50,
        "posterior_p_gt_half":0.50,
        "reason":"学習データ不足のため安全側固定値",
    }

    try:
        with sqlite3.connect(path,timeout=8.0) as con:
            con.execute("PRAGMA busy_timeout=8000")
            q="""
                SELECT rr.race_key, rr.race_date, rr.race_no,
                       re.car_no, re.finish, re.trial_time, re.handicap,
                       COALESCE(re.result_status,'通常') AS result_status
                FROM result_races rr
                JOIN result_entries re ON re.race_key=rr.race_key
                WHERE COALESCE(rr.learning_eligible,1)=1
                  AND re.finish IS NOT NULL
                  AND re.trial_time IS NOT NULL
                  AND COALESCE(re.result_status,'通常') NOT IN (
                      '欠車','出走取消','発走除外','競走除外',
                      '落車','競走中止','失格','反則','反妨','周誤','周回誤認'
                  )
            """
            params=[]
            if cutoff:
                if race_no>0:
                    q += """ AND (
                        substr(rr.race_date,1,10) < substr(?,1,10)
                        OR (
                            substr(rr.race_date,1,10) = substr(?,1,10)
                            AND CAST(REPLACE(REPLACE(COALESCE(rr.race_no,''),'R',''),'r','') AS INTEGER) < ?
                        )
                    )"""
                    params.extend([cutoff,cutoff,race_no])
                else:
                    q += " AND substr(rr.race_date,1,10) < substr(?,1,10)"
                    params.append(cutoff)
            rows=con.execute(q,params).fetchall()
    except Exception as exc:
        out["reason"]=f"読込失敗: {type(exc).__name__}: {exc}"
        _V292_TRIAL_GAP_GATE_CACHE[stamp]=dict(out)
        return out

    grouped={}
    for rk,rd,rn,car,finish,trial,h,status in rows:
        try:
            m=re.search(r"-?\d+",str(h if h is not None else "0"))
            hv=float(m.group()) if m else 0.0
            fv=float(finish)
            tv=float(trial)
            if not (np.isfinite(hv) and np.isfinite(fv) and np.isfinite(tv)):
                continue
            grouped.setdefault(str(rk),[]).append((hv,fv,tv))
        except Exception:
            continue

    wins=0
    samples=0
    threshold=0.010
    for _,g in grouped.items():
        for rear_h,rear_finish,rear_trial in g:
            for front_h,front_finish,front_trial in g:
                if rear_h <= front_h:
                    continue
                adv=float(front_trial-rear_trial)  # 正なら後方車の試走が速い
                if not (0.0 < adv < threshold):
                    continue
                samples += 1
                if rear_finish < front_finish:
                    wins += 1

    out["samples"]=int(samples)
    out["wins"]=int(wins)
    out["raw_rate"]=(float(wins/samples) if samples else None)

    # 現状のDB151では180件超ある。将来DBが小さくても60ペア未満では学習値を使わない。
    if samples < 60:
        out["reason"]=f"小試走差ペア{samples}件（60件未満）のため安全側固定値"
        _V292_TRIAL_GAP_GATE_CACHE[stamp]=dict(out)
        return out

    # Beta(20,20): 先着率50%を中心に40件分の中立事前分布。
    alpha=20.0+float(wins)
    beta=20.0+float(samples-wins)
    total=alpha+beta
    mean=alpha/total
    var=(alpha*beta)/((total**2)*(total+1.0))
    sd=math.sqrt(max(var,1e-12))
    z=(mean-0.5)/sd
    p_gt=0.5*(1.0+math.erf(z/math.sqrt(2.0)))

    # 「小差なのに本当に後方車先着が50%超と言える確率」をそのまま強度へ。
    # 完全無効にはせず、最低25%は残して試走/ST/履歴の複合proxyを尊重する。
    scale=float(np.clip(0.25+0.75*p_gt,0.25,1.00))

    out.update({
        "enabled":True,
        "small_gap_scale":scale,
        "posterior_mean":float(mean),
        "posterior_p_gt_half":float(p_gt),
        "reason":"全登録結果から自動較正",
        "races":int(len(grouped)),
    })
    _V292_TRIAL_GAP_GATE_CACHE[stamp]=dict(out)
    return out



# Ver294: 小さい試走差 + 前車ST優位の「前残り」を全結果から自動較正。
# 同ハンデは対象外。backtest時は未来結果を使わない。
_V294_FRONT_ST_GUARD_CACHE = {}

def _v294_front_st_guard_calibration(
    db_path: str | None = None,
    cutoff_date: str = "",
    cutoff_race_no: int = 0,
) -> dict:
    path=str(db_path or _v230_db_path())
