    if stamp in _V294_FRONT_ST_GUARD_CACHE:
        return dict(_V294_FRONT_ST_GUARD_CACHE[stamp])

    out={
        "enabled":False,
        "trial_gap_max":0.010,
        "front_st_adv_min":0.020,
        "guard_logit":0.035,
        "samples":0,
        "front_wins":0,
        "raw_rate":None,
        "posterior_mean":0.50,
        "reason":"学習データ不足のため固定弱補正",
    }

