def v203_standard_trifecta_formations(formations, combos):
    """三連単をBOX・通常ハイフン・片折り返し（=は最大1個）だけで正確に圧縮する。"""
    from itertools import combinations, permutations, product

    target = engine._v165_normalize_combo_texts(combos, "3連単")
    if not target:
        return []
    target = set(target)
    cars = sorted({x for combo in target for x in combo})
    candidates = {}

    def add_candidate(line):
        text = str(line or "").strip().upper()
        if not text or text.count("=") > 1:
            return
        expanded = engine._v165_expand_formation_line(text, "3連単")
        if len(expanded) < 2 or not expanded.issubset(target):
            return
        frozen = frozenset(expanded)
        old = candidates.get(frozen)
        if old is None or (len(text), text) < (len(old), old):
            candidates[frozen] = text

    # 既存圧縮のうち、BOX・通常表記・片折り返しだけを再利用する。
    for line in formations or []:
        add_candidate(line)

    # 3車6通りがすべてある場合はABCBOX候補。
    for trio in combinations(cars, 3):
        if set(permutations(trio, 3)).issubset(target):
            add_candidate("".join(map(str, trio)) + "BOX")

    # 片折り返し候補 A=B-C を生成する。
    # A/Bの各集合を折り返し、成立する3着集合Cを最大限まとめる。
    nonempty_subsets = []
    for size in range(1, len(cars) + 1):
        nonempty_subsets.extend(combinations(cars, size))
    for left in nonempty_subsets:
        for middle in nonempty_subsets:
            valid_thirds = []
            for third in cars:
                expanded = set()
                for a, b in product(left, middle):
                    if len({a, b, third}) != 3:
                        continue
                    expanded.add((a, b, third))
                    expanded.add((b, a, third))
                if expanded and expanded.issubset(target):
                    valid_thirds.append(third)
            if valid_thirds:
                add_candidate(
                    "".join(map(str, left)) + "=" +
                    "".join(map(str, middle)) + "-" +
                    "".join(map(str, valid_thirds))
                )

    # 2・3着の片折り返し候補 A-B=C も、正確に成立する場合だけ許可する。
    for firsts in nonempty_subsets:
        for middle in nonempty_subsets:
            valid_thirds = []
            for third in cars:
                expanded = set()
                for a, b in product(firsts, middle):
                    if len({a, b, third}) != 3:
                        continue
                    expanded.add((a, b, third))
                    expanded.add((a, third, b))
                if expanded and expanded.issubset(target):
                    valid_thirds.append(third)
            if valid_thirds:
                add_candidate(
                    "".join(map(str, firsts)) + "-" +
                    "".join(map(str, middle)) + "=" +
                    "".join(map(str, valid_thirds))
                )

    # 大きく覆い、短い表記を優先。行同士は絶対に重複させない。
    ranked = sorted(
        ((set(expanded), line) for expanded, line in candidates.items()),
        key=lambda item: (-len(item[0]), len(item[1]), item[1]),
    )
    uncovered = set(target)
    output = []
    while uncovered:
        best = None
        for expanded, line in ranked:
            if not expanded.issubset(uncovered):
                continue
            score = (len(expanded), -len(line), line.count("="), line)
            if best is None or score > best[0]:
                best = (score, expanded, line)
        if best is None or len(best[1]) < 2:
            break
        _, expanded, line = best
        output.append(line)
        uncovered.difference_update(expanded)

    output.extend("-".join(map(str, combo)) for combo in sorted(uncovered))

    # 最終展開検証。欠落・余分・重複・二重折り返しがあれば安全な個別表記へ戻す。
    covered = set()
    for line in output:
        if str(line).count("=") > 1:
            return ["-".join(map(str, combo)) for combo in sorted(target)]
        expanded = engine._v165_expand_formation_line(line, "3連単")
        if not expanded or not expanded.issubset(target) or expanded & covered:
            return ["-".join(map(str, combo)) for combo in sorted(target)]
        covered.update(expanded)
    if covered != target:
        return ["-".join(map(str, combo)) for combo in sorted(target)]
    return output

def v182_hit_first_odds_adjustment(bets: dict, trials: int, base_info: dict, odds_map: dict) -> dict:
    """的中重視の上位順を維持したまま、オッズで1〜10点を微調整する。"""
    counter = bets.get("三連単", {}) if isinstance(bets, dict) else {}
    if not counter or not odds_map or int(trials or 0) <= 0:
        return {"available": False, "reason": "三連単オッズを読み込むと点数調整を表示します。"}
    ordered = sorted(counter.items(), key=lambda item: item[1], reverse=True)[:10]
    rows = []
    for rank, (combo, count) in enumerate(ordered, 1):
        key = "-".join(map(str, tuple(combo) if isinstance(combo, (tuple, list)) else (combo,)))
        probability = float(count) / max(int(trials), 1) * 100.0
        odds = float(odds_map.get(key, 0) or 0)
        rows.append({"rank": rank, "combo": key, "probability": probability, "odds": odds})
    if not rows or not any(r["odds"] > 0 for r in rows):
        return {"available": False, "reason": "上位10点に対応する三連単オッズが見つかりません。"}

    base_points = max(1, min(10, int(base_info.get("points") or 10)))
    candidates = []
    for n in range(max(1, base_points - 3), min(10, base_points + 3) + 1):
        chosen = rows[:n]
        cost = n * 100.0
        cover = sum(r["probability"] for r in chosen)
        known = [r for r in chosen if r["odds"] > 0]
        black = [r for r in known if r["odds"] * 100.0 >= cost]
        black_cover = sum(r["probability"] for r in black)
        low_cover = sum(r["probability"] for r in known if r["odds"] * 100.0 < cost)
        # 的中カバーを主役にし、黒字で当たり得る範囲を加点、低配当範囲と点数を軽く減点。
        score = cover + 0.35 * black_cover - 0.20 * low_cover - 0.22 * n
        candidates.append({
            "n": n, "cost": cost, "cover": cover, "black_cover": black_cover,
            "low_cover": low_cover, "known": len(known), "score": score,
        })
    best = max(candidates, key=lambda x: (x["score"], -abs(x["n"] - base_points), -x["n"]))
    final_points = int(best["n"])
    selected = rows[:final_points]
    known_selected = [r for r in selected if r["odds"] > 0]
    low_count = sum(1 for r in known_selected if r["odds"] * 100.0 < best["cost"])
    profitable_count = sum(1 for r in known_selected if r["odds"] * 100.0 >= best["cost"])

    if best["known"] < max(3, final_points // 2):
        grade, icon = "参考", "⚪"
        reason = "上位候補のオッズ入力が少ないため、点数調整は参考扱いです。"
    elif best["black_cover"] < best["cover"] * 0.35 or low_count >= max(2, final_points // 2):
        grade, icon = "非推奨", "⛔"
        reason = "的中候補はありますが、購入点数に対して低配当となる候補の割合が高めです。"
    elif best["black_cover"] >= best["cover"] * 0.70:
        grade, icon = "推奨", "✅"
        reason = "的中カバーを維持しつつ、候補総額を上回る配当余地のある組み合わせが多めです。"
    else:
        grade, icon = "的中優先なら候補", "△"
        reason = "的中カバーは妥当ですが、回収効率は中程度です。"

    delta = final_points - base_points
    if delta > 0:
        adjust_reason = f"次点候補の確率寄与と配当余地を考慮し、基本{base_points}点から{delta}点追加しました。"
    elif delta < 0:
        adjust_reason = f"下位候補の確率寄与と低配当リスクを考慮し、基本{base_points}点から{-delta}点減らしました。"
    else:
        adjust_reason = f"基本{base_points}点を維持しました。"
    return {
        "available": True, "base_points": base_points, "final_points": final_points,
        "delta": delta, "cover": best["cover"], "black_cover": best["black_cover"],
        "low_cover": best["low_cover"], "cost": best["cost"], "grade": grade, "icon": icon,
        "reason": reason, "adjust_reason": adjust_reason, "profitable_count": profitable_count,
        "low_count": low_count, "combos": [r["combo"] for r in selected],
    }


def show_v182_odds_adjusted_tight_recommendation(bets: dict, trials: int, meta: dict, odds_map: dict) -> None:
    base = v180_trifecta_tight_recommendation(bets, trials, meta)
    adjusted = v182_hit_first_odds_adjustment(bets, trials, base, odds_map)
    st.markdown("#### 🎛️ 的中重視＋オッズ点数調整")
    if not adjusted.get("available"):
        st.caption(adjusted.get("reason", "オッズを読み込むと表示します。"))
        return
    st.subheader(f"{adjusted['icon']} 最終参考：{adjusted['final_points']}点・{adjusted['grade']}")
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("基本点数", f"{adjusted['base_points']}点")
    c2.metric("オッズ調整", f"{adjusted['delta']:+d}点")
    c3.metric("候補累積", f"{adjusted['cover']:.2f}%")
    c4.metric("黒字余地側の累積", f"{adjusted['black_cover']:.2f}%")
    if adjusted["grade"] == "非推奨":
        st.warning(adjusted["reason"])
    elif adjusted["grade"] == "推奨":
        st.success(adjusted["reason"])
    else:
        st.info(adjusted["reason"])
    st.caption(adjusted["adjust_reason"] + f" 100円ずつなら候補総額は{int(adjusted['cost']):,}円。")
    st.caption(f"総額以上の配当余地あり {adjusted['profitable_count']}点 / 低配当側 {adjusted['low_count']}点")
    st.code("\n".join(adjusted["combos"]), language=None)
    st.caption("これは過去分布と入力オッズを使った参考判定です。的中や収益を保証するものではありません。")




# Ver187: 8車合成プランをDB保存し、結果登録後に自動照合して次回判定へ反映する。
def _v187_ensure_mixed_learning_tables(db_path: str) -> None:
    """回収率学習テーブルの存在だけを保証する安全版。

    Ver282:
    予測表示・復元表示のたびに孤立データのINSERT/DELETEやTRIGGER作成を行うと、
    同時読込・バックグラウンド処理中にSQLiteへ不要な書込が発生する。
    ここではDDLの最小保証だけに限定し、孤立データ処理は監査/メンテナンス側へ分離する。
    """
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        con.executescript("""
        CREATE TABLE IF NOT EXISTS v187_mixed_plan_runs (
            race_key TEXT NOT NULL,
            plan_hash TEXT NOT NULL,
            points INTEGER NOT NULL,
            cost_yen INTEGER NOT NULL,
            grade TEXT,
            cover REAL,
            black REAL,
            low REAL,
            hit_average_multiple REAL,
            model_expected_multiple REAL,
            model_return_rate REAL,
            role_count INTEGER,
            created_at TEXT NOT NULL,
            PRIMARY KEY (race_key, plan_hash)
        );
        CREATE TABLE IF NOT EXISTS v187_mixed_plan_tickets (
            race_key TEXT NOT NULL,
            plan_hash TEXT NOT NULL,
            bet_type TEXT NOT NULL,
            combination TEXT NOT NULL,
            probability REAL,
            odds REAL,
            role TEXT,
            PRIMARY KEY (race_key, plan_hash, bet_type, combination)
        );
        CREATE TABLE IF NOT EXISTS v187_mixed_plan_feedback (
            race_key TEXT NOT NULL,
            plan_hash TEXT NOT NULL,
            hit INTEGER NOT NULL,
            black_hit INTEGER NOT NULL,
            gami_hit INTEGER NOT NULL,
            payout_yen INTEGER NOT NULL,
            cost_yen INTEGER NOT NULL,
            realized_multiple REAL NOT NULL,
            return_rate REAL NOT NULL,
            winning_types TEXT,
            evaluated_at TEXT NOT NULL,
            PRIMARY KEY (race_key, plan_hash)
        );
        CREATE TABLE IF NOT EXISTS v187_mixed_ticket_feedback (
            race_key TEXT NOT NULL,
            plan_hash TEXT NOT NULL,
            bet_type TEXT NOT NULL,
            combination TEXT NOT NULL,
            hit INTEGER NOT NULL,
            payout_yen INTEGER NOT NULL,
            PRIMARY KEY (race_key, plan_hash, bet_type, combination)
        );
        CREATE TABLE IF NOT EXISTS v300_recommendation_audit (
            race_key TEXT NOT NULL,
            plan_hash TEXT NOT NULL,
            recommendation_label TEXT NOT NULL,
            recommendation_score INTEGER NOT NULL,
            adjusted_return_rate REAL,
            cover REAL,
            max_ev REAL,
            hole_count INTEGER,
            reasons_json TEXT,
            app_version TEXT,
            created_at TEXT NOT NULL,
            PRIMARY KEY (race_key, plan_hash)
        );
        CREATE TABLE IF NOT EXISTS v280_orphan_plan_feedback_archive (
            race_key TEXT NOT NULL,
            plan_hash TEXT NOT NULL,
            hit INTEGER,
            black_hit INTEGER,
            gami_hit INTEGER,
            payout_yen INTEGER,
            cost_yen INTEGER,
            realized_multiple REAL,
            return_rate REAL,
            winning_types TEXT,
            evaluated_at TEXT,
            archived_at TEXT NOT NULL,
            archive_reason TEXT NOT NULL,
            PRIMARY KEY (race_key, plan_hash)
        );
        CREATE TABLE IF NOT EXISTS v280_orphan_ticket_feedback_archive (
            race_key TEXT NOT NULL,
            plan_hash TEXT NOT NULL,
            bet_type TEXT NOT NULL,
            combination TEXT NOT NULL,
            hit INTEGER,
            payout_yen INTEGER,
            archived_at TEXT NOT NULL,
            archive_reason TEXT NOT NULL,
            PRIMARY KEY (race_key, plan_hash, bet_type, combination)
        );
        CREATE TABLE IF NOT EXISTS v280_orphan_plan_tickets_archive (
            race_key TEXT NOT NULL,
            plan_hash TEXT NOT NULL,
            bet_type TEXT NOT NULL,
            combination TEXT NOT NULL,
            probability REAL,
            odds REAL,
            role TEXT,
            archived_at TEXT NOT NULL,
            archive_reason TEXT NOT NULL,
            PRIMARY KEY (race_key, plan_hash, bet_type, combination)
        );
        """)

        existing_cols = {row[1] for row in con.execute("PRAGMA table_info(v187_mixed_plan_runs)").fetchall()}
        for col_name, col_type in [
            ("app_version", "TEXT"),
            ("logic_version", "TEXT"),
            ("race_date", "TEXT"),
            ("venue", "TEXT"),
            ("race_no", "TEXT"),
            ("starter_count", "INTEGER"),
            ("plan_origin", "TEXT DEFAULT 'live'"),
            ("source_prediction_version", "TEXT"),
            ("include_in_live_stats", "INTEGER DEFAULT 1"),
        ]:
            if col_name not in existing_cols:
                con.execute(f"ALTER TABLE v187_mixed_plan_runs ADD COLUMN {col_name} {col_type}")

        # 旧Ver280で作った書込TRIGGERは、予測中のDB状態を複雑化させるため解除。
        con.executescript("""
        DROP TRIGGER IF EXISTS v280_guard_plan_feedback_insert;
        DROP TRIGGER IF EXISTS v280_guard_ticket_feedback_insert;
        DROP TRIGGER IF EXISTS v280_guard_plan_ticket_insert;
        """)
        con.commit()


def _v282_archive_orphan_mixed_plan_rows(db_path: str) -> dict:
    """明示的メンテナンス時だけ孤立行を退避する。通常の予測/復元表示からは呼ばない。"""
    out={"archived_plan_feedback":0,"archived_ticket_feedback":0,"archived_plan_tickets":0,"ok":False,"error":""}
    try:
        _v187_ensure_mixed_learning_tables(db_path)
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.execute("PRAGMA busy_timeout=30000")
            con.row_factory=sqlite3.Row
            now=_v228_now_jst_iso()

            before=int(con.execute("SELECT COUNT(*) FROM v280_orphan_plan_feedback_archive").fetchone()[0] or 0)
            con.execute("""
                INSERT OR IGNORE INTO v280_orphan_plan_feedback_archive
                SELECT f.race_key,f.plan_hash,f.hit,f.black_hit,f.gami_hit,
                       f.payout_yen,f.cost_yen,f.realized_multiple,f.return_rate,
                       f.winning_types,f.evaluated_at,?,?
                FROM v187_mixed_plan_feedback f
                LEFT JOIN v187_mixed_plan_runs r
                  ON r.race_key=f.race_key AND r.plan_hash=f.plan_hash
                WHERE r.race_key IS NULL
            """,(now,"runなしの孤立feedback"))
            after=int(con.execute("SELECT COUNT(*) FROM v280_orphan_plan_feedback_archive").fetchone()[0] or 0)
            out["archived_plan_feedback"]=max(0,after-before)

            before=int(con.execute("SELECT COUNT(*) FROM v280_orphan_ticket_feedback_archive").fetchone()[0] or 0)
            con.execute("""
                INSERT OR IGNORE INTO v280_orphan_ticket_feedback_archive
                SELECT f.race_key,f.plan_hash,f.bet_type,f.combination,
                       f.hit,f.payout_yen,?,?
                FROM v187_mixed_ticket_feedback f
                LEFT JOIN v187_mixed_plan_runs r
                  ON r.race_key=f.race_key AND r.plan_hash=f.plan_hash
                WHERE r.race_key IS NULL
            """,(now,"runなしの孤立ticket feedback"))
            after=int(con.execute("SELECT COUNT(*) FROM v280_orphan_ticket_feedback_archive").fetchone()[0] or 0)
            out["archived_ticket_feedback"]=max(0,after-before)

            before=int(con.execute("SELECT COUNT(*) FROM v280_orphan_plan_tickets_archive").fetchone()[0] or 0)
            con.execute("""
                INSERT OR IGNORE INTO v280_orphan_plan_tickets_archive
                SELECT t.race_key,t.plan_hash,t.bet_type,t.combination,
                       t.probability,t.odds,t.role,?,?
                FROM v187_mixed_plan_tickets t
                LEFT JOIN v187_mixed_plan_runs r
                  ON r.race_key=t.race_key AND r.plan_hash=t.plan_hash
                WHERE r.race_key IS NULL
            """,(now,"runなしの孤立ticket"))
            after=int(con.execute("SELECT COUNT(*) FROM v280_orphan_plan_tickets_archive").fetchone()[0] or 0)
            out["archived_plan_tickets"]=max(0,after-before)
            con.commit()
            out["ok"]=True
    except Exception as exc:
        out["error"]=f"{type(exc).__name__}: {exc}"
    return out


def _v280_orphan_mixed_plan_audit(db_path: str) -> dict:
    """回収率プランのrun/feedback整合性を表示用に確認する。"""
    out={"orphan_plan_feedback":0,"orphan_ticket_feedback":0,"orphan_plan_tickets":0,
         "archived_plan_feedback":0,"archived_ticket_feedback":0,"archived_plan_tickets":0}
    try:
        _v187_ensure_mixed_learning_tables(db_path)
        with sqlite3.connect(str(db_path)) as con:
            out["orphan_plan_feedback"]=int(con.execute("""
                SELECT COUNT(*) FROM v187_mixed_plan_feedback f
                LEFT JOIN v187_mixed_plan_runs r
                  ON r.race_key=f.race_key AND r.plan_hash=f.plan_hash
                WHERE r.race_key IS NULL
            """).fetchone()[0] or 0)
            out["orphan_ticket_feedback"]=int(con.execute("""
                SELECT COUNT(*) FROM v187_mixed_ticket_feedback f
                LEFT JOIN v187_mixed_plan_runs r
                  ON r.race_key=f.race_key AND r.plan_hash=f.plan_hash
                WHERE r.race_key IS NULL
            """).fetchone()[0] or 0)
            out["orphan_plan_tickets"]=int(con.execute("""
                SELECT COUNT(*) FROM v187_mixed_plan_tickets t
                LEFT JOIN v187_mixed_plan_runs r
                  ON r.race_key=t.race_key AND r.plan_hash=t.plan_hash
                WHERE r.race_key IS NULL
            """).fetchone()[0] or 0)
            for key,table in [
                ("archived_plan_feedback","v280_orphan_plan_feedback_archive"),
                ("archived_ticket_feedback","v280_orphan_ticket_feedback_archive"),
                ("archived_plan_tickets","v280_orphan_plan_tickets_archive"),
            ]:
                out[key]=int(con.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0] or 0)
    except Exception:
        pass
    return out


def _v212_norm_bet_type(bet_type: str) -> str:
    """券種名の漢数字・数字表記を同一キーへ統一する。"""
    text = str(bet_type or "").strip().replace("　", "")
    aliases = {
        "三連単": "3連単", "3連単": "3連単",
        "三連複": "3連複", "3連複": "3連複",
        "二連単": "2連単", "2連単": "2連単",
        "二連複": "2連複", "2連複": "2連複",
    }
    return aliases.get(text, text)


def _v187_norm_combo(bet_type: str, combo: str) -> str:
    bet_type = _v212_norm_bet_type(bet_type)
    nums = re.findall(r"\d+", str(combo))
    if bet_type in ("3連複", "2連複", "ワイド"):
        nums = sorted(nums, key=int)
    return "-".join(nums)



def _v282_is_full_refund_race(con, race_key: str) -> bool:
    """結果DB上で全券種が『全返還』になっているレースを判定する。"""
    try:
        rows = con.execute(
            "SELECT bet_type, combination, payout_yen FROM result_payouts WHERE race_key=?",
            (str(race_key),),
        ).fetchall()
        if not rows:
            return False
        combos = [str(r["combination"] if hasattr(r, "keys") else r[1] or "").strip() for r in rows]
        return bool(combos) and all("全返還" in x for x in combos if x) and all(bool(x) for x in combos)
    except Exception:
        return False


def _v282_write_full_refund_feedback(con, plan) -> None:
    """全返還は投資額=払戻額、回収率100%。的中/外れ判定には加えない。"""
    tickets = con.execute(
        "SELECT * FROM v187_mixed_plan_tickets WHERE race_key=? AND plan_hash=?",
        (plan["race_key"], plan["plan_hash"]),
    ).fetchall()
    cost = int(plan["cost_yen"] or len(tickets) * 100)
    unit = int(round(cost / len(tickets))) if tickets else 0
    for t in tickets:
        con.execute("""
            INSERT OR REPLACE INTO v187_mixed_ticket_feedback
            (race_key,plan_hash,bet_type,combination,hit,payout_yen)
            VALUES (?,?,?,?,?,?)
        """, (plan["race_key"], plan["plan_hash"], t["bet_type"], t["combination"], 0, unit))
    con.execute("""
        INSERT OR REPLACE INTO v187_mixed_plan_feedback
        (race_key,plan_hash,hit,black_hit,gami_hit,payout_yen,cost_yen,
         realized_multiple,return_rate,winning_types,evaluated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)
    """, (
        plan["race_key"], plan["plan_hash"], 0, 0, 0,
        cost, cost, 1.0, 100.0,
        json.dumps(["全返還"], ensure_ascii=False), _v228_now_jst_iso()
    ))


def _v187_sync_mixed_feedback(db_path: str) -> int:
    """結果登録済みプランを照合。戻り値は今回新しく評価した件数。"""
    _v187_ensure_mixed_learning_tables(db_path)
    done = 0
    with sqlite3.connect(db_path) as con:
        con.row_factory = sqlite3.Row
        plans = con.execute("""
            SELECT r.* FROM v187_mixed_plan_runs r
            LEFT JOIN v187_mixed_plan_feedback f
              ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
            WHERE f.race_key IS NULL
              AND EXISTS (
                    SELECT 1 FROM result_races rr
                    WHERE rr.race_key=r.race_key
                      AND (
                            COALESCE(rr.learning_eligible,1)=1
                            OR EXISTS (
                                SELECT 1 FROM result_payouts rp
                                WHERE rp.race_key=r.race_key
                                  AND COALESCE(rp.combination,'') LIKE '%全返還%'
                            )
                      )
              )
        """).fetchall()
        for plan in plans:
            if _v282_is_full_refund_race(con, plan["race_key"]):
                _v282_write_full_refund_feedback(con, plan)
                done += 1
                continue
            payouts = con.execute(
                "SELECT bet_type, combination, payout_yen FROM result_payouts WHERE race_key=?",
                (plan["race_key"],),
            ).fetchall()
            payout_map = {}
            for p in payouts:
                payout_map[(_v212_norm_bet_type(p["bet_type"]), _v187_norm_combo(p["bet_type"], p["combination"]))] = int(p["payout_yen"] or 0)
            if not payout_map:
                continue
            tickets = con.execute(
                "SELECT * FROM v187_mixed_plan_tickets WHERE race_key=? AND plan_hash=?",
                (plan["race_key"], plan["plan_hash"]),
            ).fetchall()
            total_payout = 0
            winning_types = []
            for t in tickets:
                key = (_v212_norm_bet_type(t["bet_type"]), _v187_norm_combo(t["bet_type"], t["combination"]))
                pay = int(payout_map.get(key, 0))
                hit = int(pay > 0)
                total_payout += pay
                if hit:
                    winning_types.append(t["bet_type"])
                con.execute("""
                    INSERT OR REPLACE INTO v187_mixed_ticket_feedback
                    (race_key,plan_hash,bet_type,combination,hit,payout_yen) VALUES (?,?,?,?,?,?)
                """, (plan["race_key"],plan["plan_hash"],t["bet_type"],t["combination"],hit,pay))
            cost = int(plan["cost_yen"] or len(tickets)*100)
            hit = int(total_payout > 0)
            black = int(total_payout >= cost and hit)
            gami = int(0 < total_payout < cost)
            multiple = total_payout / cost if cost else 0.0
            con.execute("""
                INSERT OR REPLACE INTO v187_mixed_plan_feedback
                (race_key,plan_hash,hit,black_hit,gami_hit,payout_yen,cost_yen,realized_multiple,return_rate,winning_types,evaluated_at)
                VALUES (?,?,?,?,?,?,?,?,?,?,?)
            """, (plan["race_key"],plan["plan_hash"],hit,black,gami,total_payout,cost,multiple,multiple*100.0,
                    json.dumps(sorted(set(winning_types)), ensure_ascii=False), _v228_now_jst_iso()))
            done += 1
        con.commit()
    return done


def _v212_recalculate_plan_feedback(db_path: str, race_key: str, plan_hash: str) -> None:
    """表記差を吸収して指定プランの実績を再計算し、過去の誤判定も修復する。"""
    with sqlite3.connect(db_path) as con:
        con.row_factory = sqlite3.Row
        plan = con.execute(
            "SELECT * FROM v187_mixed_plan_runs WHERE race_key=? AND plan_hash=?",
            (race_key, plan_hash),
        ).fetchone()
        if plan is None:
            return
        if _v282_is_full_refund_race(con, race_key):
            _v282_write_full_refund_feedback(con, plan)
            con.commit()
            return
        payouts = con.execute(
            "SELECT bet_type, combination, payout_yen FROM result_payouts WHERE race_key=?",
            (race_key,),
        ).fetchall()
        if not payouts:
            return
        payout_map = {
            (_v212_norm_bet_type(p["bet_type"]), _v187_norm_combo(p["bet_type"], p["combination"])): int(p["payout_yen"] or 0)
            for p in payouts
        }
        tickets = con.execute(
            "SELECT * FROM v187_mixed_plan_tickets WHERE race_key=? AND plan_hash=?",
            (race_key, plan_hash),
        ).fetchall()
        total_payout = 0
        winning_types = []
        for t in tickets:
            key = (_v212_norm_bet_type(t["bet_type"]), _v187_norm_combo(t["bet_type"], t["combination"]))
            pay = int(payout_map.get(key, 0))
            hit = int(pay > 0)
            total_payout += pay
            if hit:
                winning_types.append(_v212_norm_bet_type(t["bet_type"]))
            con.execute("""
                INSERT OR REPLACE INTO v187_mixed_ticket_feedback
                (race_key,plan_hash,bet_type,combination,hit,payout_yen) VALUES (?,?,?,?,?,?)
            """, (race_key, plan_hash, t["bet_type"], t["combination"], hit, pay))
        cost = int(plan["cost_yen"] or len(tickets) * 100)
        hit = int(total_payout > 0)
        black = int(hit and total_payout >= cost)
        gami = int(0 < total_payout < cost)
        multiple = total_payout / cost if cost else 0.0
        con.execute("""
            INSERT OR REPLACE INTO v187_mixed_plan_feedback
            (race_key,plan_hash,hit,black_hit,gami_hit,payout_yen,cost_yen,realized_multiple,return_rate,winning_types,evaluated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)
        """, (race_key, plan_hash, hit, black, gami, total_payout, cost, multiple, multiple * 100.0,
                json.dumps(sorted(set(winning_types)), ensure_ascii=False), _v228_now_jst_iso()))
        con.commit()


def _v208_latest_mixed_plan_result(race_key: str, db_path: str) -> dict:
    """予測時に保存された最新の回収率重視プランを、登録済み払戻と照合して返す。"""
    if not race_key:
        return {"available": False, "reason": "レースキーがありません。"}
    _v187_ensure_mixed_learning_tables(db_path)
    _v187_sync_mixed_feedback(db_path)
    with sqlite3.connect(db_path) as con:
        con.row_factory = sqlite3.Row
        plan = con.execute("""
            SELECT r.*, f.hit, f.black_hit, f.gami_hit, f.payout_yen,
                   f.return_rate, f.winning_types, f.evaluated_at
            FROM v187_mixed_plan_runs r
            LEFT JOIN v187_mixed_plan_feedback f
              ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
            WHERE r.race_key=?
            ORDER BY datetime(r.created_at) DESC, r.rowid DESC
            LIMIT 1
        """, (race_key,)).fetchone()
        if plan is None:
            return {"available": False, "reason": "このレースでは回収率重視プランが保存されていません。"}
        latest_plan_hash = plan["plan_hash"]
    _v212_recalculate_plan_feedback(db_path, race_key, latest_plan_hash)
    with sqlite3.connect(db_path) as con:
        con.row_factory = sqlite3.Row
        plan = con.execute("""
            SELECT r.*, f.hit, f.black_hit, f.gami_hit, f.payout_yen,
                   f.return_rate, f.winning_types, f.evaluated_at
            FROM v187_mixed_plan_runs r
            LEFT JOIN v187_mixed_plan_feedback f
              ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
            WHERE r.race_key=? AND r.plan_hash=?
            LIMIT 1
        """, (race_key, latest_plan_hash)).fetchone()
        tickets = con.execute("""
            SELECT t.bet_type, t.combination, t.odds, t.role,
                   COALESCE(f.hit,0) AS hit, COALESCE(f.payout_yen,0) AS payout_yen
            FROM v187_mixed_plan_tickets t
            LEFT JOIN v187_mixed_ticket_feedback f
              ON f.race_key=t.race_key AND f.plan_hash=t.plan_hash
             AND f.bet_type=t.bet_type AND f.combination=t.combination
            WHERE t.race_key=? AND t.plan_hash=?
            ORDER BY CASE t.bet_type WHEN '3連単' THEN 1 WHEN '3連複' THEN 2 WHEN '2連単' THEN 3 WHEN '2連複' THEN 4 WHEN 'ワイド' THEN 5 WHEN '単勝' THEN 6 WHEN '複勝' THEN 7 ELSE 9 END, t.combination
        """, (race_key, plan["plan_hash"])).fetchall()
    evaluated = plan["return_rate"] is not None
    _winning_types_text = str(plan["winning_types"] or "") if "winning_types" in plan.keys() else ""
    full_refund = "全返還" in _winning_types_text
    hit_tickets = [dict(t) for t in tickets if int(t["hit"] or 0) == 1]
    cost = int(plan["cost_yen"] or len(tickets) * 100)
    payout = int(plan["payout_yen"] or 0) if evaluated else 0
    return {
        "available": True,
        "evaluated": evaluated,
        "race_key": race_key,
        "plan_hash": plan["plan_hash"],
        "created_at": plan["created_at"],
        "plan_origin": str(plan["plan_origin"] or "live") if "plan_origin" in plan.keys() else "live",
        "source_prediction_version": str(plan["source_prediction_version"] or "") if "source_prediction_version" in plan.keys() else "",
        "include_in_live_stats": bool(int(plan["include_in_live_stats"] if "include_in_live_stats" in plan.keys() and plan["include_in_live_stats"] is not None else 1)),
        "points": int(plan["points"] or len(tickets)),
        "cost_yen": cost,
        "payout_yen": payout,
        "profit_yen": payout - cost if evaluated else None,
        "return_rate": float(plan["return_rate"] or 0.0) if evaluated else None,
        "hit": bool(plan["hit"]) if evaluated else False,
        "full_refund": bool(full_refund),
        "black_hit": bool(plan["black_hit"]) if evaluated else False,
        "gami_hit": bool(plan["gami_hit"]) if evaluated else False,
        "hit_tickets": hit_tickets,
        "tickets": [dict(t) for t in tickets],
    }


def _v208_render_mixed_plan_result(result: dict) -> None:
    """結果分析の先頭付近に、回収率重視プランを買った想定の実績を表示する。"""
    st.subheader("💰 回収率重視プランの実結果")
    if not isinstance(result, dict) or not result.get("available"):
        st.info((result or {}).get("reason", "保存された回収率重視プランがありません。"))
        return
    if str(result.get("plan_origin") or "live") == "restored_after_odds":
        srcv = str(result.get("source_prediction_version") or "不明")
        st.info(f"♻️ 復元・後付け評価プランです（復元元予測: {srcv}）。通常のリアルタイム回収率実績・学習には含めません。")
    if not result.get("evaluated"):
        st.warning("プランは保存されていますが、払戻金との照合がまだ完了していません。")
        return
    full_refund = bool(result.get("full_refund"))
    hit = bool(result.get("hit"))
    black = bool(result.get("black_hit"))
    gami = bool(result.get("gami_hit"))
    if full_refund:
        verdict = "↩ 全返還"
    elif not hit:
        verdict = "× 外れ"
    elif black:
        verdict = "◎ 的中・黒字"
    elif gami:
        verdict = "△ 的中・ガミ"
    else:
        verdict = "○ 的中"
    a,b,c,d = st.columns(4)
    a.metric("的中判定", verdict)
    b.metric("購入想定", f"{int(result.get('cost_yen',0)):,}円")
    c.metric("払戻合計", f"{int(result.get('payout_yen',0)):,}円")
    d.metric("実回収率", f"{float(result.get('return_rate',0)):.1f}%")
    profit = int(result.get("profit_yen") or 0)
    st.metric("収支", f"{profit:+,}円")
    hit_tickets = result.get("hit_tickets") or []
    if full_refund:
        st.caption("このレースは全返還です。投資額と同額を返還し、回収率100%として記録します。的中率・買い目学習には使用しません。")
    elif hit_tickets:
        rows=[]
        for t in hit_tickets:
            rows.append({
                "券種": t.get("bet_type", ""),
                "的中買い目": t.get("combination", ""),
                "払戻": int(t.get("payout_yen") or 0),
            })
        st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True,
            column_config={"払戻": st.column_config.NumberColumn(format="%d円")})
        st.caption("複数券種が同時的中した場合は、100円購入時の払戻を合算しています。")
    else:
        st.caption("保存された推奨買い目に的中券はありませんでした。")
    if str(result.get("plan_origin") or "live") == "restored_after_odds":
        st.caption(f"復元予測へ後から入力したオッズで保存したプラン（{int(result.get('points',0))}点）を参考採点しています。リアルタイム実績には加算しません。")
    else:
        st.caption(f"予測時に保存された最新プラン（{int(result.get('points',0))}点）だけで判定しています。結果確認後の買い目差し替えは行いません。")


def _v187_learning_profile(db_path: str, cutoff_race_date: str = "") -> dict:
    """回収率学習。Ver304では同一レースの再シミュ版を重複学習しない。"""
    try:
        _v187_ensure_mixed_learning_tables(db_path)
    except sqlite3.DatabaseError as _db187:
        return {
            "races":0, "return_rate":None, "hit_rate":None, "black_rate":None,
            "gami_rate":None, "ticket_stats":{}, "enabled":False,
            "reason":f"回収率学習DBを一時スキップ: {type(_db187).__name__}: {_db187}"
        }
    _v187_sync_mixed_feedback(db_path)
    out = {"samples":0, "hit_rate":None, "black_rate":None, "gami_rate":None,
           "return_rate":None, "type_weights":{}}
    _cut187 = str(cutoff_race_date or "").strip()[:10]

    # 同じ race_key をVer違い・再シミュ違いで何十回も数えると、
    # 1レースの結果が学習を占有する。1 race_key = 1学習標本へ正規化する。
    # 過去再シミュでは、対象レースより前に「実際に作成済み」だったプランだけを候補にする。
    where_extra = ""
    params = ()
    if _cut187:
        where_extra = """
          AND COALESCE(NULLIF(r.race_date,''),'9999-12-31') < ?
          AND substr(COALESCE(r.created_at,''),1,10) < ?
        """
        params = (_cut187, _cut187)

    with sqlite3.connect(db_path) as con:
        ranked_sql = """
            WITH eligible AS (
                SELECT r.*,
                       ROW_NUMBER() OVER (
                           PARTITION BY r.race_key
                           ORDER BY r.created_at DESC, r.plan_hash DESC
                       ) AS rn
                FROM v187_mixed_plan_runs r
                WHERE COALESCE(r.include_in_live_stats,1)=1
                  AND NOT (
                    COALESCE(r.plan_origin,'live')='current_version_restore'
                    AND COALESCE(NULLIF(r.app_version,''),'Unknown')
                        <> COALESCE(NULLIF(r.source_prediction_version,''),
                                    COALESCE(NULLIF(r.app_version,''),'Unknown'))
                  )
        """ + where_extra + """
            )
        """

        row = con.execute(ranked_sql + """
            SELECT COUNT(*), AVG(f.hit)*100.0, AVG(f.black_hit)*100.0,
                   AVG(f.gami_hit)*100.0, AVG(f.return_rate)
            FROM eligible r
            JOIN v187_mixed_plan_feedback f
              ON r.race_key=f.race_key AND r.plan_hash=f.plan_hash
            WHERE r.rn=1
              AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
        """, params).fetchone()

        if row and int(row[0] or 0)>0:
            out.update(samples=int(row[0]), hit_rate=float(row[1] or 0),
                       black_rate=float(row[2] or 0), gami_rate=float(row[3] or 0),
                       return_rate=float(row[4] or 0))

        rows = con.execute(ranked_sql + """
            SELECT tf.bet_type, COUNT(*) n, AVG(tf.hit)*100.0 hit_rate,
                   AVG(tf.payout_yen) avg_payout
            FROM eligible r
            JOIN v187_mixed_ticket_feedback tf
              ON r.race_key=tf.race_key AND r.plan_hash=tf.plan_hash
            JOIN v187_mixed_plan_feedback pf
              ON pf.race_key=r.race_key AND pf.plan_hash=r.plan_hash
            WHERE r.rn=1
              AND COALESCE(pf.winning_types,'') NOT LIKE '%全返還%'
            GROUP BY tf.bet_type
        """, params).fetchall()

        for bet_type,n,hit_rate,avg_payout in rows:
            # 少数標本は中立1.0へ強く縮小。独立レースが増えて初めて効かせる。
            reliability = min(1.0, float(n)/30.0)
            raw = 0.80 + min(0.40, max(0.0, float(hit_rate or 0)/25.0))
            out["type_weights"][bet_type] = 1.0 + (raw-1.0)*reliability
    return out

def _v215_race_meta_from_key(race_key: str, db_path: str) -> dict:
    """レースキーまたは結果DBから、集計用の日付・開催場・Rを取得する。"""
    out = {"race_date": "", "venue": "", "race_no": "", "starter_count": None}
    key = str(race_key or "")
    m = re.match(r"^(\d{8})_([^_]+)_(\d+)R$", key)
    if m:
        ymd, venue, race_no = m.groups()
        out.update(race_date=f"{ymd[:4]}-{ymd[4:6]}-{ymd[6:8]}", venue=venue, race_no=race_no)
    try:
        with sqlite3.connect(db_path) as con:
            con.row_factory = sqlite3.Row
            row = con.execute(
                "SELECT race_date, venue, race_no FROM result_races WHERE race_key=? LIMIT 1",
                (key,),
            ).fetchone()
            if row:
                out["race_date"] = str(row["race_date"] or out["race_date"])
                out["venue"] = str(row["venue"] or out["venue"])
                out["race_no"] = str(row["race_no"] or out["race_no"])
    except Exception:
        pass
    return out


def _v310_fingerprint(obj) -> str:
    def _jsonable(x):
        if isinstance(x, dict):
            return {str(k): _jsonable(v) for k,v in x.items()}
        if isinstance(x, (list,tuple)):
            return [_jsonable(v) for v in x]
        if hasattr(x, 'item'):
            try: return x.item()
            except Exception: pass
        return x
    try:
        raw = json.dumps(_jsonable(obj or {}), ensure_ascii=False, sort_keys=True, default=str, separators=(',', ':'))
        return hashlib.sha256(raw.encode('utf-8')).hexdigest()[:20]
    except Exception:
        return ''


def _v310_save_diagnostic(db_path: str, race_key: str, view: dict, source_version: str,
                          restored: bool, source_hash: str, current_hash: str,
                          bets_before_lap: dict, bets_after_lap: dict,
                          wall_audit: dict, trials: int, seed: int) -> None:
    """Ver310: 買い目差分の発生段階を後から特定できる診断情報を保存する。"""
    def _top(obj):
        rows=[]
        for typ, vals in (obj or {}).items():
            if not isinstance(vals, dict):
                continue
            for combo, prob in vals.items():
                try:
                    if isinstance(prob, dict):
                        prob = prob.get('probability', prob.get('p', prob.get('successes', 0)))
                    rows.append((float(prob), str(typ), json.dumps(combo, ensure_ascii=False, default=str)))
                except Exception: pass
        return [{'type':t,'combo':c,'probability':round(p,6)} for p,t,c in sorted(rows, reverse=True)[:30]]
    _v187_ensure_mixed_learning_tables(db_path)
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute('''CREATE TABLE IF NOT EXISTS v310_plan_diagnostics (
            id INTEGER PRIMARY KEY AUTOINCREMENT, race_key TEXT NOT NULL,
            app_version TEXT, source_prediction_version TEXT, created_at TEXT,
            trials INTEGER, seed INTEGER, model_state_restored INTEGER,
            source_model_state_hash TEXT, current_model_state_hash TEXT,
            bets_before_lap_hash TEXT, bets_after_lap_hash TEXT,
            bets_before_lap_top_json TEXT, bets_after_lap_top_json TEXT,
            wall_audit_json TEXT, input_meta_json TEXT
        )''')
        con.execute('''INSERT INTO v310_plan_diagnostics
            (race_key,app_version,source_prediction_version,created_at,trials,seed,
             model_state_restored,source_model_state_hash,current_model_state_hash,
             bets_before_lap_hash,bets_after_lap_hash,bets_before_lap_top_json,
             bets_after_lap_top_json,wall_audit_json,input_meta_json)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''', (
            str(race_key), str(_V231_APP_VERSION), str(source_version or ''), _v228_now_jst_iso(),
            int(trials or 0), int(seed or 0), int(bool(restored)), str(source_hash or ''),
            str(current_hash or ''), _v310_fingerprint(bets_before_lap), _v310_fingerprint(bets_after_lap),
            json.dumps(_top(bets_before_lap), ensure_ascii=False),
            json.dumps(_top(bets_after_lap), ensure_ascii=False),
            json.dumps(wall_audit or {}, ensure_ascii=False, default=str),
            json.dumps({'source_version':str(source_version or ''),'race_key':str(race_key)}, ensure_ascii=False),
        ))
        con.commit()


def _v187_save_mixed_plan(
    db_path: str, race_key: str, result: dict, app_version: str | None = None,
    plan_origin: str = "live", source_prediction_version: str | None = None,
    include_in_live_stats: bool = True,
) -> str:
    """回収率重視プランを買い目・オッズ・確率・版情報・生成経路ごと完全保存する。

    Ver302集計修正3: 復元プランは元予測版を app_version として保存する。
    source_prediction_version も保持し、復元操作だけで現在版の回収率実績を増やさない。
    """
    source_version = str(app_version or _V231_APP_VERSION or "Unknown").strip() or "Unknown"
    origin = str(plan_origin or "live").strip() or "live"
    src_pred_ver = str(source_prediction_version or source_version or "Unknown").strip() or "Unknown"
    # Ver302集計修正3: 復元プランは「復元した時の現在Ver」ではなく元予測Verへ直接保存する。
    # これにより日別・開催場別・月別・レース明細など全ての実績集計で版が一貫する。
    effective_version = src_pred_ver if origin == "current_version_restore" and src_pred_ver not in ("", "Unknown") else source_version
    live_flag = 1 if bool(include_in_live_stats) else 0
    _v187_ensure_mixed_learning_tables(db_path)
    payload = {
        "app_version": effective_version,
        "logic_version": "return_plan_v279_7types_trial",
        "plan_origin": origin,
        "source_prediction_version": src_pred_ver,
        "include_in_live_stats": live_flag,
        "tickets": [
            (t.get("type"), t.get("combo"), round(float(t.get("odds", 0)), 3), round(float(t.get("probability", 0)), 5))
            for t in result.get("tickets", [])
        ],
    }
    plan_hash = hashlib.sha1(json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:16]
    now = _v228_now_jst_iso()
    meta = _v215_race_meta_from_key(str(race_key), db_path)
    starter_count = result.get("starter_count")
    try:
        starter_count = int(starter_count) if starter_count else None
    except Exception:
        starter_count = None
    with sqlite3.connect(db_path) as con:
        cur = con.execute("""
            INSERT OR IGNORE INTO v187_mixed_plan_runs
            (race_key,plan_hash,points,cost_yen,grade,cover,black,low,hit_average_multiple,
             model_expected_multiple,model_return_rate,role_count,created_at,
             app_version,logic_version,race_date,venue,race_no,starter_count,
             plan_origin,source_prediction_version,include_in_live_stats)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (
            str(race_key), plan_hash, int(result.get("points", 0)), int(result.get("cost", 0)), result.get("grade"),
            float(result.get("cover", 0)), float(result.get("black", 0)), float(result.get("low", 0)),
            float(result.get("hit_average_multiple", 0)), float(result.get("model_expected_multiple", 0)),
            float(result.get("model_return_rate", 0)), len(result.get("grouped", {})), now,
            effective_version, "return_plan_v279_7types_trial", meta.get("race_date"), meta.get("venue"), meta.get("race_no"), starter_count,
            origin, src_pred_ver, live_flag,
        ))
        if int(cur.rowcount or 0) > 0:
            for t in result.get("tickets", []):
                con.execute("""
                    INSERT OR IGNORE INTO v187_mixed_plan_tickets
                    (race_key,plan_hash,bet_type,combination,probability,odds,role) VALUES (?,?,?,?,?,?,?)
                """, (
                    str(race_key), plan_hash, _v212_norm_bet_type(t.get("type")), t.get("combo"),
                    float(t.get("probability", 0)), float(t.get("odds", 0)), t.get("role"),
                ))
        con.commit()
    _v187_sync_mixed_feedback(db_path)
    return plan_hash



_V304_COMMON_RACE_COMPARISON = "2026-08-16-v1"

_V304_ALL_CALCULABLE_RACES = "2026-08-16-v1"

def _v304_all_calculable_race_keys(db_path):
    """保存買い目と結果照合が揃い、実回収率を計算できる全race_key。Ver共通条件なし。"""
    try:
        with sqlite3.connect(str(db_path)) as con:
            rows = con.execute("""
                SELECT DISTINCT r.race_key
                  FROM v187_mixed_plan_runs r
                  JOIN v187_mixed_plan_feedback f
                    ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                 WHERE COALESCE(r.include_in_live_stats,1)=1
                   AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                   AND f.cost_yen IS NOT NULL
                   AND f.payout_yen IS NOT NULL
            """).fetchall()
        return {str(x[0]) for x in rows if x and x[0]}
    except Exception:
        return set()




_V304_SAFE_REBUILD_INPUT = "2026-08-16-v2"

def _v304_safe_result_rebuild_keys(db_path: str) -> set[str]:
    """結果DBから、事前に判明していた項目だけで出走表を再構成できるrace_key。"""
    try:
        with sqlite3.connect(str(db_path)) as con:
            rows = con.execute("""
                SELECT rr.race_key,
                       COUNT(CASE
                           WHEN COALESCE(TRIM(re.player_name),'')<>''
                            AND re.car_no IS NOT NULL
                            AND COALESCE(TRIM(re.result_status),'通常')
                                NOT IN ('欠車','出走取消','出走取り消し','不出走','除外','参加解除')
                           THEN 1 END) AS starters,
                       COUNT(CASE
                           WHEN COALESCE(TRIM(re.player_name),'')<>''
                            AND re.car_no IS NOT NULL
                            AND re.trial_time IS NOT NULL
                            AND COALESCE(TRIM(re.result_status),'通常')
                                NOT IN ('欠車','出走取消','出走取り消し','不出走','除外','参加解除')
                           THEN 1 END) AS trial_rows
                  FROM result_races rr
                  JOIN result_entries re ON re.race_key=rr.race_key
                 WHERE COALESCE(TRIM(rr.race_date),'')<>''
                   AND COALESCE(TRIM(rr.venue),'')<>''
                   AND COALESCE(TRIM(rr.race_no),'')<>''
                 GROUP BY rr.race_key
                HAVING starters>=2 AND trial_rows>=2
            """).fetchall()
        return {str(r[0]) for r in rows if r and r[0]}
    except Exception:
        return set()


def _v304_build_safe_prediction_text_from_result(db_path: str, race_key: str) -> tuple[str, dict]:
    """結果登録DBから「レース前に判明していた項目だけ」を使い、再予測用テキストを作る。

    使用:
      日付 / 開催場 / R / 走路状態 / 走路温度 / 気温 / 湿度 /
      車番 / 選手名 / ハンデ / 試走T

    不使用:
      着順 / 競走T / 実際のST / 払戻 / 結果ステータス由来の走力情報
    """
    try:
        with sqlite3.connect(str(db_path)) as con:
            con.row_factory = sqlite3.Row
            rr = con.execute("""
                SELECT race_key,race_date,venue,race_no,surface,track_temp,air_temp,humidity
                  FROM result_races
                 WHERE race_key=?
            """, (str(race_key or ""),)).fetchone()
            if not rr:
                return "", {"reason":"result_racesなし"}

            ents = con.execute("""
                SELECT car_no,player_name,handicap,trial_time,result_status
                  FROM result_entries
                 WHERE race_key=?
                 ORDER BY car_no
            """, (str(race_key or ""),)).fetchall()

        usable = []
        nonstarter = {'欠車','出走取消','出走取り消し','不出走','除外','参加解除'}
        for e in ents:
            status = str(e["result_status"] or "通常").strip()
            if status in nonstarter:
                continue
            if e["car_no"] is None or not str(e["player_name"] or "").strip():
                continue
            usable.append(e)
        if len(usable) < 2:
            return "", {"reason":"再構成可能な出走者不足"}

        date_s = str(rr["race_date"] or "")[:10]
        m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", date_s)
        if not m:
            return "", {"reason":"日付不正"}
        yy, mm, dd = [int(x) for x in m.groups()]
        rno_m = re.search(r"\d+", str(rr["race_no"] or ""))
        if not rno_m:
            return "", {"reason":"R番号不正"}
        rno = int(rno_m.group())

        surface = str(rr["surface"] or "良走路").strip() or "良走路"
        track_temp = float(rr["track_temp"]) if rr["track_temp"] is not None else 30.0

        lines = [
            f"{rno}R",
            f"{yy}年{mm}月{dd}日",
            str(rr["venue"] or "").strip(),
            f"3100m {len(usable)}車 6周",
            f"{surface} /{track_temp:g}℃",
        ]
        if rr["air_temp"] is not None:
            lines.append(f"気温：{float(rr['air_temp']):g}℃")
        if rr["humidity"] is not None:
            lines.append(f"湿度：{float(rr['humidity']):g}%")

        for e in usable:
            h = re.search(r"-?\d+", str(e["handicap"] or "0"))
            hnum = int(h.group()) if h else 0
            trial = e["trial_time"]
            if trial is not None:
                lines.append(
                    f"{int(e['car_no'])} {str(e['player_name']).strip()} "
                    f"{hnum}m {float(trial):.2f}"
                )
            else:
                lines.append(
                    f"{int(e['car_no'])} {str(e['player_name']).strip()} {hnum}m"
                )

        return "\n".join(lines), {
            "source":"result_prerace_safe_rebuild",
            "race_key":str(race_key or ""),
            "fields":[
                "race_date","venue","race_no","surface","track_temp","air_temp","humidity",
                "car_no","player_name","handicap","trial_time"
            ],
            "excluded_future_fields":[
                "finish","race_time","start_time(actual_ST)","payout","winning_types"
            ],
        }
    except Exception as exc:
        return "", {"reason":f"{type(exc).__name__}: {exc}"}


def _v304_missing_full_replay_records(db_path: str, current_ver: str) -> list[dict]:
    """現行Ver未採点の回収率計算可能レースを、保存入力または安全再構成入力で再実行候補化。"""
    result = []
    try:
        with sqlite3.connect(str(db_path)) as con:
            con.row_factory = sqlite3.Row
            calc = {str(r[0]) for r in con.execute("""
                SELECT DISTINCT r.race_key
                  FROM v187_mixed_plan_runs r
                  JOIN v187_mixed_plan_feedback f
                    ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                 WHERE COALESCE(r.include_in_live_stats,1)=1
                   AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                   AND f.cost_yen IS NOT NULL
                   AND f.payout_yen IS NOT NULL
            """).fetchall() if r and r[0]}
            cur = {str(r[0]) for r in con.execute("""
                SELECT DISTINCT r.race_key
                  FROM v187_mixed_plan_runs r
                  JOIN v187_mixed_plan_feedback f
                    ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                 WHERE COALESCE(NULLIF(r.app_version,''),'Unknown')=?
                   AND COALESCE(r.include_in_live_stats,1)=1
                   AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                   AND f.cost_yen IS NOT NULL
                   AND f.payout_yen IS NOT NULL
            """,(str(current_ver or ""),)).fetchall() if r and r[0]}
            hist = {str(r[0]) for r in con.execute("""
                SELECT DISTINCT race_key FROM v231_prediction_history
                 WHERE race_key IS NOT NULL AND TRIM(race_key)<>''
            """).fetchall() if r and r[0]}
            try:
                restore = {
                    str(r[0]) for r in con.execute("""
                        SELECT race_key FROM v222_prediction_restore
                         WHERE COALESCE(TRIM(raw_text),'')<>''
                    """).fetchall() if r and r[0]
                }
            except Exception:
                restore = set()

            latest_source = {}
            for rk, ver in con.execute("""
                SELECT race_key,app_version FROM (
                    SELECT race_key,COALESCE(NULLIF(app_version,''),'Unknown') app_version,
                           ROW_NUMBER() OVER (
                               PARTITION BY race_key
                               ORDER BY created_at DESC,plan_hash DESC
                           ) rn
                      FROM v187_mixed_plan_runs
                     WHERE COALESCE(include_in_live_stats,1)=1
                ) WHERE rn=1
            """).fetchall():
                latest_source[str(rk)] = str(ver or "Unknown")

        missing = sorted(calc - cur)
        for rk in missing:
            # Normal v231 history is already supplied by the normal batch path.
            if rk in hist:
                continue

            if rk in restore:
                view, raw_text, venue_override = _v222_load_prediction_restore(db_path, rk)
                if str(raw_text or "").strip():
                    result.append({
                        "history_id":0,
                        "race_key":rk,
                        "race_label":_v222_race_label((view or {}).get("meta") or {},rk),
                        "app_version":str((view or {}).get("app_version") or latest_source.get(rk) or "Unknown"),
                        "simulation_mode":"restore_fallback",
                        "settings_hash":"",
                        "prediction_time":"",
                        "trials":int((view or {}).get("trials") or 20000),
                        "seed":int((view or {}).get("seed") or 20260719),
                        "_v304_raw_text":str(raw_text),
                        "_v304_venue_override":str(venue_override or ""),
                        "_v304_view":view if isinstance(view,dict) else {},
                        "_v304_input_source":"saved_restore",
                    })
                    continue

            raw_text, audit = _v304_build_safe_prediction_text_from_result(db_path, rk)
            if str(raw_text or "").strip():
                m = re.match(r'^(\d{8})_(.+?)_(\d+)R$', rk)
                label = rk
                if m:
                    d8, venue, rno = m.groups()
                    label = f"{d8[:4]}-{d8[4:6]}-{d8[6:8]} {venue} {int(rno)}R"
                result.append({
                    "history_id":0,
                    "race_key":rk,
                    "race_label":label,
                    "app_version":latest_source.get(rk,"Unknown"),
                    "simulation_mode":"safe_result_rebuild",
                    "settings_hash":"",
                    "prediction_time":"",
                    "trials":20000,
                    "seed":20260719,
                    "_v304_raw_text":raw_text,
                    "_v304_venue_override":"",
                    "_v304_view":{},
                    "_v304_input_source":"result_prerace_safe_rebuild",
                    "_v304_rebuild_audit":audit,
                })
        return result
    except Exception:
        return []

def _v304_roi_population_status(db_path, current_ver):
    """回収率計算可能な全レースと、現行Ver採点済み・再シミュ可能な残りを数える。"""
    out = {
        "all_calculable":0,
        "current_evaluated":0,
        "remaining":0,
        "replayable_remaining":0,
        "saved_history_remaining":0,
        "saved_restore_remaining":0,
        "safe_rebuild_remaining":0,
        "no_input_remaining":0,
    }
    try:
        with sqlite3.connect(str(db_path)) as con:
            all_keys = {str(r[0]) for r in con.execute("""
                SELECT DISTINCT r.race_key
                  FROM v187_mixed_plan_runs r
                  JOIN v187_mixed_plan_feedback f
                    ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                 WHERE COALESCE(r.include_in_live_stats,1)=1
                   AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                   AND f.cost_yen IS NOT NULL
                   AND f.payout_yen IS NOT NULL
            """).fetchall() if r and r[0]}

            cur_keys = {str(r[0]) for r in con.execute("""
                SELECT DISTINCT r.race_key
                  FROM v187_mixed_plan_runs r
                  JOIN v187_mixed_plan_feedback f
                    ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                 WHERE COALESCE(NULLIF(r.app_version,''),'Unknown')=?
                   AND COALESCE(r.include_in_live_stats,1)=1
                   AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                   AND f.cost_yen IS NOT NULL
                   AND f.payout_yen IS NOT NULL
            """,(str(current_ver or ""),)).fetchall() if r and r[0]}

            hist_keys = {str(r[0]) for r in con.execute("""
                SELECT DISTINCT race_key FROM v231_prediction_history
                 WHERE race_key IS NOT NULL AND TRIM(race_key)<>''
            """).fetchall() if r and r[0]}

            try:
                restore_keys = {str(r[0]) for r in con.execute("""
                    SELECT race_key FROM v222_prediction_restore
                     WHERE COALESCE(TRIM(raw_text),'')<>''
                """).fetchall() if r and r[0]}
            except Exception:
                restore_keys = set()

        rebuild_keys = _v304_safe_result_rebuild_keys(db_path)
        remaining = all_keys - cur_keys
        saved_hist = remaining & hist_keys
        saved_restore = (remaining - hist_keys) & restore_keys
        rebuild = (remaining - hist_keys - restore_keys) & rebuild_keys
        replayable = saved_hist | saved_restore | rebuild
        no_input = remaining - replayable

        out.update(
            all_calculable=len(all_keys),
            current_evaluated=len(all_keys & cur_keys),
            remaining=len(remaining),
            replayable_remaining=len(replayable),
            saved_history_remaining=len(saved_hist),
            saved_restore_remaining=len(saved_restore),
            safe_rebuild_remaining=len(rebuild),
            no_input_remaining=len(no_input),
        )
    except Exception as exc:
        out["error"]=f"{type(exc).__name__}: {exc}"
    return out


def _v304_ensure_legacy_plan_rescore_table(db_path: str) -> None:
    with sqlite3.connect(str(db_path),timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        con.execute("""
            CREATE TABLE IF NOT EXISTS v304_legacy_plan_rescore (
                race_key TEXT PRIMARY KEY,
                source_plan_hash TEXT NOT NULL,
                source_app_version TEXT,
                source_created_at TEXT,
                recommendation_label TEXT NOT NULL,
                recommended INTEGER NOT NULL DEFAULT 0,
                max_ev REAL NOT NULL DEFAULT 0,
                support_count INTEGER NOT NULL DEFAULT 0,
                cost_yen INTEGER NOT NULL DEFAULT 0,
                payout_yen INTEGER NOT NULL DEFAULT 0,
                return_rate REAL,
                rescored_at TEXT NOT NULL
            )
        """)
        con.commit()


def _v304_legacy_rescore_missing_without_history(db_path: str, current_ver: str) -> dict:
    """v231履歴が無い旧レースは、保存済みプランをVer301強推奨基準で再採点する。

    これは現行モデルの再シミュレーションではない。保存済み買い目を変えず、
    最終推奨判定だけを同一基準で再評価する監査用フォールバック。
    """
    _v304_ensure_legacy_plan_rescore_table(db_path)
    out={"checked":0,"rescored":0,"recommended":0,"errors":[]}
    try:
        with sqlite3.connect(str(db_path),timeout=30.0) as con:
            con.row_factory=sqlite3.Row
            con.execute("PRAGMA busy_timeout=30000")
            rows=con.execute("""
                WITH calc AS (
                    SELECT DISTINCT r.race_key
                    FROM v187_mixed_plan_runs r
                    JOIN v187_mixed_plan_feedback f
                      ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                    WHERE COALESCE(r.include_in_live_stats,1)=1
                      AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                      AND f.cost_yen IS NOT NULL AND f.payout_yen IS NOT NULL
                ), cur AS (
                    SELECT DISTINCT r.race_key
                    FROM v187_mixed_plan_runs r
                    JOIN v187_mixed_plan_feedback f
                      ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                    WHERE COALESCE(NULLIF(r.app_version,''),'Unknown')=?
                      AND COALESCE(r.include_in_live_stats,1)=1
                      AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                      AND f.cost_yen IS NOT NULL AND f.payout_yen IS NOT NULL
                ), hist AS (
                    SELECT DISTINCT race_key FROM v231_prediction_history
                    WHERE race_key IS NOT NULL AND TRIM(race_key)<>''
                ), ranked AS (
                    SELECT r.race_key,r.plan_hash,COALESCE(r.app_version,'Unknown') app_version,
                           r.created_at,f.cost_yen,f.payout_yen,f.return_rate,
                           ROW_NUMBER() OVER (
                               PARTITION BY r.race_key
                               ORDER BY r.created_at DESC,r.plan_hash DESC
                           ) rn
                    FROM v187_mixed_plan_runs r
                    JOIN v187_mixed_plan_feedback f
                      ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                    JOIN calc c ON c.race_key=r.race_key
                    LEFT JOIN cur cv ON cv.race_key=r.race_key
                    LEFT JOIN hist h ON h.race_key=r.race_key
                    WHERE cv.race_key IS NULL AND h.race_key IS NULL
                      AND COALESCE(r.include_in_live_stats,1)=1
                      AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                      AND f.cost_yen IS NOT NULL AND f.payout_yen IS NOT NULL
                      AND NOT (
                        COALESCE(r.plan_origin,'live')='current_version_restore'
                        AND COALESCE(NULLIF(r.app_version,''),'Unknown')
                            <> COALESCE(NULLIF(r.source_prediction_version,''),
                                        COALESCE(NULLIF(r.app_version,''),'Unknown'))
                      )
                )
                SELECT * FROM ranked WHERE rn=1 ORDER BY race_key
            """,(str(current_ver or ''),)).fetchall()

            for row in rows:
                out["checked"]+=1
                try:
                    tickets=con.execute("""
                        SELECT bet_type,combination,probability,odds
                        FROM v187_mixed_plan_tickets
                        WHERE race_key=? AND plan_hash=?
                        ORDER BY bet_type,combination
                    """,(row["race_key"],row["plan_hash"])).fetchall()
                    if not tickets:
                        continue
                    _tickets=[]
                    for t in tickets:
                        _tickets.append({
                            "type":_v212_norm_bet_type(t["bet_type"]),
                            "combo":str(t["combination"] or ''),
                            "probability":float(t["probability"] or 0.0),
                            "odds":float(t["odds"] or 0.0),
                        })
                    rec=_v301_live_recommendation({"tickets":_tickets})
                    con.execute("""
                        INSERT INTO v304_legacy_plan_rescore(
                            race_key,source_plan_hash,source_app_version,source_created_at,
                            recommendation_label,recommended,max_ev,support_count,
                            cost_yen,payout_yen,return_rate,rescored_at
                        ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)
                        ON CONFLICT(race_key) DO UPDATE SET
                            source_plan_hash=excluded.source_plan_hash,
                            source_app_version=excluded.source_app_version,
                            source_created_at=excluded.source_created_at,
                            recommendation_label=excluded.recommendation_label,
                            recommended=excluded.recommended,
                            max_ev=excluded.max_ev,
                            support_count=excluded.support_count,
                            cost_yen=excluded.cost_yen,
                            payout_yen=excluded.payout_yen,
                            return_rate=excluded.return_rate,
                            rescored_at=excluded.rescored_at
                    """,(
                        str(row["race_key"]),str(row["plan_hash"]),str(row["app_version"] or 'Unknown'),
                        str(row["created_at"] or ''),str(rec.get("label") or "見送り寄り"),
                        1 if rec.get("recommended") else 0,float(rec.get("max_ev",0.0) or 0.0),
                        int(rec.get("support_count",0) or 0),int(row["cost_yen"] or 0),
                        int(row["payout_yen"] or 0),float(row["return_rate"] or 0.0),
                        _v228_now_jst_iso(),
                    ))
                    out["rescored"]+=1
                    out["recommended"]+=int(bool(rec.get("recommended")))
                except Exception as exc:
                    if len(out["errors"])<10:
                        out["errors"].append(f"{row['race_key']}: {type(exc).__name__}: {exc}")
            con.commit()
        return out
    except Exception as exc:
        out["errors"].append(f"{type(exc).__name__}: {exc}")
        return out


def _v304_legacy_rescore_summary(db_path: str) -> dict:
    out={"races":0,"recommended":0,"cost":0,"payout":0,"recommended_cost":0,"recommended_payout":0}
    try:
        _v304_ensure_legacy_plan_rescore_table(db_path)
        with sqlite3.connect(str(db_path)) as con:
            r=con.execute("""
                SELECT COUNT(*),SUM(recommended),SUM(cost_yen),SUM(payout_yen),
                       SUM(CASE WHEN recommended=1 THEN cost_yen ELSE 0 END),
                       SUM(CASE WHEN recommended=1 THEN payout_yen ELSE 0 END)
                FROM v304_legacy_plan_rescore
            """).fetchone()
        if r:
            out.update(races=int(r[0] or 0),recommended=int(r[1] or 0),cost=int(r[2] or 0),
                       payout=int(r[3] or 0),recommended_cost=int(r[4] or 0),recommended_payout=int(r[5] or 0))
        if out["cost"]>0: out["return_rate"]=out["payout"]/out["cost"]*100.0
        if out["recommended_cost"]>0: out["recommended_return_rate"]=out["recommended_payout"]/out["recommended_cost"]*100.0
    except Exception as exc:
        out["error"]=f"{type(exc).__name__}: {exc}"
    return out

def _v304_common_race_keys_for_versions(db_path, versions):
    """指定Verすべてに回収率実績がある race_key の共通集合を返す。"""
    versions = [str(v).strip() for v in (versions or []) if str(v).strip()]
    if len(versions) < 2:
        return set()
    try:
        with sqlite3.connect(str(db_path)) as con:
            ph = ",".join("?" for _ in versions)
            rows = con.execute(f"""
                SELECT r.race_key
                  FROM v187_mixed_plan_runs r
                  JOIN v187_mixed_plan_feedback f
                    ON f.race_key=r.race_key AND f.plan_hash=r.plan_hash
                 WHERE COALESCE(NULLIF(r.app_version,''),'Unknown') IN ({ph})
                   AND COALESCE(r.include_in_live_stats,1)=1
                   AND COALESCE(f.winning_types,'') NOT LIKE '%全返還%'
                 GROUP BY r.race_key
                HAVING COUNT(DISTINCT COALESCE(NULLIF(r.app_version,''),'Unknown')) = ?
            """, tuple(versions) + (len(set(versions)),)).fetchall()
        return {str(x[0]) for x in rows if x and x[0]}
    except Exception:
        return set()

def _v304_filter_common_races(df, common_keys):
    """race_key列がある集計DataFrameを共通レースだけへ絞る。"""
    if df is None or getattr(df, "empty", True) or not common_keys:
        return df
    if "race_key" not in df.columns:
        return df
    return df[df["race_key"].astype(str).isin(common_keys)].copy()

def _v300_backfill_recommendation_audit(db_path: str, app_version_filter: str = "Ver300") -> dict:
    """保存済みプランだけから新推奨監査を補完。シミュレーションは実行しない。"""
    _v187_ensure_mixed_learning_tables(db_path)
    calibration=_v195_return_calibration(db_path)
    factor=float(calibration.get("factor",1.0) or 1.0)
    done=0; skipped=0; errors=[]
    with sqlite3.connect(str(db_path),timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        rows=con.execute("""
            SELECT r.race_key,r.plan_hash,r.cover,r.model_return_rate,
                   COALESCE(r.app_version,'')
            FROM v187_mixed_plan_runs r
            LEFT JOIN v300_recommendation_audit a
              ON a.race_key=r.race_key AND a.plan_hash=r.plan_hash
            WHERE a.race_key IS NULL
              AND COALESCE(r.app_version,'')=?
              AND COALESCE(r.include_in_live_stats,1)=1
                  AND NOT (COALESCE(r.plan_origin,'live')='current_version_restore' AND COALESCE(NULLIF(r.app_version,''),'Unknown') <> COALESCE(NULLIF(r.source_prediction_version,''),COALESCE(NULLIF(r.app_version,''),'Unknown')))
            ORDER BY r.created_at
        """,(str(app_version_filter),)).fetchall()
        for race_key,plan_hash,cover,model_rr,app_ver in rows:
            try:
                tickets=con.execute("""
                    SELECT probability,odds,role
                    FROM v187_mixed_plan_tickets
                    WHERE race_key=? AND plan_hash=?
                """,(race_key,plan_hash)).fetchall()
                if not tickets:
                    skipped+=1; continue
                max_ev=0.0; hole_count=0
                for probability,odds,role in tickets:
                    p=float(probability or 0.0); od=float(odds or 0.0)
                    max_ev=max(max_ev,(p/100.0)*od)
                    if "中穴価値候補" in str(role or ""):
                        hole_count+=1
                reconstructed={
                    "tickets":[],
                    "adjusted_return_rate":float(model_rr or 0.0)*factor,
                    "cover":float(cover or 0.0),
                }
                # Reuse the exact scoring thresholds; feed reconstructed ticket EV/hole info explicitly below.
                score=0; reasons=[]; adjusted=float(reconstructed["adjusted_return_rate"]); cv=float(reconstructed["cover"])
                if adjusted<=150.0: score+=2; reasons.append("参考回収率≤150%")
                elif adjusted<=175.0: score+=1; reasons.append("参考回収率≤175%")
                else: score-=2; reasons.append("参考回収率が高すぎる")
                if cv<=40.0: score+=2; reasons.append("カバー≤40%")
                elif cv<=50.0: score+=1; reasons.append("カバー≤50%")
                else: score-=1; reasons.append("カバー広め")
                if max_ev<=2.0: score+=2; reasons.append("最大EV≤2.0")
                elif max_ev<=2.5: score+=1; reasons.append("最大EV≤2.5")
                else: score-=2; reasons.append("最大EV暴走")
                if hole_count in (1,2): score+=1; reasons.append(f"中穴価値候補{hole_count}点")
                elif hole_count>=3: score-=1; reasons.append("穴候補過多")
                label="◎推奨" if score>=6 else ("○候補" if score>=4 else ("△検証中" if score>=2 else "見送り"))
                con.execute("""
                    INSERT OR REPLACE INTO v300_recommendation_audit
                    (race_key,plan_hash,recommendation_label,recommendation_score,
                     adjusted_return_rate,cover,max_ev,hole_count,reasons_json,app_version,created_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)
                """,(str(race_key),str(plan_hash),label,int(score),adjusted,cv,max_ev,int(hole_count),
                     json.dumps(reasons,ensure_ascii=False),str(app_ver or app_version_filter),_v228_now_jst_iso()))
                done+=1
            except Exception as exc:
                errors.append(f"{race_key}: {type(exc).__name__}: {exc}")
        con.commit()
    return {"done":done,"skipped":skipped,"errors":errors,"factor":factor}


def _v301_auto_backfill_strong_recommendation(db_path: str) -> dict:
    """保存済みVer300/Ver301/Ver302プランをVer301強推奨基準で自動再判定する。再シミュレーションは行わない。"""
    _v187_ensure_mixed_learning_tables(db_path)
    done=0; skipped=0; errors=[]
    with sqlite3.connect(str(db_path),timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        rows=con.execute("""
            SELECT r.race_key,r.plan_hash,COALESCE(r.app_version,'')
            FROM v187_mixed_plan_runs r
            WHERE COALESCE(r.include_in_live_stats,1)=1
              AND NOT (COALESCE(r.plan_origin,'live')='current_version_restore' AND COALESCE(NULLIF(r.app_version,''),'Unknown') <> COALESCE(NULLIF(r.source_prediction_version,''),COALESCE(NULLIF(r.app_version,''),'Unknown')))
              AND COALESCE(r.app_version,'') IN ('Ver300','Ver301','Ver302','Ver303','Ver304')
            ORDER BY r.created_at
        """).fetchall()
        for race_key,plan_hash,app_ver in rows:
            try:
                tickets=con.execute("""
                    SELECT bet_type,probability,odds
                    FROM v187_mixed_plan_tickets
                    WHERE race_key=? AND plan_hash=?
                """,(race_key,plan_hash)).fetchall()
                if not tickets:
                    skipped+=1
                    continue
                support_count=len({str(bt or "") for bt,_,_ in tickets if str(bt or "")})
                max_ev=0.0
                for _,probability,odds in tickets:
                    p=float(probability or 0.0)
                    od=float(odds or 0.0)
                    max_ev=max(max_ev,(p/100.0)*od)

                recommended=((max_ev<=1.70 and support_count>=2) or
                             (1.70<max_ev<=2.10 and support_count>=3))
                label="◎強推奨" if recommended else "見送り"
                score=10 if recommended else 0
                reason=(f"Ver301自動再判定: 最大EV {max_ev:.2f} / 券種支持 {support_count} → {label}")

                prev=con.execute("""
                    SELECT adjusted_return_rate,cover,hole_count,reasons_json
                    FROM v300_recommendation_audit
                    WHERE race_key=? AND plan_hash=?
                """,(race_key,plan_hash)).fetchone()
                adjusted=float(prev[0] or 0.0) if prev else 0.0
                cover=float(prev[1] or 0.0) if prev else 0.0
                hole_count=int(prev[2] or 0) if prev else 0
                reasons=[reason]
                if prev and prev[3]:
                    try:
                        old_reasons=json.loads(prev[3])
                        if isinstance(old_reasons,list):
                            reasons=old_reasons+[reason]
                    except Exception:
                        pass

                con.execute("""
                    INSERT INTO v300_recommendation_audit
                    (race_key,plan_hash,recommendation_label,recommendation_score,
                     adjusted_return_rate,cover,max_ev,hole_count,reasons_json,app_version,created_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(race_key,plan_hash) DO UPDATE SET
                        recommendation_label=excluded.recommendation_label,
                        recommendation_score=excluded.recommendation_score,
                        max_ev=excluded.max_ev,
                        reasons_json=excluded.reasons_json,
                        app_version=excluded.app_version,
                        created_at=excluded.created_at
                """,(str(race_key),str(plan_hash),label,int(score),
                     adjusted,cover,float(max_ev),int(hole_count),
                     json.dumps(reasons,ensure_ascii=False),
                     str(app_ver or "Ver301"),_v228_now_jst_iso()))
                done+=1
            except Exception as exc:
                errors.append(f"{race_key}: {type(exc).__name__}: {exc}")
        con.commit()
    return {"done":done,"skipped":skipped,"errors":errors}


def _v300_save_recommendation_audit(
    db_path: str, race_key: str, plan_hash: str, audit: dict,
    app_version: str | None = None,
) -> None:
    """新推奨判定を監査用に保存。買い目・既存gradeには一切反映しない。"""
    if not race_key or not plan_hash or not isinstance(audit,dict) or not audit:
        return
    _v187_ensure_mixed_learning_tables(db_path)
    with sqlite3.connect(str(db_path),timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        con.execute("""
            INSERT INTO v300_recommendation_audit
            (race_key,plan_hash,recommendation_label,recommendation_score,
             adjusted_return_rate,cover,max_ev,hole_count,reasons_json,app_version,created_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(race_key,plan_hash) DO UPDATE SET
                recommendation_label=excluded.recommendation_label,
                recommendation_score=excluded.recommendation_score,
                adjusted_return_rate=excluded.adjusted_return_rate,
                cover=excluded.cover,
                max_ev=excluded.max_ev,
                hole_count=excluded.hole_count,
                reasons_json=excluded.reasons_json,
                app_version=excluded.app_version,
                created_at=excluded.created_at
        """,(
            str(race_key),str(plan_hash),
            str(audit.get("label") or "△検証中"),
            int(audit.get("score",0) or 0),
            float(audit.get("adjusted_return_rate",0.0) or 0.0),
            float(audit.get("cover",0.0) or 0.0),
            float(audit.get("max_ev",0.0) or 0.0),
            int(audit.get("hole_count",0) or 0),
            json.dumps(list(audit.get("reasons") or []),ensure_ascii=False),
            str(app_version or APP_VERSION),
            _v228_now_jst_iso(),
        ))
        con.commit()


def _v195_return_calibration(db_path: str) -> dict:
    """保存済み合成のモデル回収率と実回収率の乖離を、少数標本では弱く反映する。"""
    _v187_ensure_mixed_learning_tables(db_path)
    _v187_sync_mixed_feedback(db_path)
    out = {"samples": 0, "raw_factor": 1.0, "factor": 1.0, "actual_return": None}
    try:
        with sqlite3.connect(db_path) as con:
            row = con.execute("""
                SELECT COUNT(*), SUM(f.payout_yen), SUM(f.cost_yen),
                       SUM(f.cost_yen * COALESCE(r.model_return_rate,0) / 100.0)
                FROM v187_mixed_plan_feedback f
                JOIN v187_mixed_plan_runs r
                  ON r.race_key=f.race_key AND r.plan_hash=f.plan_hash
                WHERE COALESCE(r.include_in_live_stats,1)=1
              AND NOT (COALESCE(r.plan_origin,'live')='current_version_restore' AND COALESCE(NULLIF(r.app_version,''),'Unknown') <> COALESCE(NULLIF(r.source_prediction_version,''),COALESCE(NULLIF(r.app_version,''),'Unknown')))
            """).fetchone()
        n, payout, cost, model_payout = row if row else (0,0,0,0)
        n=int(n or 0); payout=float(payout or 0); cost=float(cost or 0); model_payout=float(model_payout or 0)
        raw = payout/model_payout if model_payout>0 else 1.0
        raw = min(1.10, max(0.35, raw))
        reliability=min(1.0, n/30.0)
        factor=1.0+(raw-1.0)*reliability
        out.update(samples=n, raw_factor=raw, factor=factor, actual_return=(payout/cost*100.0 if cost>0 else None))
    except Exception:
        pass
    return out


# Ver295: 仮想ゲーム用・期待値確率校正。
# 展開確率はそのまま、期待値評価だけを券種×確率帯の過去実現率で縮小補正する。
_V295_EV_CALIBRATION_CACHE = {}

def _v295_norm_combo(bet_type: str, combo) -> str:
    s=str(combo or "").strip().replace("→","-").replace(">","-").replace(" ","")
    parts=[x for x in re.split(r"[-‐‑–—]+",s) if x!=""]
    if str(bet_type) in ("2連複","3連複"):
        try:
            parts=sorted(parts,key=lambda x:int(re.sub(r"\\D","",x) or 999))
        except Exception:
            parts=sorted(parts)
    return "-".join(parts)

def _v295_ev_calibration_table(db_path: str, cutoff_date: str="") -> dict:
    path=str(db_path)
    cutoff=str(cutoff_date or "").strip()[:10]
    try:
        stamp=(path,int(Path(path).stat().st_mtime_ns),cutoff)
    except Exception:
        stamp=(path,0,cutoff)
    if stamp in _V295_EV_CALIBRATION_CACHE:
        return _V295_EV_CALIBRATION_CACHE[stamp]

    edges=[0.0,0.5,1.0,2.0,3.0,5.0,8.0,12.0,20.0,35.0,100.0001]
    out={"edges":edges,"types":{},"samples":0,"cutoff":cutoff}
    supported=("2連単","2連複","3連単","3連複")

    try:
        with sqlite3.connect(path,timeout=12.0) as con:
            con.row_factory=sqlite3.Row
            sql="""
                SELECT t.race_key,t.bet_type,t.combination,t.probability
                FROM v67_prediction_tickets t
                JOIN result_races rr ON rr.race_key=t.race_key
                WHERE t.bet_type IN ('2連単','2連複','3連単','3連複')
                  AND EXISTS (
                    SELECT 1 FROM result_payouts rp
                    WHERE rp.race_key=t.race_key AND rp.bet_type=t.bet_type
                  )
            """
            params=[]
            if cutoff:
                sql+=" AND substr(rr.race_date,1,10) < substr(?,1,10)"
                params.append(cutoff)
            rows=con.execute(sql,params).fetchall()

            wsql="""
                SELECT rp.race_key,rp.bet_type,rp.combination
                FROM result_payouts rp
                JOIN result_races rr ON rr.race_key=rp.race_key
                WHERE rp.bet_type IN ('2連単','2連複','3連単','3連複')
            """
            wparams=[]
            if cutoff:
                wsql+=" AND substr(rr.race_date,1,10) < substr(?,1,10)"
                wparams.append(cutoff)
            win_rows=con.execute(wsql,wparams).fetchall()
    except Exception:
        _V295_EV_CALIBRATION_CACHE[stamp]=out
        return out

    wins=set(
        (str(r["race_key"]),str(r["bet_type"]),_v295_norm_combo(r["bet_type"],r["combination"]))
        for r in win_rows
    )
    buckets={bt:[{"n":0,"sum_p":0.0,"hits":0} for _ in range(len(edges)-1)] for bt in supported}

    for r in rows:
        bt=str(r["bet_type"] or "")
        try:
            p=float(r["probability"] or 0.0)
        except Exception:
            continue
        if bt not in buckets or not (0.0 <= p <= 100.0):
            continue
        bi=len(edges)-2
        for j in range(len(edges)-1):
            if edges[j] <= p < edges[j+1]:
                bi=j
                break
        b=buckets[bt][bi]
        b["n"]+=1
        b["sum_p"]+=p/100.0
        if (str(r["race_key"]),bt,_v295_norm_combo(bt,r["combination"])) in wins:
            b["hits"]+=1

    # 元モデル200件分を事前分布として実績を縮小。極端な補正は±20%に制限。
    prior_n=100.0
    for bt,arr in buckets.items():
        out["types"][bt]=[]
        for b in arr:
            n=int(b["n"])
            mean_p=(b["sum_p"]/n) if n else None
            if n and mean_p is not None and mean_p>1e-12:
                calibrated=(float(b["hits"])+prior_n*mean_p)/(n+prior_n)
                ratio=float(np.clip(calibrated/mean_p,0.70,1.30))
            else:
                ratio=1.0
            out["types"][bt].append({
                "n":n,
                "mean_p":mean_p,
                "hits":int(b["hits"]),
                "actual_rate":(float(b["hits"]/n) if n else None),
                "ratio":ratio,
            })
            out["samples"]+=n

    _V295_EV_CALIBRATION_CACHE[stamp]=out
    return out

def _v295_ev_probability(raw_probability_pct: float, bet_type: str, table: dict) -> tuple[float,float,int]:
    try:
        p=float(raw_probability_pct)
    except Exception:
        return 0.0,1.0,0
    edges=list((table or {}).get("edges") or [])
    arr=list(((table or {}).get("types") or {}).get(str(bet_type)) or [])
    if len(edges)<2 or not arr:
        return p,1.0,0
    bi=len(edges)-2
    for j in range(len(edges)-1):
        if edges[j] <= p < edges[j+1]:
            bi=j
            break
    row=arr[min(bi,len(arr)-1)]
    ratio=float(row.get("ratio",1.0) or 1.0)
    n=int(row.get("n",0) or 0)
    return float(np.clip(p*ratio,0.0,100.0)),ratio,n



def _v299_ev_trust(raw_ev_multiple: float, bet_type: str, probability_pct: float, odds: float) -> tuple[float,str]:
    """DB167検証に基づく過大EVの滑らかな信頼減衰。

    EV>2を即除外せず徐々に圧縮する。三連単の中穴候補は別枠で探索するため、
    高オッズそのものを罰する関数にはしない。
    """
    ev=max(0.0,float(raw_ev_multiple or 0.0))
    bt=str(bet_type or "")
    p=max(0.0,float(probability_pct or 0.0))
    od=max(0.0,float(odds or 0.0))
    # Ver300: DB169の同一71R比較で、Ver299の新規利益は三連単に集中。
    # 他券種の選び替えは的中を失っていたため、EV信頼減衰は三連単だけに限定する。
    if bt not in ("3連単","三連単"):
        return 1.0,"Ver298互換（非3連単）"
    if ev <= 2.0:
        trust=1.0
        reason="通常"
    else:
        # 2倍超をゼロにせず、超過部分だけ圧縮。極端なモデルEVの暴走を抑える。
        effective=2.0 + 0.35*(ev-2.0)
        trust=max(0.45,min(1.0,effective/max(ev,1e-9)))
        reason="高EV滑らか減衰"
    # 三連単の中穴帯は候補母集団から落とさない。信頼度の下限だけ確保する。
    if 0.8 <= p <= 8.0 and od >= 30.0:
        trust=max(trust,0.72)
        reason += "・穴候補保護"
    return float(np.clip(trust,0.40,1.0)),reason



def _v300_recommendation_audit(result: dict) -> dict:
    """DB169で見えた傾向を監査表示するだけの新推奨判定。買い目・保存gradeには影響させない。"""
    tickets=list(result.get("tickets") or [])
    adjusted=float(result.get("adjusted_return_rate",0.0) or 0.0)
    cover=float(result.get("cover",0.0) or 0.0)
    raw_evs=[]
    hole_count=0
    for t in tickets:
        p=float(t.get("ev_probability",t.get("probability",0.0)) or 0.0)
        od=float(t.get("odds",0.0) or 0.0)
        raw_evs.append((p/100.0)*od)
        if bool(t.get("v299_hole_rescue")):
            hole_count+=1
    max_ev=max(raw_evs) if raw_evs else 0.0

    # 固定AND条件ではなく段階スコア。DB169の有望領域を中心にしつつ境界を滑らかにする。
    score=0
    reasons=[]
    if adjusted <= 150.0:
        score+=2; reasons.append("参考回収率≤150%")
    elif adjusted <= 175.0:
        score+=1; reasons.append("参考回収率≤175%")
    else:
        score-=2; reasons.append("参考回収率が高すぎる")
    if cover <= 40.0:
        score+=2; reasons.append("カバー≤40%")
    elif cover <= 50.0:
        score+=1; reasons.append("カバー≤50%")
    else:
        score-=1; reasons.append("カバー広め")
    if max_ev <= 2.0:
        score+=2; reasons.append("最大EV≤2.0")
    elif max_ev <= 2.5:
        score+=1; reasons.append("最大EV≤2.5")
    else:
        score-=2; reasons.append("最大EV暴走")
    if hole_count in (1,2):
        score+=1; reasons.append(f"中穴価値候補{hole_count}点")
    elif hole_count>=3:
        score-=1; reasons.append("穴候補過多")

    if score>=6:
        label,icon="◎推奨","◎"
    elif score>=4:
        label,icon="○候補","○"
    elif score>=2:
        label,icon="△検証中","△"
    else:
        label,icon="見送り","—"
    return {"label":label,"icon":icon,"score":int(score),"adjusted_return_rate":adjusted,
            "cover":cover,"max_ev":max_ev,"hole_count":hole_count,"reasons":reasons}



def _v301_live_recommendation(result: dict) -> dict:
    """予測時に実運用する強推奨判定。

    DB172までの監査で有望だった条件:
    - 最大EV <= 1.70 かつ 最終プランの券種支持数 >= 2
    - 1.70 < 最大EV <= 2.10 かつ 券種支持数 >= 3

    買い目自体は変更せず、レース推奨表示だけに使う。
    """
    tickets=list(result.get("tickets") or [])
    bet_types={
        str(t.get("type") or "")
        for t in tickets
        if str(t.get("type") or "")
    }
    support_count=len(bet_types)

    evs=[]
    for t in tickets:
        # 実運用時はその場で保持している期待値評価用確率を優先。
        p=float(t.get("ev_probability",t.get("probability",0.0)) or 0.0)
        od=float(t.get("odds",0.0) or 0.0)
        evs.append((p/100.0)*od)
    max_ev=max(evs) if evs else 0.0

    strong = (
        (max_ev <= 1.70 and support_count >= 2)
        or
        (1.70 < max_ev <= 2.10 and support_count >= 3)
    )

    if strong:
        if max_ev <= 1.70:
            reason=f"最大EV {max_ev:.2f} <= 1.70 かつ {support_count}券種支持"
        else:
            reason=f"最大EV {max_ev:.2f}（1.70〜2.10）かつ {support_count}券種支持"
        return {
            "recommended":True,
            "label":"◎強推奨",
            "icon":"🔥",
            "max_ev":float(max_ev),
            "support_count":int(support_count),
            "reason":reason,
        }

    # 非強推奨も理由を明示。
    if max_ev > 2.10:
        why=f"最大EV {max_ev:.2f} > 2.10"
    elif max_ev <= 1.70 and support_count < 2:
        why=f"最大EVは{max_ev:.2f}だが券種支持が{support_count}"
    elif 1.70 < max_ev <= 2.10 and support_count < 3:
        why=f"最大EV {max_ev:.2f}に対して券種支持が{support_count}"
    else:
        why="強推奨条件未達"
    return {
        "recommended":False,
        "label":"見送り寄り",
        "icon":"—",
        "max_ev":float(max_ev),
        "support_count":int(support_count),
        "reason":why,
    }



def _v305_live_recommendation(result: dict) -> dict:
    """Ver305 強推奨判定。

    Ver301のEV条件を候補条件として維持しつつ、
    ◎強推奨は4券種以上の独立した支持がある場合だけに限定する。

    狙い:
    ・過去数Rの当たり外れへ合わせてEV閾値を細かく最適化しない
    ・最終プランが複数券種で同じ方向を支持する「安定性」だけを追加
    ・従来条件は○候補として残し、情報を捨てない
    """
    tickets = list(result.get("tickets") or [])
    bet_types = {
        str(t.get("type") or "")
        for t in tickets
        if str(t.get("type") or "")
    }
    support_count = len(bet_types)

    evs = []
    for t in tickets:
        p = float(t.get("ev_probability", t.get("probability", 0.0)) or 0.0)
        od = float(t.get("odds", 0.0) or 0.0)
        evs.append((p / 100.0) * od)
    max_ev = max(evs) if evs else 0.0

    # Ver301の候補条件はそのまま。
    legacy_candidate = (
        (max_ev <= 1.70 and support_count >= 2)
        or
        (1.70 < max_ev <= 2.10 and support_count >= 3)
    )

    # Ver305: ◎だけは4券種以上の一致を必須にする。
    strong = bool(legacy_candidate and support_count >= 4)

    if strong:
        return {
            "recommended": True,
            "candidate": True,
            "label": "◎強推奨",
            "icon": "🔥",
            "max_ev": float(max_ev),
            "support_count": int(support_count),
            "reason": (
                f"最大EV {max_ev:.2f} / {support_count}券種支持。"
                "Ver301候補条件＋4券種以上の安定性条件を通過"
            ),
        }

    if legacy_candidate:
        return {
            "recommended": False,
            "candidate": True,
            "label": "○候補",
            "icon": "○",
            "max_ev": float(max_ev),
            "support_count": int(support_count),
            "reason": (
                f"Ver301候補条件は通過（最大EV {max_ev:.2f} / {support_count}券種支持）"
                "だが、◎に必要な4券種支持には未達"
            ),
        }

    if max_ev > 2.10:
        why = f"最大EV {max_ev:.2f} > 2.10"
    elif max_ev <= 1.70 and support_count < 2:
        why = f"最大EVは{max_ev:.2f}だが券種支持が{support_count}"
    elif 1.70 < max_ev <= 2.10 and support_count < 3:
        why = f"最大EV {max_ev:.2f}に対して券種支持が{support_count}"
    else:
        why = "強推奨候補条件未達"

    return {
        "recommended": False,
        "candidate": False,
        "label": "見送り",
        "icon": "—",
        "max_ev": float(max_ev),
        "support_count": int(support_count),
        "reason": why,
    }


def _v305_auto_backfill_current_recommendation(db_path: str) -> dict:
    """現在APP_VERSIONの全プランを現行推奨基準で監査補完する。

    Ver307（Ver306の表示不具合修正は維持）:
    - Ver305固定ではなくAPP_VERSIONを対象にする
    - 再シミュレーション済みプランも全件補完
    - 既存の古い/部分監査も現行基準へ更新
    - adjusted_return_rate / cover / hole_countも保存済みプランから再構成
    """
    _v187_ensure_mixed_learning_tables(db_path)
    target_version = str(APP_VERSION or _V231_APP_VERSION or "Ver306")
    calibration = _v195_return_calibration(db_path)
    factor = float(calibration.get("factor", 1.0) or 1.0)

    done = 0
    skipped = 0
    errors = []

    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        rows = con.execute("""
            SELECT
                r.race_key,
                r.plan_hash,
                COALESCE(r.app_version,''),
                COALESCE(r.cover,0),
                COALESCE(r.model_return_rate,0)
            FROM v187_mixed_plan_runs r
            WHERE COALESCE(r.include_in_live_stats,1)=1
              AND COALESCE(r.app_version,'')=?
              AND NOT (
                    COALESCE(r.plan_origin,'live')='current_version_restore'
                    AND COALESCE(NULLIF(r.app_version,''),'Unknown')
                        <> COALESCE(
                            NULLIF(r.source_prediction_version,''),
                            COALESCE(NULLIF(r.app_version,''),'Unknown')
                        )
              )
            ORDER BY r.created_at
        """, (target_version,)).fetchall()

        for race_key, plan_hash, app_ver, cover, model_rr in rows:
            try:
                tickets = con.execute("""
                    SELECT bet_type, probability, odds, role
                    FROM v187_mixed_plan_tickets
                    WHERE race_key=? AND plan_hash=?
                """, (race_key, plan_hash)).fetchall()

                if not tickets:
                    skipped += 1
                    continue

                rec_tickets = [
                    {
                        "type": str(bt or ""),
                        "probability": float(prob or 0.0),
                        "odds": float(od or 0.0),
                    }
                    for bt, prob, od, _role in tickets
                ]
                rec = _v305_live_recommendation({"tickets": rec_tickets})

                hole_count = sum(
                    1 for _bt, _prob, _od, role in tickets
                    if "中穴価値候補" in str(role or "")
                )
                adjusted = float(model_rr or 0.0) * factor
                cv = float(cover or 0.0)

                reasons = [
                    f"{target_version}現行推奨判定: "
                    + str(rec.get("reason") or "")
                ]

                con.execute("""
                    INSERT INTO v300_recommendation_audit
                    (
                        race_key,plan_hash,recommendation_label,
                        recommendation_score,adjusted_return_rate,
                        cover,max_ev,hole_count,reasons_json,
                        app_version,created_at
                    )
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(race_key,plan_hash) DO UPDATE SET
                        recommendation_label=excluded.recommendation_label,
                        recommendation_score=excluded.recommendation_score,
                        adjusted_return_rate=excluded.adjusted_return_rate,
                        cover=excluded.cover,
                        max_ev=excluded.max_ev,
                        hole_count=excluded.hole_count,
                        reasons_json=excluded.reasons_json,
                        app_version=excluded.app_version,
                        created_at=excluded.created_at
                """, (
                    str(race_key),
                    str(plan_hash),
                    str(rec.get("label") or "見送り"),
                    10 if rec.get("recommended")
                    else (5 if rec.get("candidate") else 0),
                    adjusted,
                    cv,
                    float(rec.get("max_ev", 0.0) or 0.0),
                    int(hole_count),
                    json.dumps(reasons, ensure_ascii=False),
                    str(app_ver or target_version),
                    _v228_now_jst_iso(),
                ))
                done += 1

            except Exception as exc:
                if len(errors) < 30:
                    errors.append(
                        f"{race_key}: {type(exc).__name__}: {exc}"
                    )

        con.commit()

    return {
        "done": done,
        "skipped": skipped,
        "errors": errors,
        "factor": factor,
        "target_version": target_version,
    }


def _v305_rec_only_hash(race_key: str, source_plan_hash: str) -> str:
    raw=f"Ver305-rec-only|{race_key}|{source_plan_hash}".encode("utf-8")
    return hashlib.sha1(raw).hexdigest()[:16]


def _v305_latest_ver304_plan(db_path: str, race_key: str) -> dict:
    try:
        with sqlite3.connect(str(db_path)) as con:
            con.row_factory=sqlite3.Row
            row=con.execute("""
                SELECT r.*
                  FROM v187_mixed_plan_runs r
                 WHERE r.race_key=?
                   AND COALESCE(r.app_version,'')=?
                   AND COALESCE(r.include_in_live_stats,1)=1
                   AND NOT (
                     COALESCE(r.plan_origin,'live')='current_version_restore'
                     AND COALESCE(NULLIF(r.app_version,''),'Unknown')
                         <> COALESCE(NULLIF(r.source_prediction_version,''),
                                     COALESCE(NULLIF(r.app_version,''),'Unknown'))
                   )
                 ORDER BY CASE WHEN COALESCE(r.plan_origin,'live')='live' THEN 0 ELSE 1 END,
                          r.created_at DESC
                 LIMIT 1
            """,(str(race_key or ''),_V305_REC_ONLY_BASE_VERSION)).fetchone()
        return dict(row) if row else {}
    except Exception:
        return {}


def _v305_clone_ver304_plan_as_rec_only(db_path: str, race_key: str) -> dict:
    """Ver304の最終買い目・実績をVer305比較用へ完全コピーし、推奨だけVer305判定する。"""
    src=_v305_latest_ver304_plan(db_path,race_key)
    if not src:
        return {"ok":False,"reason":"Ver304保存プランなし"}
    src_hash=str(src.get('plan_hash') or '')
    if not src_hash:
        return {"ok":False,"reason":"Ver304 plan_hashなし"}
    dst_hash=_v305_rec_only_hash(str(race_key),src_hash)
    now=_v228_now_jst_iso()

    try:
        _v187_ensure_mixed_learning_tables(db_path)
        with sqlite3.connect(str(db_path),timeout=30.0) as con:
            con.row_factory=sqlite3.Row
            con.execute("PRAGMA busy_timeout=30000")

            # 同じ過去レースで再計算されたVer305プランは比較から外す。
            # Ver305の定義を「Ver304土台＋推奨のみ変更」に固定するため。
            con.execute("""
                UPDATE v187_mixed_plan_runs
                   SET include_in_live_stats=0
                 WHERE race_key=? AND COALESCE(app_version,'')='Ver305'
                   AND COALESCE(plan_origin,'')<>?
            """,(str(race_key),_V305_REC_ONLY_ORIGIN))

            con.execute("""
                INSERT INTO v187_mixed_plan_runs
                (race_key,plan_hash,points,cost_yen,grade,cover,black,low,
                 hit_average_multiple,model_expected_multiple,model_return_rate,role_count,
                 created_at,app_version,logic_version,race_date,venue,race_no,starter_count,
                 plan_origin,source_prediction_version,include_in_live_stats)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)
                ON CONFLICT(race_key,plan_hash) DO UPDATE SET
                  points=excluded.points,cost_yen=excluded.cost_yen,grade=excluded.grade,
                  cover=excluded.cover,black=excluded.black,low=excluded.low,
                  hit_average_multiple=excluded.hit_average_multiple,
                  model_expected_multiple=excluded.model_expected_multiple,
                  model_return_rate=excluded.model_return_rate,role_count=excluded.role_count,
                  created_at=excluded.created_at,app_version='Ver305',
                  logic_version=excluded.logic_version,race_date=excluded.race_date,
                  venue=excluded.venue,race_no=excluded.race_no,starter_count=excluded.starter_count,
                  plan_origin=excluded.plan_origin,source_prediction_version='Ver304',
                  include_in_live_stats=1
            """,(
                str(race_key),dst_hash,int(src.get('points') or 0),int(src.get('cost_yen') or 0),
                src.get('grade'),src.get('cover'),src.get('black'),src.get('low'),
                src.get('hit_average_multiple'),src.get('model_expected_multiple'),src.get('model_return_rate'),
                src.get('role_count'),now,'Ver305','Ver304-base+Ver305-rec-only',
                src.get('race_date'),src.get('venue'),src.get('race_no'),src.get('starter_count'),
                _V305_REC_ONLY_ORIGIN,'Ver304'
            ))

            con.execute("DELETE FROM v187_mixed_plan_tickets WHERE race_key=? AND plan_hash=?",(race_key,dst_hash))
            con.execute("""
                INSERT INTO v187_mixed_plan_tickets
                (race_key,plan_hash,bet_type,combination,probability,odds,role)
                SELECT race_key,?,bet_type,combination,probability,odds,role
                  FROM v187_mixed_plan_tickets
                 WHERE race_key=? AND plan_hash=?
            """,(dst_hash,race_key,src_hash))

            # 実績も同じ買い目なのでそのままコピー。
            fb=con.execute("""
                SELECT * FROM v187_mixed_plan_feedback
                 WHERE race_key=? AND plan_hash=?
            """,(race_key,src_hash)).fetchone()
            if fb:
                con.execute("""
                    INSERT INTO v187_mixed_plan_feedback
                    (race_key,plan_hash,hit,black_hit,gami_hit,payout_yen,cost_yen,
                     realized_multiple,return_rate,winning_types,evaluated_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(race_key,plan_hash) DO UPDATE SET
                      hit=excluded.hit,black_hit=excluded.black_hit,gami_hit=excluded.gami_hit,
                      payout_yen=excluded.payout_yen,cost_yen=excluded.cost_yen,
                      realized_multiple=excluded.realized_multiple,return_rate=excluded.return_rate,
                      winning_types=excluded.winning_types,evaluated_at=excluded.evaluated_at
                """,(
                    race_key,dst_hash,fb['hit'],fb['black_hit'],fb['gami_hit'],fb['payout_yen'],fb['cost_yen'],
                    fb['realized_multiple'],fb['return_rate'],fb['winning_types'],fb['evaluated_at']
                ))

            con.execute("DELETE FROM v187_mixed_ticket_feedback WHERE race_key=? AND plan_hash=?",(race_key,dst_hash))
            con.execute("""
                INSERT INTO v187_mixed_ticket_feedback
                (race_key,plan_hash,bet_type,combination,hit,payout_yen)
                SELECT race_key,?,bet_type,combination,hit,payout_yen
                  FROM v187_mixed_ticket_feedback
                 WHERE race_key=? AND plan_hash=?
            """,(dst_hash,race_key,src_hash))

            trows=con.execute("""
                SELECT bet_type,probability,odds
                  FROM v187_mixed_plan_tickets
                 WHERE race_key=? AND plan_hash=?
            """,(race_key,dst_hash)).fetchall()
            rec=_v305_live_recommendation({"tickets":[
                {"type":str(r['bet_type'] or ''),"probability":float(r['probability'] or 0),"odds":float(r['odds'] or 0)}
                for r in trows
            ]})

            src_audit=con.execute("""
                SELECT adjusted_return_rate,cover,hole_count
                  FROM v300_recommendation_audit
                 WHERE race_key=? AND plan_hash=?
            """,(race_key,src_hash)).fetchone()
            adj=float(src_audit['adjusted_return_rate'] or 0) if src_audit else float(src.get('model_return_rate') or 0)
            cov=float(src_audit['cover'] or 0) if src_audit else float(src.get('cover') or 0)
            holes=int(src_audit['hole_count'] or 0) if src_audit else 0
            con.execute("""
                INSERT INTO v300_recommendation_audit
                (race_key,plan_hash,recommendation_label,recommendation_score,
                 adjusted_return_rate,cover,max_ev,hole_count,reasons_json,app_version,created_at)
                VALUES (?,?,?,?,?,?,?,?,?,?,?)
                ON CONFLICT(race_key,plan_hash) DO UPDATE SET
                  recommendation_label=excluded.recommendation_label,
                  recommendation_score=excluded.recommendation_score,
                  adjusted_return_rate=excluded.adjusted_return_rate,
                  cover=excluded.cover,max_ev=excluded.max_ev,hole_count=excluded.hole_count,
                  reasons_json=excluded.reasons_json,app_version='Ver305',created_at=excluded.created_at
            """,(
                race_key,dst_hash,str(rec.get('label') or '見送り'),
                10 if rec.get('recommended') else (5 if rec.get('candidate') else 0),
                adj,cov,float(rec.get('max_ev') or 0),holes,
                json.dumps(["Ver304買い目固定 / Ver305推奨のみ: "+str(rec.get('reason') or '')],ensure_ascii=False),
                'Ver305',now
            ))
            con.commit()

        return {
            "ok":True,"race_key":race_key,"source_plan_hash":src_hash,"plan_hash":dst_hash,
            "points":int(src.get('points') or 0),"cost_yen":int(src.get('cost_yen') or 0),
            "recommendation":rec,
            "source_version":"Ver304","app_version":"Ver305",
        }
    except Exception as exc:
        return {"ok":False,"reason":f"{type(exc).__name__}: {exc}"}


def _v305_clone_ver304_laps(db_path: str, race_key: str) -> dict:
    """比較用のVer305周回隊列をVer304保存値からコピー。"""
    m=re.match(r'^(\d{8})_(.+?)_(\d+)R$',str(race_key or ''))
    if not m:
        return {"ok":False,"reason":"race_key形式外"}
    d8,venue,rno=m.groups()
    date=f"{d8[:4]}-{d8[4:6]}-{d8[6:8]}"
    try:
        with sqlite3.connect(str(db_path),timeout=30.0) as con:
            rows=con.execute("""
                SELECT lap_no,predicted_order,support,is_backtest
                  FROM v252_lap_prediction_snapshots
                 WHERE substr(race_date,1,10)=? AND venue=?
                   AND REPLACE(CAST(race_no AS TEXT),'R','')=?
                   AND app_version='Ver304'
                 ORDER BY created_at DESC,snapshot_id DESC
            """,(date,venue,str(int(rno)))).fetchall()
            if not rows:
                return {"ok":False,"reason":"Ver304周回なし"}
            # 同じlapは最新1件。
            latest={}
            for lap,order,support,is_bt in rows:
                if int(lap) not in latest:
                    latest[int(lap)]=(order,support,is_bt)
            con.execute("""
                DELETE FROM v252_lap_prediction_snapshots
                 WHERE substr(race_date,1,10)=? AND venue=?
                   AND REPLACE(CAST(race_no AS TEXT),'R','')=?
                   AND app_version='Ver305'
            """,(date,venue,str(int(rno))))
            now=_v228_now_jst_iso()
            for lap,(order,support,is_bt) in sorted(latest.items()):
                con.execute("""
                    INSERT INTO v252_lap_prediction_snapshots
                    (race_date,venue,race_no,lap_no,predicted_order,support,app_version,is_backtest,created_at)
                    VALUES (?,?,?,?,?,?, 'Ver305', ?, ?)
                """,(date,venue,str(int(rno)),int(lap),str(order),support,int(is_bt or 0),now))
            con.commit()
        return {"ok":True,"saved_laps":len(latest)}
    except Exception as exc:
        return {"ok":False,"reason":f"{type(exc).__name__}: {exc}"}


def _v305_clone_ver304_history(db_path: str, race_key: str) -> dict:
    """Ver304の保存prediction_viewをVer305履歴として複製。再計算しない。"""
    try:
        _v231_ensure_prediction_history_table(db_path)
        with sqlite3.connect(str(db_path)) as con:
            row=con.execute("""
                SELECT history_id FROM v231_prediction_history
                 WHERE race_key=? AND app_version='Ver304'
                 ORDER BY history_id DESC LIMIT 1
            """,(race_key,)).fetchone()
        if not row:
            return {"ok":False,"reason":"Ver304予測履歴なし"}
        view,raw,venue_override,hm=_v231_load_prediction_history(db_path,int(row[0]))
        if not view:
            return {"ok":False,"reason":"Ver304 payload読込失敗"}
        cloned=dict(view)
        cloned['app_version']='Ver305'
        cloned['source_prediction_version']='Ver304'
        cloned['v305_recommendation_only']=True
        cloned['v305_base_version']='Ver304'
        cloned['prediction_time']=_v228_now_jst_iso()
        trials=int(cloned.get('trials') or hm.get('trials') or 20000)
        seed=int(cloned.get('seed') or hm.get('seed') or 20260719)
        cloned['settings_hash']=_v231_settings_hash(trials,seed,cloned.get('excluded') or [])
        hid=_v231_save_prediction_history(db_path,race_key,raw,venue_override,cloned,trials,seed)
        return {"ok":bool(hid),"history_id":int(hid or 0),"view":cloned}
    except Exception as exc:
        return {"ok":False,"reason":f"{type(exc).__name__}: {exc}"}


def _v305_repair_existing_rec_only_comparison(db_path: str) -> dict:
    """既に再計算してしまったVer305比較データを、Ver304固定土台へ安全に置換。"""
    out={"races":0,"plans":0,"laps":0,"errors":[]}
    try:
        with sqlite3.connect(str(db_path)) as con:
            keys=[str(r[0]) for r in con.execute("""
                SELECT DISTINCT race_key FROM v187_mixed_plan_runs
                 WHERE app_version='Ver304' AND COALESCE(include_in_live_stats,1)=1
            """).fetchall() if r and r[0]]
        for rk in keys:
            p=_v305_clone_ver304_plan_as_rec_only(db_path,rk)
            l=_v305_clone_ver304_laps(db_path,rk)
            if p.get('ok'): out['plans']+=1
            if l.get('ok'): out['laps']+=1
            if not p.get('ok') and len(out['errors'])<20: out['errors'].append(f"{rk} plan: {p.get('reason')}")
            out['races']+=1
        return out
    except Exception as exc:
        out['errors'].append(f"{type(exc).__name__}: {exc}")
        return out


def v184_eight_car_mixed_plan(bets: dict, trials: int, meta: dict, odds_maps: dict) -> dict:
    """6〜8車立て向けの役割分担型・回収率合成。

    車立てに応じて三連単中心度を変え、着順ずれ・3着抜け・1・2着逆転を補う。
    Ver191では単なる合成的中率ではなく、購入総額を超える黒字的中率を最優先する。
    低配当保険は、ほかの券種との同時的中を含めて黒字側を実際に増やす場合だけ採用する。
    """
    starter_count = engine.v102_starter_count_for_meta(meta, engine.DB_PATH)
    if not starter_count or int(starter_count) not in (6, 7, 8):
        return {"available": False, "reason": "回収率重視の合成推奨は6〜8車立てに対応しています。"}
    starter_count = int(starter_count)
    _race_date295=str((meta or {}).get("開催日") or (meta or {}).get("race_date") or "")[:10]
    _ev_calibration295=_v295_ev_calibration_table(str(engine.DB_PATH),_race_date295)
    if not isinstance(bets, dict) or int(trials or 0) <= 0:
        return {"available": False, "reason": "シミュレーション確率を取得できません。"}

    tri_counter = bets.get("三連単", {}) or {}
    if not tri_counter:
        return {"available": False, "reason": "三連単シミュレーションがありません。"}

    # Ver303: 当時まだ存在しなかった回収率実績を使わない。
    learning = _v187_learning_profile(engine.DB_PATH, _race_date295)
    if isinstance(learning,dict) and learning.get("enabled") is False and learning.get("reason"):
        try:
            st.caption("回収率学習: " + str(learning.get("reason")))
        except Exception:
            pass
    type_weights = learning.get("type_weights", {})

    # 車立て別に役割を変更。6車は三連単中心、7車は準中心、8車は複数券種の補完を厚くする。
    if starter_count == 6:
        type_specs = {
            "三連単": {"counter": "三連単", "odds": "3tan", "limit": 24, "cap": 10, "target_cover": None, "role": "主軸・着順まで一致"},
            "三連複": {"counter": "三連複", "odds": "3fuku", "limit": 999, "cap": 3, "target_cover": 86.0, "role": "着順ずれを少点数で補完"},
            "2連単": {"counter": "2車単", "odds": "2tansho", "limit": 999, "cap": 2, "target_cover": 84.0, "role": "3着抜けの限定保険"},
            "2連複": {"counter": "2車複", "odds": "2fuku", "limit": 999, "cap": 1, "target_cover": 82.0, "role": "逆転保険・黒字時のみ"},
        }
    elif starter_count == 7:
        type_specs = {
            "三連単": {"counter": "三連単", "odds": "3tan", "limit": 18, "cap": 9, "target_cover": None, "role": "本線・着順まで一致"},
            "三連複": {"counter": "三連複", "odds": "3fuku", "limit": 999, "cap": 5, "target_cover": 88.0, "role": "上位3車の着順ずれ保険"},
            "2連単": {"counter": "2車単", "odds": "2tansho", "limit": 999, "cap": 4, "target_cover": 88.0, "role": "1・2着一致／3着抜け保険"},
            "2連複": {"counter": "2車複", "odds": "2fuku", "limit": 999, "cap": 2, "target_cover": 86.0, "role": "1・2着逆転保険"},
        }
    else:
        type_specs = {
            "三連単": {"counter": "三連単", "odds": "3tan", "limit": 14, "cap": 9, "target_cover": None, "role": "本線・着順まで一致"},
            "三連複": {"counter": "三連複", "odds": "3fuku", "limit": 999, "cap": 7, "target_cover": 90.0, "role": "上位3車の着順ずれ保険"},
            "2連単": {"counter": "2車単", "odds": "2tansho", "limit": 999, "cap": 6, "target_cover": 90.0, "role": "1・2着一致／3着抜け保険"},
            "2連複": {"counter": "2車複", "odds": "2fuku", "limit": 999, "cap": 4, "target_cover": 88.0, "role": "1・2着逆転保険"},
        }

    def combo_text(value, unordered=False):
        vals = tuple(value) if isinstance(value, (tuple, list)) else (value,)
        nums = [str(int(v)) for v in vals]
        if unordered:
            nums = sorted(nums, key=int)
        return "-".join(nums)

    outcomes = []
    for combo, count in tri_counter.items():
        vals = tuple(int(v) for v in (tuple(combo) if isinstance(combo, (tuple, list)) else (combo,)))
        if len(vals) == 3:
            outcomes.append((vals, float(count) / max(int(trials), 1) * 100.0))
    if not outcomes:
        return {"available": False, "reason": "三連単結果空間を作れませんでした。"}

    def ticket_matches(ticket, outcome):
        a, b, c = outcome
        nums = tuple(int(x) for x in ticket["combo"].split("-"))
        if ticket["type"] == "三連単":
            return nums == (a, b, c)
        if ticket["type"] == "三連複":
            return tuple(sorted(nums)) == tuple(sorted((a, b, c)))
        if ticket["type"] == "2連単":
            return nums == (a, b)
        return tuple(sorted(nums)) == tuple(sorted((a, b)))

    candidates = []
    pool_summary = {}
    for label, spec in type_specs.items():
        counter = bets.get(spec["counter"], {}) or {}
        odds_map = odds_maps.get(spec["odds"], {}) or {}
        unordered = label in ("三連複", "2連複")
        ordered = sorted(counter.items(), key=lambda x: x[1], reverse=True)
        added = 0
        core_added = 0
        hole_added = 0
        cumulative = 0.0
        target_cover = spec.get("target_cover")
        for combo, count in ordered:
            probability = float(count) / max(int(trials), 1) * 100.0
            key = combo_text(combo, unordered=unordered)
            odds = float(odds_map.get(key, 0) or 0)
            # オッズが無い券は最終候補にできないため、候補母集団の累積にも含めない。
            if odds <= 0:
                continue
            learned_weight = float(type_weights.get(label, 1.0))
            _ev_prob295,_ev_ratio295,_ev_n295=_v295_ev_probability(
                probability,label,_ev_calibration295
            )
            _raw_ev299=(_ev_prob295/100.0)*odds
            _trust299,_trust_reason299=_v299_ev_trust(_raw_ev299,label,probability,odds)
            _effective_ev_prob299=(
                _ev_prob295*_trust299 if label=="三連単" else _ev_prob295
            )

            # Ver299: 三連単は確率上位limit点を越えても「中穴の価値候補」を最大6点だけ探索。
            # 極端な宝くじ領域ではなく、シミュレーションにも一定頻度で出る穴だけを対象にする。
            _is_hole299=(
                label=="三連単"
                and core_added >= int(spec["limit"])
                and hole_added < 6
                and 0.80 <= probability <= 6.00
                and odds >= 30.0
                and 0.72 <= _raw_ev299 <= 2.20
            )
            if label=="三連単" and core_added >= int(spec["limit"]) and not _is_hole299:
                continue

            ticket = {
                "type": label, "combo": key, "probability": probability,
                "ev_probability": _effective_ev_prob299,
                "ev_probability_before_v299": _ev_prob295,
                "ev_calibration_ratio": _ev_ratio295,
                "ev_calibration_samples": _ev_n295,
                "v299_ev_trust": _trust299,
                "v299_ev_trust_reason": _trust_reason299,
                "v299_raw_ev_multiple": _raw_ev299,
                "v299_hole_rescue": bool(_is_hole299),
                "odds": odds, "cap": int(spec["cap"]),
                "role": (spec["role"] + ("・中穴価値候補" if _is_hole299 else "")),
                "learned_weight": learned_weight,
            }
            matched = {i for i, (outcome, _) in enumerate(outcomes) if ticket_matches(ticket, outcome)}
            if not matched:
                continue
            ticket["matched"] = matched
            ticket["matched_probability"] = sum(outcomes[i][1] for i in matched)
            candidates.append(ticket)
            added += 1
            if _is_hole299:
                hole_added += 1
            else:
                core_added += 1
                cumulative += probability
            # 三連単は上位limit点を確保した後も、条件を満たす中穴だけ最大6点探索する。
            # その他券種は従来通り累積カバー到達で終了。
            if target_cover is not None and cumulative >= float(target_cover):
                break
            if target_cover is None and core_added >= int(spec["limit"]) and hole_added >= 6:
                break
        pool_summary[label] = {
            "points": added,
            "core_points": core_added,
            "hole_points": hole_added,
            "cover": cumulative,
            "target": target_cover,
        }

    # Ver201: 合成最適化で高確率本線まで削らないよう、券種ごとに保護候補を設定する。
    # 点数を固定せず、順位と確率の両方で判定する。保護候補は回収率判定には含めるが、
    # 最終構成の組み替え処理では削除対象にしない。
    protected_ids = set()
    protected_reasons = {}

    def protect_ticket(ticket, reason):
        key = (str(ticket.get("type")), str(ticket.get("combo")))
        protected_ids.add(key)
        protected_reasons.setdefault(key, []).append(str(reason))
        ticket["protected"] = True

    by_type = {}
    for ticket in candidates:
        by_type.setdefault(ticket["type"], []).append(ticket)
    for rows in by_type.values():
        rows.sort(key=lambda t: (float(t.get("probability", 0.0)), float(t.get("odds", 0.0))), reverse=True)

    # 三連単は全車立てで上位2点を必ず保護。上位と差が小さい候補も最大4点まで保護する。
    tri_rows_all = by_type.get("三連単", [])
    if tri_rows_all:
        tri_top = float(tri_rows_all[0].get("probability", 0.0))
        for idx, ticket in enumerate(tri_rows_all[:4]):
            prob = float(ticket.get("probability", 0.0))
            if idx < 2 or (prob >= 2.5 and prob >= tri_top * 0.55):
                protect_ticket(ticket, f"三連単{idx + 1}位・高確率本線")

    # 三連複は広い結果を1点で拾うため、上位2点と単独確率閾値以上を保護する。
    trio_threshold = {6: 12.0, 7: 10.0, 8: 8.0}[starter_count]
    for idx, ticket in enumerate(by_type.get("三連複", [])):
        prob = float(ticket.get("probability", 0.0))
        if idx < 2 or prob >= trio_threshold:
            protect_ticket(ticket, f"三連複{idx + 1}位・確率{prob:.2f}%")

    # 2連単は最上位を保護し、2位も首位との差が小さい場合は残す。
    exacta_rows = by_type.get("2連単", [])
    if exacta_rows:
        exacta_top = float(exacta_rows[0].get("probability", 0.0))
        for idx, ticket in enumerate(exacta_rows[:2]):
            prob = float(ticket.get("probability", 0.0))
            if idx == 0 or (prob >= 6.0 and prob >= exacta_top * 0.55):
                protect_ticket(ticket, f"2連単{idx + 1}位・高確率本線")

    # 2連複も広い結果を拾うため上位1点を保護。2位は確率が十分高い場合に保護する。
    quinella_threshold = {6: 15.0, 7: 12.0, 8: 10.0}[starter_count]
    for idx, ticket in enumerate(by_type.get("2連複", [])[:2]):
        prob = float(ticket.get("probability", 0.0))
        if idx == 0 or prob >= quinella_threshold:
            protect_ticket(ticket, f"2連複{idx + 1}位・確率{prob:.2f}%")

    protected_tickets = [
        ticket for ticket in candidates
        if (str(ticket.get("type")), str(ticket.get("combo"))) in protected_ids
    ]

    tri_candidates = [c for c in candidates if c["type"] == "三連単"]
    if len(tri_candidates) < 2:
        return {"available": False, "reason": "三連単上位候補のオッズが2点以上必要です。"}
    if len(candidates) < 6:
        return {"available": False, "reason": "合成判定に必要なオッズ候補が不足しています。4券種表を読み込んでください。"}

    def evaluate(plan):
        n = len(plan)
        cost = n * 100.0
        cover = black = low = expected_return = 0.0
        covered = set()
        hit_payout_rows = []
        for i, (outcome, probability) in enumerate(outcomes):
            payout = sum(t["odds"] * 100.0 for t in plan if i in t["matched"])
            if payout > 0:
                covered.add(i)
                cover += probability
                expected_return += probability / 100.0 * payout
                hit_payout_rows.append((float(payout), float(probability)))
                if payout >= cost:
                    black += probability
                else:
                    low += probability
        counts = {}
        for t in plan:
            counts[t["type"]] = counts.get(t["type"], 0) + 1
        diversity = len(counts)
        role_bonus = 0.0
        if counts.get("三連単", 0) >= 2:
            role_bonus += 0.5
        if counts.get("三連複", 0) >= 1:
            role_bonus += 0.8
        if counts.get("2連単", 0) >= 1:
            role_bonus += 0.8
        if counts.get("2連複", 0) >= 1:
            role_bonus += 0.35
        # 合成倍率は候補総額に対する払戻倍率。複数券種が同時的中する結果では払戻を合算する。
        if hit_payout_rows and cost > 0 and cover > 0:
            hit_average_payout = expected_return / (cover / 100.0)
            hit_average_multiple = hit_average_payout / cost
            hit_min_multiple = min(payout / cost for payout, _ in hit_payout_rows)
            hit_max_multiple = max(payout / cost for payout, _ in hit_payout_rows)
        else:
            hit_average_payout = 0.0
            hit_average_multiple = 0.0
            hit_min_multiple = 0.0
            hit_max_multiple = 0.0
        model_expected_multiple = expected_return / cost if cost else 0.0

        # Ver295: 期待値評価専用の校正済み期待払戻。
        # cover/black/lowは元の展開シミュレーション確率のまま維持する。
        ev_expected_return = sum(
            (float(t.get("ev_probability",t.get("probability",0.0)) or 0.0)/100.0)
            * float(t.get("odds",0.0) or 0.0) * 100.0
            for t in plan
        )
        ev_expected_multiple = ev_expected_return / cost if cost else 0.0
        ev_model_return_rate = ev_expected_multiple * 100.0

        # Ver191: 黒字的中率を主役にする。単なる的中範囲とガミ的中は強く評価しない。
        # 点数増加は購入総額そのものを押し上げるため、以前より明確に減点する。
        tri_share = (counts.get("三連単", 0) / max(1, n))
        field_bonus = (0.34 * tri_share if starter_count == 6 else (0.12 * tri_share if starter_count == 7 else 0.0))
        score = 0.48 * cover + 1.22 * black - 0.72 * low + 0.55 * role_bonus - 0.16 * n + field_bonus
        black_share_of_hits = black / cover * 100.0 if cover > 0 else 0.0
        gami_share_of_hits = low / cover * 100.0 if cover > 0 else 0.0
        return {
            "points": n, "cost": cost, "cover": cover, "black": black, "low": low,
            "miss": max(0.0, 100.0 - cover), "expected_return": expected_return,
            "model_return_rate": model_expected_multiple * 100.0,
            "model_expected_multiple": model_expected_multiple,
            "ev_expected_return": ev_expected_return,
            "ev_model_return_rate": ev_model_return_rate,
            "ev_expected_multiple": ev_expected_multiple,
            "hit_average_payout": hit_average_payout,
            "hit_average_multiple": hit_average_multiple,
            "hit_min_multiple": hit_min_multiple,
            "hit_max_multiple": hit_max_multiple,
            "black_share_of_hits": black_share_of_hits,
            "gami_share_of_hits": gami_share_of_hits,
            "score": score, "diversity": diversity, "counts": counts, "covered": covered,
        }

    def marginal(plan, cand):
        before = evaluate(plan)
        after = evaluate(plan + [cand])
        unique = cand["matched"] - before["covered"]
        unique_prob = sum(outcomes[i][1] for i in unique)
        return {
            "unique_prob": unique_prob,
            "cover_gain": after["cover"] - before["cover"],
            "black_gain": after["black"] - before["black"],
            "low_gain": after["low"] - before["low"],
            "score_gain": after["score"] - before["score"],
            "after": after,
        }

    # Ver189: 三連単も2点固定にせず、上位2〜6点を合成全体の土台として比較する。
    # 的中範囲を優先しつつ、追加による黒字側の改善、ガミ化、点数増を同時に評価する。
    tri_seed_options = []
    max_tri_seed = min(8 if starter_count == 6 else (7 if starter_count == 7 else 6), len(tri_candidates))
    for k in range(2, max_tri_seed + 1):
        seed_plan = tri_candidates[:k]
        seed_metrics = evaluate(seed_plan)
        # 三連単だけの土台でも黒字側を優先し、ガミ化と点数増を強めに抑える。
        seed_utility = (
            seed_metrics["cover"]
            + 0.52 * seed_metrics["black"]
            - 0.30 * seed_metrics["low"]
            - 0.16 * k
        )
        tri_seed_options.append((k, seed_plan, seed_metrics, seed_utility))

    best_seed_utility = max(x[3] for x in tri_seed_options)
    # 最高評価にほぼ並ぶなら少ない点数を優先し、無意味な膨張を避ける。
    seed_near = [x for x in tri_seed_options if x[3] >= best_seed_utility - 0.35]
    tri_seed_points, plan, tri_seed_metrics, _ = min(
        seed_near,
        key=lambda x: (x[0], -x[2]["black"], -x[2]["cover"], x[2]["low"]),
    )
    plan = list(plan)
    remaining = [c for c in candidates if c not in plan]

    # まず異なる外れ方を補う券種を1点ずつ検討する。
    for required_type in ("三連複", "2連単", "2連複"):
        choices = []
        for cand in remaining:
            if cand["type"] != required_type:
                continue
            mg = marginal(plan, cand)
            lw = float(cand.get("learned_weight", 1.0))
            new_cost = (len(plan) + 1) * 100.0
            solo_recovers = float(cand.get("odds", 0.0)) * 100.0 >= new_cost
            key = ((1.35 * mg["black_gain"] + 0.35 * mg["cover_gain"] - 0.75 * max(0.0, mg["low_gain"])) * lw,
                   int(solo_recovers), mg["unique_prob"] * lw, cand["probability"], cand["odds"])
            choices.append((key, cand, mg))
        if choices:
            key, cand, mg = max(choices, key=lambda x: x[0])
            # 役割券でも、ほとんど範囲が増えないものは無理に入れない。
            new_cost = (len(plan) + 1) * 100.0
            solo_recovers = float(cand.get("odds", 0.0)) * 100.0 >= new_cost
            min_black_gain = 0.18 if required_type == "2連複" else 0.28
            # 低配当保険は、単独回収できるか、同時的中込みで黒字確率を明確に増やす場合だけ採用。
            if mg["black_gain"] >= min_black_gain and (solo_recovers or mg["black_gain"] >= 0.65):
                plan.append(cand)
                remaining.remove(cand)

    snapshots = []
    # Ver305: 6点以上の構成だけを推奨判定の母集団として評価する。
    if len(plan) >= 6:
        snapshots.append((list(plan), evaluate(plan)))

    # 基本上限は12点。13〜14点目は黒字側が明確に伸びる場合だけ例外採用する。
    while len(plan) < 14 and remaining:
        counts = evaluate(plan)["counts"]
        best = None
        for cand in remaining:
            if counts.get(cand["type"], 0) >= cand["cap"]:
                continue
            mg = marginal(plan, cand)
            # 既存券と重複するだけの券より、新しい外れ方を拾う券を優先。
            lw = float(cand.get("learned_weight", 1.0))
            new_cost = (len(plan) + 1) * 100.0
            solo_recovers = float(cand.get("odds", 0.0)) * 100.0 >= new_cost
            complement = (1.50 * mg["black_gain"] + 0.28 * mg["cover_gain"]
                          - 0.78 * max(0.0, mg["low_gain"]) + 0.10 * mg["unique_prob"]) * lw
            if cand["type"] != "三連単" and counts.get(cand["type"], 0) == 0 and mg["black_gain"] > 0:
                complement += 0.18
            key = (complement, mg["black_gain"], int(solo_recovers), mg["score_gain"], cand["odds"])
            if best is None or key > best[0]:
                best = (key, cand, mg)
        if best is None:
            break
        _, cand, mg = best
        new_cost = (len(plan) + 1) * 100.0
        solo_recovers = float(cand.get("odds", 0.0)) * 100.0 >= new_cost
        # 黒字確率が増えない追加は不採用。低配当券は、強い黒字改善が無ければ止める。
        if mg["black_gain"] <= 0.0:
            break
        if not solo_recovers and mg["black_gain"] < 0.60:
            break
        if len(plan) >= 8 and mg["black_gain"] < 0.22:
            break
        if len(plan) >= 12 and (mg["black_gain"] < 0.80 or mg["after"]["ev_expected_multiple"] < evaluate(plan)["ev_expected_multiple"]):
            break
        plan.append(cand)
        remaining.remove(cand)
        if len(plan) >= 6:
            snapshots.append((list(plan), evaluate(plan)))

    if not snapshots:
        return {"available": False, "reason": "役割の異なる券を組み合わせた有効な構成を作れませんでした。"}

    # Ver191: 最高評価に近い構成から、黒字的中率と期待倍率を優先して選ぶ。
    best_score = max(m["score"] for _, m in snapshots)
    near = [(p, m) for p, m in snapshots if m["score"] >= best_score - 0.18]
    selected, metrics = max(
        near,
        key=lambda x: (x[1]["black"], x[1]["ev_expected_multiple"],
                       x[1]["black_share_of_hits"], x[1]["cover"], -x[1]["low"], -x[1]["points"]),
    )
    selected = list(selected)

    # Ver299: 「上位確率にいないから穴が候補にすら入らない」を防ぐ。
    # 候補母集団へ救済した中穴から、全体のEV指標を壊さず黒字率も大きく落とさないものを最大2点追加。
    v299_hole_notes = []
    for _ in range(2):
        _base299=evaluate(selected)
        _selected_ids299={(str(t.get("type")),str(t.get("combo"))) for t in selected}
        _best299=None
        for _cand299 in candidates:
            if not bool(_cand299.get("v299_hole_rescue")):
                continue
            _cid299=(str(_cand299.get("type")),str(_cand299.get("combo")))
            if _cid299 in _selected_ids299:
                continue
            _trial299=selected+[_cand299]
            _after299=evaluate(_trial299)
            _ret_delta299=float(_after299.get("ev_model_return_rate",0.0)-_base299.get("ev_model_return_rate",0.0))
            _black_delta299=float(_after299.get("black",0.0)-_base299.get("black",0.0))
            _cover_gain299=float(_after299.get("cover",0.0)-_base299.get("cover",0.0))
            _ev299=(float(_cand299.get("ev_probability",0.0))/100.0)*float(_cand299.get("odds",0.0))
            # 穴だからという理由だけで追加しない。校正後EVと合成指標の両方を通す。
            if _ev299 < 0.78 or _ret_delta299 < -1.5 or _black_delta299 < -0.45:
                continue
            _score299=2.0*_ret_delta299+1.4*_black_delta299+0.8*_cover_gain299+6.0*_ev299
            _key299=(_score299,_ev299,float(_cand299.get("odds",0.0)),float(_cand299.get("probability",0.0)))
            if _best299 is None or _key299>_best299[0]:
                _best299=(_key299,_cand299,_after299,_ret_delta299,_black_delta299,_cover_gain299,_ev299)
        if _best299 is None:
            break
        _,_cand299,_after299,_ret_delta299,_black_delta299,_cover_gain299,_ev299=_best299
        selected.append(_cand299)
        v299_hole_notes.append(
            f"中穴価値候補を追加：3連単 {_cand299.get('combo')} "
            f"（確率{float(_cand299.get('probability',0)):.2f}%・"
            f"オッズ{float(_cand299.get('odds',0)):.1f}倍・信頼補正EV{_ev299*100:.1f}%）"
        )

    # Ver201: 高確率本線を最終候補へ戻す。追加後の購入総額を含めて再評価し、
    # 回収率が悪ければ判定自体を下げるが、本線を黙って削ることはしない。
    protected_add_notes = []
    selected_ids = {(str(t.get("type")), str(t.get("combo"))) for t in selected}
    for ticket in protected_tickets:
        key = (str(ticket.get("type")), str(ticket.get("combo")))
        if key not in selected_ids:
            selected.append(ticket)
            selected_ids.add(key)
            protected_add_notes.append(
                f"{ticket['type']} {ticket['combo']}（モデル{float(ticket.get('probability',0.0)):.2f}%）を高確率本線として保護"
            )
    metrics = evaluate(selected)

    # Ver192: 単独ではガミになる2連系を、同じ展開に含まれる三連単へ分解して比較する。
    # 的中範囲を極端に捨てず、黒字的中率・期待倍率が改善する場合だけ差し替える。
    replacement_notes = list(v299_hole_notes)
    for _ in range(3):
        base_metrics = evaluate(selected)
        base_cost = float(base_metrics.get("cost", len(selected) * 100.0))
        best_swap = None
        for low_ticket in list(selected):
            if low_ticket.get("protected"):
                continue
            if low_ticket.get("type") not in ("2連単", "2連複"):
                continue
            # 現在の総点数に対し、この券だけの払戻では回収できないものを対象にする。
            if float(low_ticket.get("odds", 0.0)) * 100.0 >= base_cost:
                continue
            available_tri = [
                t for t in tri_candidates
                if t not in selected and t.get("matched")
                and t["matched"].issubset(low_ticket.get("matched", set()))
            ]
            available_tri.sort(
                key=lambda t: (float(t.get("probability", 0.0)), float(t.get("odds", 0.0))),
                reverse=True,
            )
            # 1〜4点への分解を比較。総点数は最大14点を維持する。
            max_add = min(5 if starter_count == 6 else 4, len(available_tri), (12 if starter_count == 6 else 15) - len(selected))
            for k in range(1, max_add + 1):
                tri_rows = available_tri[:k]
                trial_plan = [t for t in selected if t is not low_ticket] + tri_rows
                if len(trial_plan) > 14:
                    continue
                trial_metrics = evaluate(trial_plan)
                cover_loss = base_metrics["cover"] - trial_metrics["cover"]
                black_gain = trial_metrics["black"] - base_metrics["black"]
                expected_gain = (trial_metrics["ev_expected_multiple"]
                                 - base_metrics["ev_expected_multiple"])
                gami_drop = base_metrics["low"] - trial_metrics["low"]
                # 的中重視なので、カバー低下は原則2.5pt以内。大幅な黒字改善時のみ4ptまで許容。
                allowed_loss = 4.0 if black_gain >= 1.20 else 2.5
                if cover_loss > allowed_loss:
                    continue
                if black_gain <= 0.05:
                    continue
                if expected_gain < -0.03:
                    continue
                utility = (1.55 * black_gain + 0.55 * max(0.0, gami_drop)
                           + 8.0 * expected_gain - 0.28 * max(0.0, cover_loss)
                           - 0.06 * max(0, len(trial_plan) - len(selected)))
                key = (utility, black_gain, gami_drop, expected_gain, -cover_loss, -len(trial_plan))
                if best_swap is None or key > best_swap[0]:
                    best_swap = (key, low_ticket, tri_rows, trial_plan, trial_metrics, cover_loss)
        if best_swap is None or best_swap[0][0] <= 0.0:
            break
        _, low_ticket, tri_rows, selected, metrics, cover_loss = best_swap
        replacement_notes.append(
            f"{low_ticket['type']} {low_ticket['combo']}（{float(low_ticket.get('odds',0)):.1f}倍）を外し、"
            f"三連単 {', '.join(t['combo'] for t in tri_rows)} へ分解。"
            f"黒字的中率 {base_metrics['black']:.2f}%→{metrics['black']:.2f}%、"
            f"カバー率 {base_metrics['cover']:.2f}%→{metrics['cover']:.2f}%"
        )

    # Ver194: 同じ2車について、2連複・片側2連単・表裏2連単・重ね買いを全比較する。
    # 例: 2連複6-8 + 高配当側の2連単6-8 は、同じ2点の表裏2連単より
    # 両方向の払戻が高くなる場合がある。固定パターンではなく合成全体を再評価して採用する。
    pair_mix_notes = []
    for _ in range(4):
        base_metrics = evaluate(selected)
        exacta_by_combo = {
            str(t.get("combo")): t for t in candidates
            if t.get("type") == "2連単" and float(t.get("odds", 0.0)) > 0
        }
        best_pair_swap = None

        for quinella_ticket in list(selected):
            if quinella_ticket.get("type") != "2連複":
                continue
            if quinella_ticket.get("protected"):
                continue
            try:
                qa, qb = [int(x) for x in str(quinella_ticket.get("combo", "")).split("-")[:2]]
            except Exception:
                continue

            forward = exacta_by_combo.get(f"{qa}-{qb}")
            reverse = exacta_by_combo.get(f"{qb}-{qa}")
            pair_set = {qa, qb}

            # 現在選択中の同一ペア券を一度まとめて外し、候補構成を公平に比較する。
            related = []
            fixed_plan = []
            for ticket in selected:
                is_related = ticket is quinella_ticket
                if ticket.get("type") == "2連単":
                    try:
                        ea, eb = [int(x) for x in str(ticket.get("combo", "")).split("-")[:2]]
                        is_related = is_related or ({ea, eb} == pair_set)
                    except Exception:
                        pass
                if is_related:
                    related.append(ticket)
                else:
                    fixed_plan.append(ticket)

            option_rows = [("2連複のみ", [quinella_ticket])]
            if forward is not None:
                option_rows.extend([
                    (f"2連単{forward['combo']}のみ", [forward]),
                    (f"2連複＋2連単{forward['combo']}", [quinella_ticket, forward]),
                ])
            if reverse is not None:
                option_rows.extend([
                    (f"2連単{reverse['combo']}のみ", [reverse]),
                    (f"2連複＋2連単{reverse['combo']}", [quinella_ticket, reverse]),
                ])
            if forward is not None and reverse is not None:
                option_rows.extend([
                    ("2連単表裏", [forward, reverse]),
                    ("2連複＋2連単表裏", [quinella_ticket, forward, reverse]),
                ])

            # 同一ペア内に保護された2連単がある場合、その本線を外す比較は行わない。
            if any(t.get("protected") for t in related):
                continue

            current_ids = {(t.get("type"), t.get("combo")) for t in related}
            current_name = "現在構成"
            pair_base_metrics = evaluate(selected)
            current_score = (
                1.70 * pair_base_metrics["black"]
                + 0.18 * pair_base_metrics["cover"]
                - 0.88 * pair_base_metrics["low"]
                + 10.0 * pair_base_metrics["model_expected_multiple"]
                + 2.2 * pair_base_metrics["hit_average_multiple"]
                - 0.12 * len(selected)
            )

            seen_options = set()
            for option_name, option_tickets in option_rows:
                ids = tuple(sorted((t.get("type"), t.get("combo")) for t in option_tickets))
                if ids in seen_options:
                    continue
                seen_options.add(ids)
                trial_plan = list(fixed_plan)
                for ticket in option_tickets:
                    if ticket not in trial_plan:
                        trial_plan.append(ticket)
                if len(trial_plan) > 14:
                    continue

                trial_metrics = evaluate(trial_plan)
                cover_loss = pair_base_metrics["cover"] - trial_metrics["cover"]
                black_gain = trial_metrics["black"] - pair_base_metrics["black"]
                gami_drop = pair_base_metrics["low"] - trial_metrics["low"]
                expected_gain = (trial_metrics["model_expected_multiple"]
                                 - pair_base_metrics["model_expected_multiple"])
                avg_gain = (trial_metrics["hit_average_multiple"]
                            - pair_base_metrics["hit_average_multiple"])
                point_gain = len(trial_plan) - len(selected)

                # 的中重視なので、両方向を拾う構成同士ではカバーをほぼ維持する。
                # 片方向のみへ絞る場合は、黒字側の改善が大きい場合だけ最大2.0ptまで許容する。
                allowed_cover_loss = 2.0 if black_gain >= 0.80 else 0.40
                if cover_loss > allowed_cover_loss:
                    continue
                if expected_gain < -0.025:
                    continue
                if avg_gain < -0.06:
                    continue

                score = (
                    1.70 * trial_metrics["black"]
                    + 0.18 * trial_metrics["cover"]
                    - 0.88 * trial_metrics["low"]
                    + 10.0 * trial_metrics["model_expected_multiple"]
                    + 2.2 * trial_metrics["hit_average_multiple"]
                    - 0.12 * len(trial_plan)
                )
                gain = score - current_score
                # 同点付近なら、点数が少なくガミ率が低い構成を優先する。
                key = (
                    gain,
                    black_gain,
                    gami_drop,
                    expected_gain,
                    avg_gain,
                    -max(0.0, cover_loss),
                    -len(trial_plan),
                )
                if best_pair_swap is None or key > best_pair_swap[0]:
                    best_pair_swap = (
                        key, quinella_ticket, related, option_name, option_tickets,
                        trial_plan, trial_metrics, pair_base_metrics
                    )

        if best_pair_swap is None or best_pair_swap[0][0] <= 0.015:
            break

        (_, quinella_ticket, old_tickets, option_name, option_tickets,
         selected, metrics, before_metrics) = best_pair_swap

        old_desc = "・".join(
            f"{t['type']} {t['combo']}（{float(t.get('odds',0)):.1f}倍）" for t in old_tickets
        )
        new_desc = "・".join(
            f"{t['type']} {t['combo']}（{float(t.get('odds',0)):.1f}倍）" for t in option_tickets
        )
        pair_mix_notes.append(
            f"同一ペア構成を全比較し、{old_desc} から {new_desc} へ変更（{option_name}）。"
            f"黒字的中率 {before_metrics['black']:.2f}%→{metrics['black']:.2f}%、"
            f"ガミ率 {before_metrics['low']:.2f}%→{metrics['low']:.2f}%、"
            f"合成倍率 {before_metrics['hit_average_multiple']:.2f}倍→{metrics['hit_average_multiple']:.2f}倍"
        )

    replacement_notes.extend(pair_mix_notes)

    # Ver212: 長期回収率重視の最低基準。
    # 本線保護の有無にかかわらず、極端な低配当かつ単体期待値100%未満の券は
    # 「的中数を増やすだけの保険」として最終構成から除外する。
    low_odds_floor_notes = []
    for _ in range(8):
        base = evaluate(selected)
        forced = None
        for ticket in list(selected):
            if len(selected) <= 2:
                break
            odds = float(ticket.get("odds", 0.0) or 0.0)
            prob = float(ticket.get("probability", 0.0) or 0.0)
            standalone_ev = (float(ticket.get("ev_probability",prob) or prob) / 100.0) * odds
            payout_ratio = (odds * 100.0 / float(base.get("cost", 1.0))) if base.get("cost") else 0.0

            # 2.0倍以下はEV100%未満なら無条件除外。
            # それ以上でも、総額の25%未満しか戻らずEV95%未満なら除外する。
            too_low = (odds <= 2.0 and standalone_ev < 1.0)
            deep_low_return = (payout_ratio < 0.25 and standalone_ev < 0.95)
            if not (too_low or deep_low_return):
                continue

            trial = [t for t in selected if t is not ticket]
            after = evaluate(trial)
            key = (
                base["model_return_rate"] - after["model_return_rate"],
                odds, standalone_ev
            )
            if forced is None or key < forced[0]:
                forced = (key, ticket, trial, after, standalone_ev, payout_ratio)

        if forced is None:
            break
        _, ticket, selected, after, standalone_ev, payout_ratio = forced
        ticket["protected"] = False
        low_odds_floor_notes.append(
            f"{ticket['type']} {ticket['combo']}（{float(ticket.get('odds',0)):.1f}倍）を長期回収率基準で除外。"
            f"単体期待値{standalone_ev*100:.1f}%・単独払戻は候補総額の{payout_ratio*100:.1f}%"
        )

    # Ver204: 券種をまたいだ重複と深いガミ券を、最終総額ベースで再評価する。
    # 高確率本線でも、追加的中範囲が小さく、単体期待値が低く、除外後に
    # 黒字確率・ガミ率・参考回収率が改善する場合は保護を解除して除外する。
    gami_prune_notes = []
    for _ in range(8):
        before = evaluate(selected)
        best_remove = None
        for ticket in list(selected):
            trial_plan = [t for t in selected if t is not ticket]
            if len(trial_plan) < 4:
                continue
            after = evaluate(trial_plan)

            other_matched = set()
            for other in trial_plan:
                other_matched.update(other.get("matched", set()))
            unique_indexes = set(ticket.get("matched", set())) - other_matched
            unique_prob = sum(outcomes[i][1] for i in unique_indexes)

            odds = float(ticket.get("odds", 0.0) or 0.0)
            prob = float(ticket.get("probability", 0.0) or 0.0)
            standalone_ev = (float(ticket.get("ev_probability",prob) or prob) / 100.0) * odds
            payout_ratio = (odds * 100.0 / float(before.get("cost", 1.0))) if before.get("cost") else 0.0
            cover_loss = float(before["cover"] - after["cover"])
            black_delta = float(after["black"] - before["black"])
            gami_drop = float(before["low"] - after["low"])
            return_gain = float(after["model_return_rate"] - before["model_return_rate"])

            # Ver220: 「ほかの券が何か当たる」だけではカバー扱いにしない。
            # 券を外したことで、黒字→ガミ／黒字→外れ／的中→外れになる確率を
            # 各シミュレーション着順の払戻額から直接計算する。
            before_cost = len(selected) * 100.0
            after_cost = len(trial_plan) * 100.0
            black_to_gami = 0.0
            black_to_miss = 0.0
            hit_to_miss = 0.0
            payout_loss_expected = 0.0
            for i, (_, outcome_prob) in enumerate(outcomes):
                before_payout = sum(
                    float(t.get("odds", 0.0) or 0.0) * 100.0
                    for t in selected if i in t.get("matched", set())
                )
                after_payout = sum(
                    float(t.get("odds", 0.0) or 0.0) * 100.0
                    for t in trial_plan if i in t.get("matched", set())
                )
                outcome_prob = float(outcome_prob)
                payout_loss_expected += (outcome_prob / 100.0) * max(0.0, before_payout - after_payout)
                if before_payout > 0 and after_payout <= 0:
                    hit_to_miss += outcome_prob
                if before_payout >= before_cost:
                    if after_payout <= 0:
                        black_to_miss += outcome_prob
                    elif after_payout < after_cost:
                        black_to_gami += outcome_prob

            black_result_loss = black_to_gami + black_to_miss
            is_trifecta = str(ticket.get("type", "")).replace("三", "3") == "3連単"
            # 上位10点などの固定順位では守らない。実際に失う黒字結果・固有的中が
            # 十分大きい券だけを、チーム貢献として保護する。
            contribution_protected = is_trifecta and (
                black_result_loss >= 0.75
                or hit_to_miss >= 1.25
                or (prob >= 2.0 and payout_ratio >= 1.0)
            )

            deep_gami = payout_ratio < 0.70
            low_ev_overlap = unique_prob <= 6.0 and standalone_ev < 0.95
            pure_overlap = unique_prob <= 0.01 and standalone_ev < 0.75
            total_gami_cleanup = (
                payout_ratio < 1.0 and gami_drop >= 2.0 and return_gain >= 1.0
                and cover_loss <= 3.5 and black_delta >= -0.5
            )
            removable = (
                (deep_gami and low_ev_overlap and return_gain >= 1.0 and black_delta >= -2.5)
                or (pure_overlap and return_gain >= 1.0 and black_delta >= -2.5)
                or total_gami_cleanup
            )
            if not removable:
                continue

            # 黒字結果や固有的中を実際に失う3連単は、平均回収率だけを理由に切らない。
            if contribution_protected:
                continue

            # 保護券は通常残す。ただし深いガミかつ低期待値で、追加範囲も小さい場合だけ解除する。
            if ticket.get("protected") and not (deep_gami and low_ev_overlap):
                continue

            score = (
                return_gain + 1.50 * gami_drop + 0.80 * black_delta
                - 0.25 * max(0.0, cover_loss) + 20.0 * max(0.0, 1.0 - payout_ratio)
            )
            key = (score, return_gain, gami_drop, black_delta, -cover_loss, -unique_prob)
            if best_remove is None or key > best_remove[0]:
                best_remove = (
                    key, ticket, trial_plan, after, unique_prob, standalone_ev,
                    payout_ratio, cover_loss, black_delta, gami_drop, return_gain
                )

        if best_remove is None:
            break

        (_, ticket, selected, after, unique_prob, standalone_ev, payout_ratio,
         cover_loss, black_delta, gami_drop, return_gain) = best_remove
        ticket["protected"] = False
        gami_prune_notes.append(
            f"{ticket['type']} {ticket['combo']}（{float(ticket.get('odds',0)):.1f}倍）を除外。"
            f"固有的中{hit_to_miss:.2f}%・黒字→ガミ{black_to_gami:.2f}%・"
            f"黒字→外れ{black_to_miss:.2f}%・単体期待値{standalone_ev*100:.1f}%・"
            f"参考回収率{before['model_return_rate']:.1f}%→{after['model_return_rate']:.1f}%・"
            f"ガミ率{before['low']:.2f}%→{after['low']:.2f}%"
        )

    # Ver212: 堅いレースでは、通常合成の期待値比較だけで見送らない。
    # 最有力の1・2着ペアを固定し、3着候補ごとに表裏を揃えた3連単2〜4点を優先する。
    hard_race_info = {"enabled": False}
    try:
        win_share = {}
        pair_share = {}
        for outcome, probability in outcomes:
            a, b, _ = outcome
            win_share[a] = win_share.get(a, 0.0) + float(probability)
            pair = tuple(sorted((a, b)))
            pair_share[pair] = pair_share.get(pair, 0.0) + float(probability)
        top_wins = sorted(win_share.items(), key=lambda x: x[1], reverse=True)
        top_pair, top_pair_prob = max(pair_share.items(), key=lambda x: x[1]) if pair_share else ((0, 0), 0.0)
        top2_win_share = sum(v for _, v in top_wins[:2])
        top_tri_prob = max((float(t.get("probability", 0.0)) for t in tri_candidates), default=0.0)
        hard_score = 0
        hard_score += int(top2_win_share >= 72.0)
        hard_score += int(float(top_pair_prob) >= 38.0)
        hard_score += int(top_tri_prob >= 5.0)
        top_tri_rows = sorted(tri_candidates, key=lambda t: float(t.get("probability", 0.0)), reverse=True)[:10]
        low_odds_count = sum(1 for t in top_tri_rows[:5] if 0 < float(t.get("odds", 0.0)) <= 25.0)
        hard_score += int(low_odds_count >= 3)

        if hard_score >= 3 and len(top_tri_rows) >= 2:
            pair_set = set(int(x) for x in top_pair)
            pair_rows = []
            third_scores = {}
            for t in tri_candidates:
                try:
                    a, b, c = (int(x) for x in str(t.get("combo", "")).split("-"))
                except Exception:
                    continue
                if {a, b} == pair_set and c not in pair_set:
                    pair_rows.append(t)
                    third_scores[c] = third_scores.get(c, 0.0) + float(t.get("probability", 0.0))

            third_order = [c for c, _ in sorted(third_scores.items(), key=lambda x: x[1], reverse=True)]
            structured = []
            used = set()
            for c in third_order[:2]:
                rows = [t for t in pair_rows if str(t.get("combo", "")).endswith(f"-{c}")]
                rows.sort(key=lambda t: float(t.get("probability", 0.0)), reverse=True)
                # 最有力3着候補は中心ペアの表裏を両方残す。
                for t in rows[:2]:
                    key = (t.get("type"), t.get("combo"))
                    if key not in used:
                        structured.append(t); used.add(key)

            # ペア固定だけで不足する場合は、全体上位から補完する。
            for t in top_tri_rows:
                if len(structured) >= 4:
                    break
                key = (t.get("type"), t.get("combo"))
                if key not in used:
                    structured.append(t); used.add(key)

            compact_options = []
            min_k = 2 if len(structured) >= 2 else 1
            for k in range(min_k, min(4, len(structured)) + 1):
                compact = structured[:k]
                compact_metrics = evaluate(compact)
                # どの1点が当たっても購入総額以上になりやすい構成を優先。
                break_even_ok = all(float(t.get("odds", 0.0)) >= float(k) for t in compact)
                utility = (
                    2.10 * compact_metrics["black"]
                    + 10.0 * compact_metrics["ev_expected_multiple"]
                    + 0.18 * compact_metrics["cover"]
                    - 0.75 * compact_metrics["low"]
                    - 0.35 * k
                    + (12.0 if break_even_ok else -12.0)
                )
                compact_options.append((utility, compact, compact_metrics, break_even_ok))

            _, compact_plan, compact_metrics, break_even_ok = max(
                compact_options,
                key=lambda x: (x[3], x[0], x[2]["black"], x[2]["ev_expected_multiple"], -x[2]["points"]),
            )
            normal_metrics = evaluate(selected)

            # 強い堅い判定では、ガミ保険を多数残す通常構成より中心ペア固定を優先。
            # ただし全点が単独ガミになる構成、または参考回収率が著しく低い構成は採用しない。
            compact_is_better = bool(
                break_even_ok
                and compact_metrics["points"] <= 4
                and compact_metrics["model_return_rate"] >= 95.0
                and compact_metrics["low"] <= normal_metrics["low"]
            )
            hard_race_info = {
                "enabled": True,
                "applied": compact_is_better,
                "score": hard_score,
                "top_pair": top_pair,
                "top_pair_prob": float(top_pair_prob),
                "top2_win_share": float(top2_win_share),
                "normal_points": int(normal_metrics.get("points", len(selected))),
                "compact_points": int(compact_metrics.get("points", len(compact_plan))),
                "normal_return": float(normal_metrics.get("model_return_rate", 0.0)),
                "compact_return": float(compact_metrics.get("model_return_rate", 0.0)),
                "normal_black": float(normal_metrics.get("black", 0.0)),
                "compact_black": float(compact_metrics.get("black", 0.0)),
                "normal_low": float(normal_metrics.get("low", 0.0)),
                "compact_low": float(compact_metrics.get("low", 0.0)),
                "break_even_ok": bool(break_even_ok),
            }

            # Ver301監査: 堅いレースで3点固定が本当に有利か、
            # 同じ三連単候補から 3/6/8/10/16点へ広げた場合を表示用に比較する。
            # ここでは買い目自体は変更しない。
            try:
                _audit_order301=[]
                _audit_seen301=set()

                # まず実際のコンパクト案を優先して並べる。
                for _t301 in list(compact_plan):
                    _k301=(str(_t301.get("type","")),str(_t301.get("combo","")))
                    if _k301 not in _audit_seen301:
                        _audit_order301.append(_t301)
                        _audit_seen301.add(_k301)

                # 残りは「校正後EV・モデル確率・オッズ」の順で候補を広げる。
                _rest301=[]
                for _t301 in tri_candidates:
                    _k301=(str(_t301.get("type","")),str(_t301.get("combo","")))
                    if _k301 in _audit_seen301:
                        continue
                    _p301=float(_t301.get("probability",0.0) or 0.0)
                    _ep301=float(_t301.get("ev_probability",_p301) or _p301)
                    _od301=float(_t301.get("odds",0.0) or 0.0)
                    _ev301=(_ep301/100.0)*_od301
                    _rest301.append((_ev301,_p301,_od301,_t301))

                for _,_,_,_t301 in sorted(_rest301,key=lambda x:(x[0],x[1],x[2]),reverse=True):
                    _k301=(str(_t301.get("type","")),str(_t301.get("combo","")))
                    if _k301 not in _audit_seen301:
                        _audit_order301.append(_t301)
                        _audit_seen301.add(_k301)

                _rows301=[]
                for _target301 in (3,6,8,10,16):
                    _plan301=_audit_order301[:min(_target301,len(_audit_order301))]
                    if not _plan301:
                        continue
                    _m301=evaluate(_plan301)
                    _rows301.append({
                        "points":int(len(_plan301)),
                        "cover":float(_m301.get("cover",0.0)),
                        "black":float(_m301.get("black",0.0)),
                        "low":float(_m301.get("low",0.0)),
                        "model_return_rate":float(_m301.get("model_return_rate",0.0)),
                        "ev_model_return_rate":float(_m301.get("ev_model_return_rate",_m301.get("model_return_rate",0.0))),
                        "hit_average_multiple":float(_m301.get("hit_average_multiple",0.0)),
                        "min_odds":min((float(_t.get("odds",0.0) or 0.0) for _t in _plan301),default=0.0),
                        "max_odds":max((float(_t.get("odds",0.0) or 0.0) for _t in _plan301),default=0.0),
                        "combos":[str(_t.get("combo","")) for _t in _plan301],
                    })
                hard_race_info["expand_audit"]=_rows301
            except Exception:
                hard_race_info["expand_audit"]=[]
            if compact_is_better:
                selected = list(compact_plan)
                metrics = compact_metrics
                replacement_notes.append(
                    f"堅いレース判定により通常{normal_metrics['points']}点から、中心ペア"
                    f"{top_pair[0]}・{top_pair[1]}固定の3連単{compact_metrics['points']}点へ絞り込み。"
                    f"上位2車勝率合計{top2_win_share:.1f}%・中心ペア確率{top_pair_prob:.1f}%・"
                    f"ガミ率{normal_metrics['low']:.2f}%→{compact_metrics['low']:.2f}%"
                )
    except Exception:
        hard_race_info = {"enabled": False}


    # Ver245: 同じ1着・同じ3車で2着と3着だけが入れ替わる三連単をセット比較する。
    # 片側だけ残すことで取りこぼしやすい展開を守るが、何でも折り返して点数を膨らませない。
    # 確率差が小さく、追加後も単独ガミにならず、全体指標を大きく悪化させない場合だけ最大2点追加。
    v245_pair_protection_notes = []
    try:
        tri_by_combo = {
            str(t.get("combo", "")): t for t in tri_candidates
            if str(t.get("type", "")).replace("三", "3") == "3連単"
        }
        selected_ids_now = {(str(t.get("type", "")), str(t.get("combo", ""))) for t in selected}
        pair_candidates = []
        base_pair_metrics = evaluate(selected)
        for ticket in list(selected):
            if str(ticket.get("type", "")).replace("三", "3") != "3連単":
                continue
            try:
                a, b, c = (int(x) for x in str(ticket.get("combo", "")).split("-"))
            except Exception:
                continue
            reverse_combo = f"{a}-{c}-{b}"
            reverse_ticket = tri_by_combo.get(reverse_combo)
            if reverse_ticket is None or (str(reverse_ticket.get("type", "")), reverse_combo) in selected_ids_now:
                continue
            p1 = float(ticket.get("probability", 0.0) or 0.0)
            p2 = float(reverse_ticket.get("probability", 0.0) or 0.0)
            odds2 = float(reverse_ticket.get("odds", 0.0) or 0.0)
            if p1 <= 0 or p2 < 0.80 or p2 < p1 * 0.62:
                continue
            new_points = len(selected) + 1
            standalone_ev = (float(reverse_ticket.get("ev_probability",p2) or p2) / 100.0) * odds2
            if odds2 < float(new_points) or standalone_ev < 0.72:
                continue
            trial_plan = list(selected) + [reverse_ticket]
            after = evaluate(trial_plan)
            return_drop = float(base_pair_metrics.get("ev_model_return_rate", 0.0) - after.get("ev_model_return_rate", 0.0))
            black_drop = float(base_pair_metrics.get("black", 0.0) - after.get("black", 0.0))
            cover_gain = float(after.get("cover", 0.0) - base_pair_metrics.get("cover", 0.0))
            low_gain = float(after.get("low", 0.0) - base_pair_metrics.get("low", 0.0))
            if return_drop > 5.0 or black_drop > 0.55 or low_gain > 1.25:
                continue
            score = 1.25 * cover_gain + 0.60 * p2 + 8.0 * standalone_ev - 0.55 * return_drop - 0.40 * low_gain
            pair_candidates.append((score, ticket, reverse_ticket, after, return_drop, black_drop, cover_gain, standalone_ev))

        for _, source_ticket, reverse_ticket, after, return_drop, black_drop, cover_gain, standalone_ev in sorted(pair_candidates, key=lambda x: x[0], reverse=True)[:2]:
            key = (str(reverse_ticket.get("type", "")), str(reverse_ticket.get("combo", "")))
            if key in {(str(t.get("type", "")), str(t.get("combo", ""))) for t in selected}:
                continue
            selected.append(reverse_ticket)
            base_pair_metrics = evaluate(selected)
            reverse_ticket["protected"] = True
            v245_pair_protection_notes.append(
                f"展開入替ペアを保護：{source_ticket.get('combo')} に対し {reverse_ticket.get('combo')} を追加。"
                f"確率{float(reverse_ticket.get('probability',0)):.2f}%・オッズ{float(reverse_ticket.get('odds',0)):.1f}倍・"
                f"単体期待値{standalone_ev*100:.1f}%・追加カバー+{cover_gain:.2f}pt"
            )
        if v245_pair_protection_notes:
            metrics = evaluate(selected)
            replacement_notes.extend(v245_pair_protection_notes)
    except Exception:
        v245_pair_protection_notes = []

    # Ver206: 低評価でも3着へ残る選手を、無条件で本線へ追加しない。
    # 既存の1・2着軸、3連複、別の3連単から自然に派生し、オッズ込みの期待値がある3連単だけを
    # 「余裕がある場合の追加候補」または「低効率券との入れ替え候補」として提示する。
    base_for_residual = evaluate(selected)
    selected_ids = {(t.get("type"), t.get("combo")) for t in selected}
    # Ver213: 回収率重視の最終構成では「その券だけが的中した場合に赤字」の券を残さない。
    # 券を1点ずつ外すたびに購入総額が下がるため、最終総額に対して再判定を繰り返す。
    # 長期回収率を優先し、本線保護よりも単独黒字条件を優先する。
    solo_gami_exclusion_notes = []
    for _ in range(20):
        current = evaluate(selected)
        current_cost = float(current.get("cost", 0.0) or 0.0)
        if current_cost <= 0 or len(selected) <= 1:
            break
        solo_gami = []
        for ticket in selected:
            odds = float(ticket.get("odds", 0.0) or 0.0)
            payout = odds * 100.0
            if payout + 1e-9 >= current_cost:
                continue
            prob = float(ticket.get("probability", 0.0) or 0.0)
            ev = (float(ticket.get("ev_probability",prob) or prob) / 100.0) * odds
            trial = [t for t in selected if t is not ticket]
            after = evaluate(trial)
            return_gain = float(after.get("model_return_rate", 0.0) - current.get("model_return_rate", 0.0))
            black_delta = float(after.get("black", 0.0) - current.get("black", 0.0))
            cover_loss = float(current.get("cover", 0.0) - after.get("cover", 0.0))
            # 低EV、回収率改善、黒字率を傷めにくい券から除外。
            key = (
                1 if ev < 1.0 else 0,
                return_gain,
                black_delta,
                -cover_loss,
                current_cost - payout,
                -ev,
            )
            solo_gami.append((key, ticket, trial, after, payout, ev))
        if not solo_gami:
            break
        solo_gami.sort(key=lambda x: x[0], reverse=True)
        _, ticket, selected, after, payout, ev = solo_gami[0]
        ticket["protected"] = False
        solo_gami_exclusion_notes.append(
            f"{ticket['type']} {ticket['combo']}（{float(ticket.get('odds',0)):.1f}倍）を除外。"
            f"単独払戻{payout:.0f}円が除外前総額{current_cost:.0f}円を下回り、"
            f"単体期待値は{ev*100:.1f}%"
        )

    # Ver214: 単独ガミ除外後、2連単・2連複・3連複を削除して終わりにせず、
    # 同じ展開から派生する高期待値3連単へ1対1で置換した場合を再評価する。
    # 長期回収率・黒字的中率・ガミ率を同時比較し、改善する交換だけ自動採用する。
    cross_type_tri_swap_notes = []
    for _ in range(8):
        base_swap = evaluate(selected)
        best_cross_swap = None
        selected_now = {(t.get("type"), t.get("combo")) for t in selected}

        for old in list(selected):
            old_type = str(old.get("type", ""))
            if old_type not in {"2連単", "2連複", "3連複", "二連単", "二連複", "三連複"}:
                continue

            try:
                nums = tuple(int(x) for x in str(old.get("combo", "")).replace("=", "-").split("-") if str(x).strip())
            except Exception:
                continue

            related_combos = set()
            if old_type in {"2連単", "二連単"} and len(nums) == 2:
                a, b = nums
                for c in range(1, starter_count + 1):
                    if c not in (a, b):
                        related_combos.add(f"{a}-{b}-{c}")
            elif old_type in {"2連複", "二連複"} and len(nums) == 2:
                a, b = nums
                for c in range(1, starter_count + 1):
                    if c not in (a, b):
                        related_combos.add(f"{a}-{b}-{c}")
                        related_combos.add(f"{b}-{a}-{c}")
            elif old_type in {"3連複", "三連複"} and len(nums) == 3:
                import itertools as _itertools_v214
                for p in _itertools_v214.permutations(nums, 3):
                    related_combos.add("-".join(map(str, p)))

            if not related_combos:
                continue

            for cand in candidates:
                if str(cand.get("type", "")) not in {"3連単", "三連単"}:
                    continue
                if str(cand.get("combo", "")) not in related_combos:
                    continue
                if (cand.get("type"), cand.get("combo")) in selected_now or any(
                    str(t.get("type", "")) in {"3連単", "三連単"}
                    and str(t.get("combo", "")) == str(cand.get("combo", "")) for t in selected
                ):
                    continue

                odds = float(cand.get("odds", 0.0) or 0.0)
                probability = float(cand.get("probability", 0.0) or 0.0)
                standalone_ev = float(cand.get("ev_probability",probability) or probability) / 100.0 * odds
                if odds <= 0 or standalone_ev < 1.00:
                    continue

                swapped = [t for t in selected if t is not old] + [cand]
                sm = evaluate(swapped)
                return_gain = float(sm.get("model_return_rate", 0.0) - base_swap.get("model_return_rate", 0.0))
                black_delta = float(sm.get("black", 0.0) - base_swap.get("black", 0.0))
                gami_drop = float(base_swap.get("low", 0.0) - sm.get("low", 0.0))
                cover_loss = float(base_swap.get("cover", 0.0) - sm.get("cover", 0.0))
                avg_gain = float(sm.get("hit_average_multiple", 0.0) - base_swap.get("hit_average_multiple", 0.0))

                # 高配当化だけで的中範囲を壊さないよう、長期回収率の改善を必須にし、
                # 黒字率・ガミ率の悪化とカバー損失には上限を設ける。
                if return_gain < 0.50:
                    continue
                if black_delta < -0.35:
                    continue
                if gami_drop < -0.25:
                    continue
                if cover_loss > 3.0:
                    continue
                if avg_gain < -0.03:
                    continue

                old_odds = float(old.get("odds", 0.0) or 0.0)
                score = (
                    2.2 * return_gain + 1.4 * black_delta + 1.1 * gami_drop
                    - 0.35 * max(0.0, cover_loss) + 8.0 * max(0.0, avg_gain)
                    + 0.02 * max(0.0, odds - old_odds)
                )
                key = (score, return_gain, black_delta, gami_drop, -cover_loss, standalone_ev, odds)
                if best_cross_swap is None or key > best_cross_swap[0]:
                    best_cross_swap = (key, old, cand, swapped, sm, standalone_ev, cover_loss)

        if best_cross_swap is None or best_cross_swap[0][0] <= 0.0:
            break

        _, old, cand, selected, after_swap, standalone_ev, cover_loss = best_cross_swap
        cross_type_tri_swap_notes.append(
            f"{old['type']} {old['combo']}（{float(old.get('odds',0)):.1f}倍）を "
            f"3連単 {cand['combo']}（{float(cand.get('odds',0)):.1f}倍）へ置換。"
            f"参考回収率{base_swap['model_return_rate']:.1f}%→{after_swap['model_return_rate']:.1f}%・"
            f"黒字的中率{base_swap['black']:.2f}%→{after_swap['black']:.2f}%・"
            f"ガミ率{base_swap['low']:.2f}%→{after_swap['low']:.2f}%・"
            f"3連単単体期待値{standalone_ev*100:.1f}%"
        )

    replacement_notes.extend(cross_type_tri_swap_notes)

    # 置換後の最終構成を基準に追加候補を作り直す。
    base_for_residual = evaluate(selected)
    selected_ids = {(t.get("type"), t.get("combo")) for t in selected}
    residual_candidates = []
    selected_exacta = {tuple(int(x) for x in t["combo"].split("-")) for t in selected if t.get("type") in {"2連単", "二連単"}}
    selected_trio = {tuple(sorted(int(x) for x in t["combo"].split("-"))) for t in selected if t.get("type") in {"3連複", "三連複"}}
    selected_tris = [tuple(int(x) for x in t["combo"].split("-")) for t in selected if t.get("type") in {"3連単", "三連単"}]

    for cand in candidates:
        if cand.get("type") not in {"3連単", "三連単"} or (cand.get("type"), cand.get("combo")) in selected_ids:
            continue
        vals = tuple(int(x) for x in str(cand.get("combo", "")).split("-"))
        if len(vals) != 3:
            continue
        a, b, c = vals
        support = []
        if (a, b) in selected_exacta:
            support.append(f"2連単 {a}-{b}を3着まで延長")
        if tuple(sorted(vals)) in selected_trio:
            support.append(f"3連複 {'-'.join(map(str, sorted(vals)))}の着順候補")
        if any(x[0] == a and x[2] == c and x[1] != b for x in selected_tris):
            support.append(f"1着{a}・3着{c}の相手替わり")
        if any(x[0] == a and x[1] == b and x[2] != c for x in selected_tris):
            support.append(f"1・2着{a}-{b}の3着替わり")
        if len(support) < 2:
            continue

        probability = float(cand.get("probability", 0.0) or 0.0)
        odds = float(cand.get("odds", 0.0) or 0.0)
        standalone_ev = float(cand.get("ev_probability",probability) or probability) / 100.0 * odds
        add_metrics = evaluate(selected + [cand])
        cover_gain = add_metrics["cover"] - base_for_residual["cover"]
        black_gain = add_metrics["black"] - base_for_residual["black"]
        return_delta = add_metrics["model_return_rate"] - base_for_residual["model_return_rate"]
        low_delta = add_metrics["low"] - base_for_residual["low"]

        best_swap = None
        for old in selected:
            if old.get("type") == "三連単" and old.get("protected"):
                continue
            swapped = [t for t in selected if t is not old] + [cand]
            sm = evaluate(swapped)
            if sm["ev_model_return_rate"] + 0.01 < base_for_residual["ev_model_return_rate"]:
                continue
            if sm["black"] + 0.25 < base_for_residual["black"]:
                continue
            if sm["low"] > base_for_residual["low"] + 0.25:
                continue
            if sm["cover"] + 1.0 < base_for_residual["cover"]:
                continue
            key = (
                sm["black"] - base_for_residual["black"],
                sm["ev_model_return_rate"] - base_for_residual["ev_model_return_rate"],
                base_for_residual["low"] - sm["low"],
                sm["cover"] - base_for_residual["cover"],
            )
            if best_swap is None or key > best_swap[0]:
                best_swap = (key, old, sm)

        mode = None
        old_ticket = None
        comparison = add_metrics
        if best_swap is not None:
            mode = "入れ替え候補"
            old_ticket = best_swap[1]
            comparison = best_swap[2]
        elif (standalone_ev >= 1.00 and cover_gain >= 0.20
              and return_delta >= -3.0 and black_gain >= -1.0 and low_delta <= 1.5):
            mode = "余裕がある場合の追加候補"

        if mode:
            residual_candidates.append({
                "mode": mode, "ticket": cand, "replace": old_ticket,
                "support": support, "standalone_ev": standalone_ev * 100.0,
                "before": base_for_residual, "after": comparison,
                "score": (1 if mode == "入れ替え候補" else 0, standalone_ev, probability, odds),
            })

    residual_candidates.sort(key=lambda x: x["score"], reverse=True)
    residual_candidates = residual_candidates[:3]

    # Ver260: 画面・買い方の構成は従来のまま、券種をまたぐ完全重複だけを最終再評価する。
    # 例: 3連単で同じ3車の全着順をすでに覆っている場合の同一3連複、
    #     2連単表裏で同じ2車を覆っている場合の同一2連複。
    # 一律削除ではなく、100円均等買いの総額を含めたモデル回収率・黒字率・ガミ率を比較し、
    # 外しても的中範囲を失わず、成績が同等以上になる場合だけ除外する。
    v259_overlap_prune_notes = []
    for _ in range(10):
        before_overlap = evaluate(selected)
        best_overlap_remove = None
        for ticket in list(selected):
            if len(selected) <= 2:
                break
            trial_plan = [t for t in selected if t is not ticket]
            other_matched = set()
            for other in trial_plan:
                other_matched.update(other.get("matched", set()))
            own_matched = set(ticket.get("matched", set()))
            unique_indexes = own_matched - other_matched
            unique_prob = sum(float(outcomes[i][1]) for i in unique_indexes)
            if unique_prob > 0.01:
                continue

            after_overlap = evaluate(trial_plan)
            return_delta = float(after_overlap.get("model_return_rate", 0.0) - before_overlap.get("model_return_rate", 0.0))
            black_delta = float(after_overlap.get("black", 0.0) - before_overlap.get("black", 0.0))
            gami_delta = float(after_overlap.get("low", 0.0) - before_overlap.get("low", 0.0))
            cover_delta = float(after_overlap.get("cover", 0.0) - before_overlap.get("cover", 0.0))

            # 完全重複なのでカバーは原則不変。払戻の上乗せ価値が高ければ残す。
            # 回収率が明確に改善、またはほぼ同等で黒字率・ガミ率が悪化しない時だけ削る。
            acceptable = (
                return_delta >= 0.10
                or (
                    return_delta >= -0.05
                    and black_delta >= -0.05
                    and gami_delta <= 0.05
                    and cover_delta >= -0.01
                )
            )
            if not acceptable:
                continue

            prob = float(ticket.get("probability", 0.0) or 0.0)
            odds = float(ticket.get("odds", 0.0) or 0.0)
            standalone_ev = (float(ticket.get("ev_probability",prob) or prob) / 100.0) * odds
            key = (
                return_delta,
                black_delta,
                -gami_delta,
                -standalone_ev,
                odds,
            )
            if best_overlap_remove is None or key > best_overlap_remove[0]:
                best_overlap_remove = (
                    key, ticket, trial_plan, after_overlap, standalone_ev,
                    return_delta, black_delta, gami_delta
                )

        if best_overlap_remove is None:
            break

        (_, ticket, selected, after_overlap, standalone_ev,
         return_delta, black_delta, gami_delta) = best_overlap_remove
        ticket["protected"] = False
        v259_overlap_prune_notes.append(
            f"{ticket['type']} {ticket['combo']}（{float(ticket.get('odds',0)):.1f}倍）は他券で的中範囲を完全包含。"
            f"100円均等の最終比較で除外（単体期待値{standalone_ev*100:.1f}%、"
            f"参考回収率{before_overlap['model_return_rate']:.1f}%→{after_overlap['model_return_rate']:.1f}%、"
            f"黒字率差{black_delta:+.2f}pt、ガミ率差{gami_delta:+.2f}pt）。"
        )

    # Ver260: 完全重複を削った後は、減った点数を機械的には埋めない。
    # 未採用候補を1点ずつ100円均等で再評価し、現在構成より参考回収率が改善する候補だけを追加する。
    # 追加しても改善しない場合は、点数が減ったまま終了する。
    v260_refill_notes = []
    v260_removed_points = len(v259_overlap_prune_notes)
    for _ in range(v260_removed_points):
        before_refill = evaluate(selected)
        selected_ids_now = {(str(t.get("type")), str(t.get("combo"))) for t in selected}
        current_matched = set()
        for t in selected:
            current_matched.update(t.get("matched", set()))

        best_refill = None
        for cand in candidates:
            cid = (str(cand.get("type")), str(cand.get("combo")))
            if cid in selected_ids_now:
                continue

            # 既存構成に完全包含される券は、削除直後に戻さない。
            own_matched = set(cand.get("matched", set()))
            unique_indexes = own_matched - current_matched
            unique_prob = sum(float(outcomes[i][1]) for i in unique_indexes)
            if unique_prob <= 0.01:
                continue

            counts = before_refill.get("counts", {}) or {}
            if counts.get(cand.get("type"), 0) >= int(cand.get("cap", 99)):
                continue

            after_refill = evaluate(selected + [cand])
            return_delta = float(after_refill.get("model_return_rate", 0.0) - before_refill.get("model_return_rate", 0.0))
            black_delta = float(after_refill.get("black", 0.0) - before_refill.get("black", 0.0))
            gami_delta = float(after_refill.get("low", 0.0) - before_refill.get("low", 0.0))
            cover_delta = float(after_refill.get("cover", 0.0) - before_refill.get("cover", 0.0))
            probability = float(cand.get("probability", 0.0) or 0.0)
            odds = float(cand.get("odds", 0.0) or 0.0)
            standalone_ev = (float(cand.get("ev_probability",probability) or probability) / 100.0) * odds

            acceptable = (
                return_delta >= 0.05
                and black_delta >= -0.05
                and gami_delta <= 0.10
                and cover_delta >= 0.0
                and standalone_ev >= 0.95
            )
            if not acceptable:
                continue

            key = (return_delta, black_delta, cover_delta, -gami_delta, standalone_ev, unique_prob, odds)
            if best_refill is None or key > best_refill[0]:
                best_refill = (key, cand, after_refill, standalone_ev, unique_prob,
                               return_delta, black_delta, gami_delta, cover_delta)

        if best_refill is None:
            break

        (_, cand, after_refill, standalone_ev, unique_prob,
         return_delta, black_delta, gami_delta, cover_delta) = best_refill
        selected.append(cand)
        v260_refill_notes.append(
            f"{cand['type']} {cand['combo']}（{float(cand.get('odds',0)):.1f}倍）を次点から追加。"
            f"参考回収率{before_refill['model_return_rate']:.1f}%→{after_refill['model_return_rate']:.1f}% "
            f"（{return_delta:+.2f}pt）、黒字率{black_delta:+.2f}pt、ガミ率{gami_delta:+.2f}pt、"
            f"追加カバー{cover_delta:+.2f}pt、単体期待値{standalone_ev*100:.1f}%・固有カバー{unique_prob:.2f}%。"
        )

    metrics = evaluate(selected)
    calibration = _v195_return_calibration(engine.DB_PATH)
    adjusted_expected_multiple = float(metrics.get("model_expected_multiple", 0.0)) * float(calibration.get("factor", 1.0))
    adjusted_return_rate = adjusted_expected_multiple * 100.0
    metrics["adjusted_expected_multiple"] = adjusted_expected_multiple
    metrics["adjusted_return_rate"] = adjusted_return_rate
    metrics["return_calibration"] = calibration

    # 的中率だけでなく、的中時に黒字となる割合と実績補正後回収率を主軸に評価する。
    gami_share = float(metrics.get("gami_share_of_hits", 0.0))
    black_share = float(metrics.get("black_share_of_hits", 0.0))
    avg_multiple = float(metrics.get("hit_average_multiple", 0.0))
    expected_multiple = float(metrics.get("model_expected_multiple", 0.0))
    adjusted_multiple = float(metrics.get("adjusted_expected_multiple", expected_multiple))

    if adjusted_multiple >= 1.15 and avg_multiple >= 1.35 and black_share >= 68.0 and gami_share <= 25.0:
        multiple_grade = "実績補正後も回収率基準を超える"
    elif adjusted_multiple >= 1.00 and black_share >= 55.0:
        multiple_grade = "実績補正後100%前後"
    else:
        multiple_grade = "実績補正後100%未満"

    samples = int(calibration.get("samples", 0))
    if adjusted_multiple < 0.95 or metrics["black"] < 15.0 or gami_share >= 42.0 or avg_multiple < 1.05:
        grade, icon = "非推奨", "⛔"
        reason = (
            f"実績補正後の参考回収率は{adjusted_return_rate:.1f}%です。"
            "的中範囲があっても、長期的に購入総額を回収しにくい構成です。"
        )
    elif (adjusted_multiple >= 1.15 and metrics["diversity"] >= 2 and metrics["black"] >= 30.0
          and black_share >= 68.0 and gami_share <= 20.0 and avg_multiple >= 1.35
          and samples >= 15):
        grade, icon = "回収率基準を満たす", "✅"
        reason = (
            f"実績補正後の参考回収率が{adjusted_return_rate:.1f}%で、黒字的中率は{metrics['black']:.1f}%です。"
            "保存実績も15レース以上あるため、回収率100%以上を狙う候補として扱います。"
        )
    elif adjusted_multiple >= 1.00:
        grade, icon = "回収率100%候補・検証中", "△"
        reason = (
            f"実績補正後の参考回収率は{adjusted_return_rate:.1f}%です。"
            f"ただし現ロジックの評価可能実績が{samples}レースのため、まだ検証中です。"
        )
    else:
        grade, icon = "的中優先なら候補", "⚠️"
        reason = (
            f"モデル上は的中範囲がありますが、実績補正後の参考回収率は{adjusted_return_rate:.1f}%です。"
            "回収率100%以上を優先する場合は見送り寄りです。"
        )

    grouped = {}
    for ticket in selected:
        grouped.setdefault(ticket["type"], []).append(ticket)
    role_lines = []
    for ticket_type in ("三連単", "三連複", "2連単", "2連複"):
        rows = grouped.get(ticket_type, [])
        if rows:
            role_lines.append(f"{v205_ticket_display_name(ticket_type)}{len(rows)}点：{rows[0]['role']}")
    return {
        "available": True, "grade": grade, "icon": icon, "reason": reason,
        "multiple_grade": multiple_grade,
        "tickets": selected, "grouped": grouped, "role_lines": role_lines,
        "learning": learning, "pool_summary": pool_summary,
        "tri_seed_points": int(tri_seed_points),
        "replacement_notes": replacement_notes,
        "gami_prune_notes": gami_prune_notes,
        "v259_overlap_prune_notes": v259_overlap_prune_notes,
        "v260_refill_notes": v260_refill_notes,
        "low_odds_floor_notes": low_odds_floor_notes,
        "solo_gami_exclusion_notes": solo_gami_exclusion_notes,
        "protected_add_notes": protected_add_notes,
        "protected_count": len([t for t in selected if t.get("protected")]),
        "residual_trifecta_candidates": residual_candidates,
        "hard_race_info": hard_race_info,
        "tri_seed_cover": float(tri_seed_metrics.get("cover", 0.0)),
        "tri_seed_black": float(tri_seed_metrics.get("black", 0.0)),
        **metrics,
    }



def v205_ticket_display_name(ticket_type: str) -> str:
    """内部キーは変えず、画面とコピー欄だけ券種名を数字表記へ統一する。"""
    return {
        "三連単": "3連単",
        "三連複": "3連複",
        "2連単": "2連単",
        "2連複": "2連複",
        "ワイド": "ワイド",
        "単勝": "単勝",
        "複勝": "複勝",
    }.get(str(ticket_type), str(ticket_type))



def v207_build_mixed_formation_sections(result: dict):
    """回収率重視の最終買い目を、画面最上段で使えるコピー形式へ整形する。"""
    sections = []
    notes = []
    for ticket_type in ("三連単", "三連複", "2連単", "2連複", "ワイド", "単勝", "複勝"):
        rows = result.get("grouped", {}).get(ticket_type, []) or []
        combos = [str(r.get("combo", "")).strip() for r in rows if str(r.get("combo", "")).strip()]
        if not combos:
            continue
        if ticket_type in ("ワイド", "単勝", "複勝"):
            formations = combos
        else:
            try:
                formations = engine.v67_compress_formations(combos, ticket_type)
                if ticket_type == "三連単":
                    formations = v203_standard_trifecta_formations(formations, combos)
            except Exception as exc:
                formations = []
                notes.append(f"{v205_ticket_display_name(ticket_type)}: フォーメーション変換に失敗したため個別表記を使用（{exc}）")
            if not formations:
                formations = combos
                notes.append(f"{v205_ticket_display_name(ticket_type)}: 圧縮できない組み合わせは個別表記のまま出力")
        sections.append(
            f"{v205_ticket_display_name(ticket_type)} {len(combos)}点\n" + "\n".join(str(x) for x in formations)
        )
    return sections, notes


def v244_optional_single_wide_candidates(bets: dict, trials: int, odds_maps: dict) -> list[dict]:
    """単勝・複勝・ワイドは本線へ自動混入せず、余裕がある場合の候補として評価する。"""
    tri_counter = (bets or {}).get("三連単", {}) or {}
    if not tri_counter or int(trials or 0) <= 0:
        return []
    outcomes = []
    for combo, count in tri_counter.items():
        vals = tuple(int(v) for v in (tuple(combo) if isinstance(combo, (tuple, list)) else (combo,)))
        if len(vals) == 3:
            outcomes.append((vals, float(count) / max(int(trials), 1) * 100.0))
    if not outcomes:
        return []
    win_prob = {}
    place_prob = {}
    wide_prob = {}
    for (a, b, c), prob in outcomes:
        win_prob[a] = win_prob.get(a, 0.0) + prob
        # オートレースの複勝は1着または2着。三連単分布からそのまま集計する。
        place_prob[a] = place_prob.get(a, 0.0) + prob
        place_prob[b] = place_prob.get(b, 0.0) + prob
        for x, y in ((a, b), (a, c), (b, c)):
            key = "-".join(map(str, sorted((x, y))))
            wide_prob[key] = wide_prob.get(key, 0.0) + prob
    rows = []
    for car_text, odds in (odds_maps.get("tansho", {}) or {}).items():
        try:
            car = int(car_text); odd = float(odds); prob = float(win_prob.get(car, 0.0))
        except Exception:
            continue
        ev = prob / 100.0 * odd * 100.0
        if odd > 0 and prob >= 8.0 and ev >= 100.0:
            rows.append({"type":"単勝","combo":str(car),"probability":prob,"odds":odd,"ev":ev,
                         "reason":"1着確率と単勝オッズの組み合わせが100%以上"})
    for car_text, odds in (odds_maps.get("fukusho", {}) or {}).items():
        try:
            car = int(car_text); odd = float(odds); prob = float(place_prob.get(car, 0.0))
        except Exception:
            continue
        ev = prob / 100.0 * odd * 100.0
        # 複勝も範囲オッズの下限で安全側評価。
        if odd > 0 and prob >= 20.0 and ev >= 103.0:
            rows.append({"type":"複勝","combo":str(car),"probability":prob,"odds":odd,"ev":ev,
                         "reason":"2着内確率と複勝下限オッズで期待値103%以上"})
    for combo, odds in (odds_maps.get("wide", {}) or {}).items():
        try:
            odd = float(odds); prob = float(wide_prob.get(str(combo), 0.0))
        except Exception:
            continue
        ev = prob / 100.0 * odd * 100.0
        # ワイドはHTMLの下限オッズを使うため、判定はやや厳しめ。
        if odd > 0 and prob >= 18.0 and ev >= 105.0:
            rows.append({"type":"ワイド","combo":str(combo),"probability":prob,"odds":odd,"ev":ev,
                         "reason":"3着内ペア確率とワイド下限オッズで期待値105%以上"})
    rows.sort(key=lambda r:(float(r.get("ev",0)), float(r.get("probability",0))), reverse=True)
    # 同券種が並びすぎないよう最大3点。
    return rows[:3]

def v277_provisional_merge_7types(result: dict, bets: dict, trials: int, odds_maps: dict) -> dict:
    """Ver279: 単勝・複勝・ワイドを回収率重視プランへ暫定統合する。

    既存4券種の最適化結果を土台に、追加3券種は厳しめのEV条件を通過し、
    100円均等買いで合成モデル回収率を実際に改善する場合だけ最大2点追加する。
    予測確率そのものは変更しない。
    """
    if not isinstance(result, dict) or not result.get("available"):
        return result
    tri_counter = (bets or {}).get("三連単", {}) or {}
    if not tri_counter or int(trials or 0) <= 0:
        return result
    optional = v244_optional_single_wide_candidates(bets, trials, odds_maps)
    if not optional:
        result["provisional_7type_candidates"] = []
        result["provisional_7type_added"] = []
        return result

    outcomes = []
    total_trials = max(int(trials), 1)
    for combo, count in tri_counter.items():
        try:
            vals = tuple(int(v) for v in (tuple(combo) if isinstance(combo, (tuple, list)) else (combo,)))
        except Exception:
            continue
        if len(vals) == 3:
            outcomes.append((vals, float(count) / total_trials * 100.0))
    if not outcomes:
        return result

    def _nums(combo):
        return tuple(int(x) for x in re.findall(r"\d+", str(combo)))

    def _match(ticket, outcome):
        a, b, c = outcome
        typ = str(ticket.get("type") or "")
        nums = _nums(ticket.get("combo", ""))
        if typ in ("三連単", "3連単"):
            return nums == (a, b, c)
        if typ in ("三連複", "3連複"):
            return tuple(sorted(nums)) == tuple(sorted((a, b, c)))
        if typ in ("2連単", "二連単"):
            return nums == (a, b)
        if typ in ("2連複", "二連複"):
            return tuple(sorted(nums)) == tuple(sorted((a, b)))
        if typ == "単勝":
            return len(nums) == 1 and nums[0] == a
        if typ == "複勝":
            return len(nums) == 1 and nums[0] in (a, b)
        if typ == "ワイド":
            return len(nums) == 2 and set(nums).issubset({a, b, c})
        return False

    def _evaluate(plan):
        cost = len(plan) * 100.0
        cover = black = low = expected = 0.0
        hit_rows = []
        for outcome, prob in outcomes:
            payout = 0.0
            for t in plan:
                if _match(t, outcome):
                    payout += float(t.get("odds", 0.0) or 0.0) * 100.0
            if payout > 0:
                cover += prob
                expected += prob / 100.0 * payout
                hit_rows.append((payout, prob))
                if payout >= cost:
                    black += prob
                else:
                    low += prob
        if hit_rows and cost > 0 and cover > 0:
            avg_payout = expected / (cover / 100.0)
            avg_multiple = avg_payout / cost
            min_multiple = min(p / cost for p, _ in hit_rows)
            max_multiple = max(p / cost for p, _ in hit_rows)
        else:
            avg_payout = avg_multiple = min_multiple = max_multiple = 0.0
        expected_multiple = expected / cost if cost else 0.0
        return {
            "points": len(plan), "cost": cost, "cover": cover, "black": black, "low": low,
            "miss": max(0.0, 100.0-cover), "expected_return": expected,
            "model_return_rate": expected_multiple*100.0, "model_expected_multiple": expected_multiple,
            "hit_average_payout": avg_payout, "hit_average_multiple": avg_multiple,
            "hit_min_multiple": min_multiple, "hit_max_multiple": max_multiple,
            "black_share_of_hits": (black/cover*100.0 if cover>0 else 0.0),
            "gami_share_of_hits": (low/cover*100.0 if cover>0 else 0.0),
        }

    plan = [dict(t) for t in (result.get("tickets", []) or [])]
    before = _evaluate(plan)
    added = []
    used_types = set()
    for cand in optional:
        if len(added) >= 2:
            break
        typ = str(cand.get("type") or "")
        if typ in used_types:
            continue
        ticket = dict(cand)
        ticket["role"] = "暫定7券種・高EV補助"
        after = _evaluate(plan + [ticket])
        # 追加コスト込みで回収率が改善し、黒字的中率を大きく壊さない候補だけ採用。
        if (after["model_return_rate"] >= before["model_return_rate"] + 0.50
                and after["black"] >= before["black"] - 0.20):
            plan.append(ticket)
            added.append(ticket)
            used_types.add(typ)
            before = after

    result["provisional_7type_candidates"] = optional
    result["provisional_7type_added"] = added
    if not added:
        return result

    metrics = _evaluate(plan)
    result["tickets"] = plan
    grouped = {}
    for t in plan:
        grouped.setdefault(t.get("type"), []).append(t)
    result["grouped"] = grouped
    result.update(metrics)
    cal = result.get("return_calibration", {}) or {}
    factor = float(cal.get("factor", 1.0) or 1.0)
    result["adjusted_return_rate"] = float(metrics["model_return_rate"]) * factor
    role_lines = []
    for typ in ("三連単", "三連複", "2連単", "2連複", "ワイド", "単勝", "複勝"):
        rows = grouped.get(typ, []) or []
        if rows:
            role_lines.append(f"{v205_ticket_display_name(typ)}{len(rows)}点：{rows[0].get('role','')}")
    result["role_lines"] = role_lines
    return result

def _v305_supersede_plan_after_odds_refresh(
    db_path: str, race_key: str, app_version: str, new_plan_hash: str = ""
) -> None:
    """オッズ訂正時、同一レース・同一予測Verの現行プランを1つへ統一する。

    通常予測(live)だけでなく復元表示(source_version_restore /
    current_version_restore)も対象。過去行は削除せずinclude_in_live_stats=0へ退避する。
    """
    if not race_key:
        return
    _v187_ensure_mixed_learning_tables(db_path)
    now = datetime.now(_V228_JST).isoformat(timespec="microseconds")
    _ver305 = str(app_version or APP_VERSION)
    with sqlite3.connect(db_path, timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")

        # 同じレース・同じ予測Verは、生成経路に関係なく現行1プランだけにする。
        con.execute("""
            UPDATE v187_mixed_plan_runs
               SET include_in_live_stats=0
             WHERE race_key=?
               AND COALESCE(app_version,'')=?
               AND COALESCE(include_in_live_stats,1)=1
        """, (str(race_key), _ver305))

        if new_plan_hash:
            # 同一hashの再入力でもcreated_atを更新して訂正版を最新扱いにする。
            con.execute("""
                UPDATE v187_mixed_plan_runs
                   SET include_in_live_stats=1,
                       created_at=?
                 WHERE race_key=?
                   AND plan_hash=?
                   AND COALESCE(app_version,'')=?
            """, (now, str(race_key), str(new_plan_hash), _ver305))
        con.commit()


def show_v184_eight_car_mixed_plan(
    bets: dict, trials: int, meta: dict, odds_maps: dict, race_key: str = "",
    app_version: str | None = None, save_enabled: bool = True,
    plan_origin: str = "live", source_prediction_version: str | None = None,
    include_in_live_stats: bool = True,
) -> None:
    result = v184_eight_car_mixed_plan(bets, trials, meta, odds_maps)
    result = v277_provisional_merge_7types(result, bets, trials, odds_maps)
    # Ver300監査は継続。
    _rec_audit300 = _v300_recommendation_audit(result) if result.get("available") else {}
    # Ver305: 現行Verは4券種安定性ゲート。旧Ver復元は当時のVer301基準を維持。
    _rec_target_ver = str(app_version or APP_VERSION)
    if result.get("available"):
        # Ver309: Ver305基準の買い目生成と推奨判定を比較用に固定。
        # Ver307以前はAPP_VERSIONがVer305でないため、条件分岐だけでVer301へ落ちていた。
        # 現行版でもVer305のEV＋4券種支持条件をそのまま使用する。
        _live_rec301 = _v305_live_recommendation(result)
    else:
        _live_rec301 = {}
    starter_count = engine.v102_starter_count_for_meta(meta, engine.DB_PATH) or 0
    st.markdown(f"#### 🧩 {int(starter_count)}車向け・黒字的中重視の回収率合成")

    _odds_refresh_key305 = f"v305_odds_refresh_pending_{race_key}"
    _odds_refresh_pending305 = bool(
        race_key and st.session_state.get(_odds_refresh_key305) is not None
    )

    if not result.get("available"):
        # 訂正版オッズで「構成なし」になった場合、間違った旧プランを
        # 最新live実績として残さない。
        if (
            _odds_refresh_pending305
            and save_enabled
            and include_in_live_stats
        ):
            try:
                _v305_supersede_plan_after_odds_refresh(
                    engine.DB_PATH, str(race_key), str(app_version or APP_VERSION), ""
                )
            finally:
                st.session_state.pop(_odds_refresh_key305, None)
        st.caption(result.get("reason", "オッズを読み込むと表示します。"))
        return
    saved_hash = ""
    try:
        # Ver279: 復元表示でも後から入力したオッズのプランを保存する。
        # ただし plan_origin / include_in_live_stats でリアルタイム実績とは分離する。
        if save_enabled and race_key and str(race_key) != "current":
            saved_hash = _v187_save_mixed_plan(
                engine.DB_PATH, str(race_key), result, app_version=app_version,
                plan_origin=plan_origin,
                source_prediction_version=source_prediction_version,
                include_in_live_stats=include_in_live_stats,
            )
            if saved_hash and _rec_audit300:
                _save_audit301=dict(_rec_audit300)
                if _live_rec301:
                    _save_audit301["label"] = str(
                        _live_rec301.get("label")
                        or ("◎強推奨" if _live_rec301.get("recommended") else "見送り")
                    )
                    _save_audit301["score"] = (
                        10 if _live_rec301.get("recommended")
                        else (5 if _live_rec301.get("candidate") else 0)
                    )
                    _save_audit301["reasons"]=list(_save_audit301.get("reasons") or []) + [
                        "Ver305互換・安定性推奨: "
                        + str(_live_rec301.get("reason",""))
                    ]
                _v300_save_recommendation_audit(
                    engine.DB_PATH, str(race_key), str(saved_hash), _save_audit301,
                    app_version=(app_version or APP_VERSION),
                )

            if (
                _odds_refresh_pending305
                and include_in_live_stats
            ):
                _v305_supersede_plan_after_odds_refresh(
                    engine.DB_PATH, str(race_key),
                    str(app_version or APP_VERSION), str(saved_hash or "")
                )
                st.session_state.pop(_odds_refresh_key305, None)
    except Exception as exc:
        st.warning(f"合成プランをDBへ保存できませんでした: {exc}")

    # Ver207: ユーザーが主に見る最終買い目と一括コピーを、説明・監査・指標より先に表示する。
    hard_info = result.get("hard_race_info") or {}
    if hard_info.get("enabled"):
        pair = hard_info.get("top_pair") or (0, 0)
